-- Name: audit_personal_info(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.audit_personal_info() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_fields text[];
begin
  if auth.uid() is null then return new; end if;
  select coalesce(array_agg(n.key order by n.key), '{}')
    into v_fields
    from jsonb_each(to_jsonb(new)) n
    join jsonb_each(to_jsonb(old)) o using (key)
   where n.value is distinct from o.value
     and n.key not in ('updated_at', 'updated_by', 'complete');
  if cardinality(v_fields) = 0 then return new; end if;
  insert into public.audit_log(actor_id, action, entity, entity_id, after)
  values (auth.uid(), 'personal_info.update', 'employee_personal_info', new.employee_id,
          jsonb_build_object('fields', to_jsonb(v_fields)));
  return new;
end; $$;


--
-- Name: audit_row_change(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.audit_row_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_before jsonb;
  v_after  jsonb;
  v_id     uuid;
begin
  -- Migrations/seed run without an end-user identity and have their own change
  -- history. Avoid filling the runtime audit trail with actor-less replays.
  if auth.uid() is null then
    if tg_op = 'DELETE' then return old; end if;
    return new;
  end if;

  if tg_op <> 'INSERT' then v_before := to_jsonb(old); end if;
  if tg_op <> 'DELETE' then v_after := to_jsonb(new); end if;
  v_id := coalesce(
    nullif(v_after->>'id', '')::uuid,
    nullif(v_before->>'id', '')::uuid
  );

  insert into public.audit_log(actor_id, action, entity, entity_id, before, after)
  values (
    auth.uid(),
    lower(tg_op) || '_' || tg_table_name,
    tg_table_name,
    v_id,
    v_before,
    v_after
  );

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;


--
-- Name: audit_user_signature(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.audit_user_signature() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if auth.uid() is null then
    return coalesce(new, old);
  end if;
  insert into public.audit_log(actor_id, action, entity, entity_id, after)
  values (
    auth.uid(),
    case when tg_op = 'DELETE' then 'signature.deleted' else 'signature.saved' end,
    'user_signatures',
    coalesce(new.user_id, old.user_id),
    case when tg_op = 'DELETE' then null else jsonb_build_object('source', new.source) end
  );
  return coalesce(new, old);
end; $$;


