      or private.has_role(uid, 'manager')
      or private.has_role(uid, 'security')
      or private.has_role(uid, 'hr');
$$;


--
-- Name: FUNCTION can_read_all(uid uuid); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.can_read_all(uid uuid) IS 'Broad-read predicate: admin, manager, security, or hr. Write access is never implied — managers write only to direct reports, and hr writes only through guarded RPCs. FR-17/FR-18/FR-35.';


--
-- Name: can_read_approval_request(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.can_read_approval_request(p_uid uuid, p_request uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(private.is_active(p_uid) and exists (
    select 1 from public.leave_requests r join public.profiles p on p.id=p_uid and p.company_id=r.company_id
    where r.id=p_request and (r.employee_id=p_uid or private.is_manager_of(p_uid,r.employee_id)
      or private.has_perm(p_uid,'leave_requests','read')
      -- Review fix: approval authority grants a full-row read only while the request is
      -- pending, or for a request on which the caller recorded a decision (print/history).
      or exists (select 1 from public.leave_request_approvals a
        where a.request_id=r.id and a.approver_id=p_uid)
      or (r.status='pending' and (exists (select 1 from public.approval_steps s
        where private.can_approve_step(p_uid,r.id,s.id))
      or (not exists(select 1 from public.approval_steps s where s.company_id=r.company_id
        and s.active and r.kind=any(s.applies_to) and private.step_applies(s.manager_scope,r.employee_id))
        and private.approval_fallback_allowed(p_uid,r.id)))))),false);
$$;


--
-- Name: can_read_separation(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.can_read_separation(uid uuid, p_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.is_active(uid)
     and exists (
       select 1
         from public.separations s
         join public.profiles c on c.id = uid and c.company_id = s.company_id
        where s.id = p_id
          and (private.has_perm(uid, 'clearance', 'read')
               or s.employee_id = uid
               or exists (select 1 from public.separation_signoffs o
                           where o.separation_id = s.id and o.signer_id = uid))
     );
$$;


--
-- Name: can_reset_password(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.can_reset_password(p_caller uuid, p_target uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(private.is_admin(p_caller), false);
$$;


--
-- Name: ceo_delegate_configuration_ready(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.ceo_delegate_configuration_ready(p_ceo uuid, p_delegate uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.delegate_eligible(p_ceo,p_delegate) and not exists(
    select 1 from unnest(array['leave','errand']::public.request_kind[]) kind
    where not exists(select 1 from public.approval_steps s
      join public.profiles target on target.id=p_delegate and target.company_id=s.company_id
      where s.active and kind=any(s.applies_to) and private.step_applies(s.manager_scope,p_delegate)
        and not exists(select 1 from public.approval_executive_settings x where x.company_id=s.company_id
          and x.hr_head_id=p_delegate and s.id=any(x.hr_step_ids))
        and case when s.approver_id is not null then s.approver_id=p_ceo
          when s.role='manager' and s.manager_scope='department' then private.is_department_manager_of(p_ceo,p_delegate)
          when s.role='manager' then private.is_manager_of(p_ceo,p_delegate)
          else private.has_role(p_ceo,s.role) end));
$$;


--
-- Name: companies_seed_roles(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.companies_seed_roles() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform private.seed_company_roles(new.id);
  return new;
end $$;


--
-- Name: company_minutes_per_day(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.company_minutes_per_day(p_company_id uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select round(coalesce((
    select hours_per_day from public.work_settings where company_id = p_company_id limit 1
  ), 8) * 60)::int;
$$;


--
-- Name: create_employee_impl(uuid, text, uuid, uuid, uuid, text, text, text, public.app_role[], date, text, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.create_employee_impl(p_actor uuid, p_path text, p_company_id uuid, p_department_id uuid, p_manager_id uuid, p_personnel_no text, p_full_name text, p_password text, p_roles public.app_role[], p_hire_date date, p_language_pref text, p_calendar_pref text, p_job_title text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_uid       uuid := gen_random_uuid();
  v_pno       text := btrim(coalesce(p_personnel_no, ''));
  v_dept_code text;
  v_code      text;
  v_email     text;
  v_role      public.app_role;
begin
  if v_pno !~ '^[0-9]{1,10}$' then
    raise exception 'invalid personnel number (1-10 digits)' using errcode = '22023';
  end if;
  if length(coalesce(p_password, '')) < 8 then
    raise exception 'new password must be at least 8 characters' using errcode = '22023';
  end if;
  if coalesce(btrim(p_full_name), '') = '' then
    raise exception 'full name is required' using errcode = '22023';
  end if;
  if p_department_id is null then
    raise exception 'department is required' using errcode = '22023';
  end if;

  -- The department no longer feeds the code, but it must still exist and
  -- belong to this company: it scopes the team and defaults the manager.
  select code into v_dept_code
    from public.departments
   where id = p_department_id and company_id = p_company_id;
  if v_dept_code is null then
    raise exception 'department not found' using errcode = '22023';
  end if;

  v_code := v_pno;
  if exists (select 1 from public.profiles where company_id = p_company_id and personnel_no = v_pno) then
    raise exception 'personnel number already exists' using errcode = '23505';
  end if;
  -- employee_code uniqueness is GLOBAL, not per company. With bare numbers a
  -- second tenant's 1042 would collide; see the spec §6 for the multi-tenant
  -- cost this knowingly takes on.
  if exists (select 1 from public.profiles where employee_code = v_code) then
    raise exception 'employee code already exists' using errcode = '23505';
  end if;

  v_email := v_code || '@bj-app.internal';

  insert into auth.users (
    instance_id, id, aud, role, email, encrypted_password, email_confirmed_at,
    created_at, updated_at, raw_app_meta_data, raw_user_meta_data, is_sso_user, is_anonymous,
    confirmation_token, recovery_token, email_change_token_new, email_change,
    email_change_token_current, phone_change, phone_change_token, reauthentication_token
  ) values (
    '00000000-0000-0000-0000-000000000000', v_uid, 'authenticated', 'authenticated', v_email,
    extensions.crypt(p_password, extensions.gen_salt('bf')), now(), now(), now(),
    '{"provider":"email","providers":["email"]}'::jsonb, '{}'::jsonb, false, false,
    '', '', '', '', '', '', '', ''
  );

  insert into auth.identities (provider_id, user_id, identity_data, provider, last_sign_in_at, created_at, updated_at)
  values (v_uid::text, v_uid,
          jsonb_build_object('sub', v_uid::text, 'email', v_email, 'email_verified', true),
          'email', now(), now(), now());

  insert into public.profiles (id, company_id, employee_code, full_name, department_id, manager_id,
                               hire_date, language_pref, calendar_pref, personnel_no, job_title)
  values (v_uid, p_company_id, v_code, btrim(p_full_name), p_department_id, p_manager_id,
          p_hire_date, coalesce(p_language_pref, 'fa'), coalesce(p_calendar_pref, 'jalali'),
          v_pno, nullif(btrim(coalesce(p_job_title, '')), ''));

  foreach v_role in array p_roles loop
    insert into public.user_roles (user_id, role) values (v_uid, v_role) on conflict do nothing;
  end loop;

  insert into public.audit_log (actor_id, action, entity, entity_id, after)
  values (p_actor, 'create_employee', 'profiles', v_uid,
          jsonb_build_object('employee_code', v_code, 'personnel_no', v_pno,
                             'full_name', p_full_name, 'roles', to_jsonb(p_roles), 'path', p_path));

  return v_uid;
end; $_$;


--
-- Name: decide_approval_request(uuid, uuid, uuid, public.leave_status, text, boolean, boolean, bigint, text, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.decide_approval_request(p_id uuid, p_step_id uuid, p_actor uuid, p_decision public.leave_status, p_signature_data text, p_signature_authorized boolean, p_override boolean, p_per_diem_rials bigint, p_reason text, p_auto_authority uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r public.leave_requests%rowtype; s public.approval_steps%rowtype;
  d public.approval_delegations%rowtype; v_auth public.approval_delegations%rowtype;
  v_steps uuid[]; v_step uuid; v_total integer; v_admin boolean:=false; v_override boolean:=false;
  v_kind text; v_principal uuid; v_principal_name text; v_actor_name text; v_evidence jsonb;
  v_now timestamptz; v_filled_hr boolean:=false; v_note text:=nullif(btrim(p_reason),'');
begin
  select * into r from public.leave_requests where id=p_id;
  if r.id is null then raise exception 'request not found' using errcode='P0002'; end if;
  perform private.approval_lock(r.company_id);
  perform pg_advisory_xact_lock(hashtextextended('leave:'||r.employee_id::text,0));
  select * into r from public.leave_requests where id=p_id for update;
  v_now:=clock_timestamp();
  if r.status<>'pending' then raise exception 'only pending requests can be decided' using errcode='22023'; end if;
  if p_decision not in ('approved','rejected') then raise exception 'invalid decision' using errcode='22023'; end if;
  if length(v_note)>500 then raise exception 'rejection note is too long (max 500 characters)' using errcode='22023'; end if;
  if p_auto_authority is null then
    if not private.is_active(p_actor) or not exists (select 1 from public.profiles where id=p_actor and company_id=r.company_id) then
      raise exception 'not allowed to decide this request' using errcode='42501'; end if;
    v_admin:=private.is_admin(p_actor);
    select full_name into v_actor_name from public.profiles where id=p_actor;
    if p_decision='approved' then perform private.separation_check_signature(p_signature_data,p_signature_authorized); end if;
  else
    -- Automatic CEO-step approval at submission (only enroll_request_delegation calls this).
    select * into v_auth from public.approval_delegations where id=p_auto_authority;
    if p_actor is not null or p_decision<>'approved' or v_auth.id is null or not v_auth.ceo_authorized
      or v_auth.delegate_id is distinct from r.employee_id or r.signature_data is null or r.signature_consent_at is null
      or not exists (select 1 from public.approval_executive_settings x
        where x.company_id=r.company_id and x.ceo_id=v_auth.principal_id)
      or not exists (select 1 from private.effective_approval_delegate(v_auth.principal_id) e where e.id=v_auth.id)
      or not private.request_step_applies(p_id,p_step_id)
      or not private.natural_step_authority(v_auth.principal_id,p_id,p_step_id) then
      raise exception 'automatic CEO authority is no longer valid' using errcode='42501'; end if;
    if p_signature_data is not null or p_per_diem_rials is not null then
      raise exception 'automatic decisions cannot carry human signatures or per diem' using errcode='22023'; end if;
  end if;
  if p_per_diem_rials<0 then raise exception 'per diem must be 0 or more' using errcode='22023'; end if;
  select count(*) into v_total from public.approval_steps st where private.request_step_applies(p_id,st.id);
  if p_auto_authority is not null then v_steps:=array[p_step_id];
  elsif v_total=0 and not exists (select 1 from public.approval_steps st
    where st.company_id=r.company_id and st.active and r.kind=any(st.applies_to)
      and private.step_applies(st.manager_scope,r.employee_id)) then
    -- Legacy no-chain fallback; delegation remains approval-only and cannot sign own requests.
    if not (v_admin or private.is_manager_of(p_actor,r.employee_id)) then
      select g.* into d from public.profiles emp
        cross join lateral private.effective_approval_delegate(emp.manager_id) g
        where emp.id=r.employee_id and g.delegate_id=p_actor and r.employee_id<>p_actor
          and g.source_request_id is distinct from p_id and private.is_manager_of(g.principal_id,r.employee_id);
      if d.id is null then raise exception 'not allowed to decide this request' using errcode='42501'; end if;
    end if;
    v_steps:=array[null::uuid];
  else
    if p_step_id is not null then
      if not private.request_step_applies(p_id,p_step_id) then
        raise exception 'approval step is no longer applicable' using errcode='22023'; end if;
      if not private.can_approve_step(p_actor,p_id,p_step_id) and not v_admin then
        raise exception 'not allowed to decide this request' using errcode='42501'; end if;
      v_step:=p_step_id;
    else
      select st.id into v_step from public.approval_steps st
      where private.can_approve_step(p_actor,p_id,st.id) and not private.request_step_decided(p_id,st.id)
        order by st.step_order,st.id limit 1;
    end if;
    v_override:=v_admin and (coalesce(p_override,false) or v_step is null
      or not private.can_approve_step(p_actor,p_id,v_step));
    if v_override then
      select array_agg(st.id order by st.step_order,st.id) into v_steps from public.approval_steps st
        where private.request_step_applies(p_id,st.id) and not private.request_step_decided(p_id,st.id);
    elsif v_step is not null then v_steps:=array[v_step];
    else raise exception 'not allowed to decide this request' using errcode='42501'; end if;
  end if;
  if cardinality(coalesce(v_steps,'{}'))=0 then raise exception 'you have already signed this request' using errcode='22023'; end if;
  foreach v_step in array v_steps loop
    s:=null;
    if v_step is not null then select * into s from public.approval_steps where id=v_step;
      if private.request_step_decided(p_id,s.id) then
        raise exception 'you have already signed this request' using errcode='22023'; end if;
      if p_auto_authority is null and not v_override and p_decision='approved'
        and exists (select 1 from public.work_settings w where w.company_id=r.company_id and w.approval_order_enforced)
        and exists (select 1 from public.approval_steps prev where private.request_step_applies(p_id,prev.id)
          and prev.step_order<s.step_order and not private.request_step_decided(p_id,prev.id,'approved')) then
        raise exception 'an earlier approval is still required' using errcode='22023'; end if;
    end if;
    v_evidence:='{}';
    if p_auto_authority is not null then
      v_kind:='automatic'; v_principal:=v_auth.principal_id; v_principal_name:=v_auth.principal_name;
      v_evidence:=jsonb_build_object('authority_id',v_auth.id,'principal_name',v_auth.principal_name,
        'delegate_id',v_auth.delegate_id,'delegate_name',v_auth.delegate_name,'consent_at',r.signature_consent_at,
        'submitted_at',r.created_at,'processed_at',v_now,'statement',
        'Automatically approved at submission under delegated CEO authority. The appointed delegate accepted responsibility under the recorded authorization.');
    else
      if v_step is not null then
        d:=null;
        if not v_override and not private.natural_step_authority(p_actor,p_id,v_step) then
          select g.* into d from private.step_delegation(p_actor,p_id,v_step) g;
        end if;
      end if;
      if d.id is not null then v_kind:='delegated';v_principal:=d.principal_id;v_principal_name:=d.principal_name;
      else v_kind:='manual';v_principal:=p_actor;v_principal_name:=v_actor_name; end if;
      v_evidence:=jsonb_build_object('admin_override',v_override,'actor_id',p_actor,
        'principal_id',v_principal,'principal_name',v_principal_name,'signer_name',v_actor_name);
    end if;
    v_filled_hr:=v_filled_hr or coalesce(s.role='hr',false);
    insert into public.leave_request_approvals(request_id,step_id,step_role,approver_id,decision,
      signature_data,signature_consent_at,note,evidence_kind,principal_id,principal_name,signer_name_snapshot,authority_id,evidence,created_at)
    values(p_id,v_step,coalesce(s.role,'manager'),p_actor,p_decision,
      case when p_decision='approved' then p_signature_data end,
      case when p_decision='approved' and p_signature_data is not null then v_now end,
      v_note,v_kind,v_principal,v_principal_name,v_actor_name,
      case when p_auto_authority is not null then p_auto_authority else d.id end,
      v_evidence||jsonb_build_object('step_id',v_step,'step_role',coalesce(s.role,'manager'),
        'step_order',coalesce(s.step_order,1),'manager_scope',coalesce(s.manager_scope,'direct'),
        'named',s.approver_id is not null,'approver_id',s.approver_id,
        'expected_name',case when s.approver_id is not null then
          (select full_name from public.profiles where id=s.approver_id) else v_principal_name end),v_now);
    if p_decision='rejected' then exit; end if;
  end loop;
  if p_decision='rejected' then
    update public.leave_requests set status='rejected',decided_by=p_actor,decided_at=v_now,decision_note=v_note where id=p_id and status='pending';
  else
    if p_per_diem_rials is not null then
      if r.kind<>'errand' or not v_filled_hr then
        raise exception 'per diem can only be set on the hr step of an errand' using errcode='22023'; end if;
      update public.leave_requests set per_diem_rials=p_per_diem_rials where id=p_id;
    end if;
    perform private.finalize_approval_request(p_id,p_actor,p_signature_data,v_now,
      case when p_auto_authority is not null then 'automatic' else v_kind end);
  end if;
  insert into public.audit_log(actor_id,action,entity,entity_id,after) values
    (p_actor,case when p_decision='approved' then 'approve_leave_step' else 'reject_leave_request' end,
     'leave_requests',p_id,jsonb_build_object('step_ids',v_steps,'evidence_kind',v_kind,'admin_override',v_override,
       'authority_id',p_auto_authority,'per_diem_rials',p_per_diem_rials));
end; $$;


--
-- Name: delegate_eligible(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.delegate_eligible(p_principal uuid, p_delegate uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(p_principal <> p_delegate
    and private.has_perm(p_principal,'approval_delegate','edit')
    and private.natural_approver(p_principal) and private.natural_approver(p_delegate)
    and exists (select 1 from public.profiles p join public.profiles d on d.company_id=p.company_id
      where p.id=p_principal and d.id=p_delegate and p.active and d.active
      and (not exists (select 1 from public.approval_executive_settings x
                        where x.company_id=p.company_id and x.ceo_id=p_principal)
           or d.manager_id=p_principal)),false);
$$;


--
-- Name: department_manager_for(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.department_manager_for(p_emp uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select d.manager_id
    from public.profiles p
    join public.departments d on d.id = p.department_id
    join public.profiles m on m.id = d.manager_id and m.active
   where p.id = p_emp;
$$;


--
-- Name: department_step_applies(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.department_step_applies(p_emp uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select x.dm is not null
     and x.dm <> p_emp
     and x.dm is distinct from (select manager_id from public.profiles where id = p_emp)
    from (select private.department_manager_for(p_emp) as dm) x;
$$;


SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: approval_delegations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.approval_delegations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    principal_id uuid NOT NULL,
    delegate_id uuid NOT NULL,
    principal_name text NOT NULL,
    delegate_name text NOT NULL,
    source_request_id uuid,
    starts_at timestamp with time zone,
    ends_at timestamp with time zone,
    activated_at timestamp with time zone,
    ceo_authorized boolean DEFAULT false NOT NULL,
    configured_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    revoked_at timestamp with time zone,
    CONSTRAINT approval_delegation_not_self CHECK ((principal_id <> delegate_id)),
    CONSTRAINT approval_delegation_window CHECK ((((source_request_id IS NULL) AND (starts_at IS NULL) AND (ends_at IS NULL)) OR ((source_request_id IS NOT NULL) AND (starts_at IS NOT NULL) AND (ends_at > starts_at))))
);


--
-- Name: effective_approval_delegate(uuid, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.effective_approval_delegate(p_principal uuid, p_at timestamp with time zone DEFAULT clock_timestamp()) RETURNS SETOF public.approval_delegations
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_count integer;
begin
  select count(*) into v_count from public.approval_delegations d
    join public.leave_requests r on r.id=d.source_request_id
    where d.principal_id=p_principal and d.revoked_at is null and r.status='approved'
      and d.starts_at<=p_at and p_at<d.ends_at and private.delegate_eligible(p_principal,d.delegate_id);
  -- An ambiguous legacy overlap never silently picks a person or falls back to a saved grant.
  if v_count>1 then return; end if;
  if v_count=1 then
    return query select d.* from public.approval_delegations d
      join public.leave_requests r on r.id=d.source_request_id
      where d.principal_id=p_principal and d.revoked_at is null and r.status='approved'
        and d.starts_at<=p_at and p_at<d.ends_at and private.delegate_eligible(p_principal,d.delegate_id);
  else
    return query select d.* from public.approval_delegations d
      where d.principal_id=p_principal and d.source_request_id is null and d.revoked_at is null
        and private.delegate_eligible(p_principal,d.delegate_id);
  end if;
end; $$;


--
-- Name: enforce_department_update_scope(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enforce_department_update_scope() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
begin
  if new.manager_id is not null
     and (tg_op = 'INSERT' or new.manager_id is distinct from old.manager_id)
     and not exists (
       select 1 from public.profiles where id = new.manager_id and company_id = new.company_id
     )
  then
    raise exception 'department manager must belong to the same company' using errcode = '22023';
  end if;

  -- FR-55 D7: a non-admin never appoints themselves (any department, insert or update).
  if not private.is_admin(v_uid) and new.manager_id = v_uid
     and (tg_op = 'INSERT' or new.manager_id is distinct from old.manager_id) then
    raise exception 'you cannot appoint yourself department manager' using errcode = '42501';
  end if;

  if tg_op = 'INSERT' or private.is_admin(v_uid) then
    return new;
  end if;

  if (new.id         is distinct from old.id)
     or (new.company_id is distinct from old.company_id)
     or (new.code       is distinct from old.code)
     or (new.kind       is distinct from old.kind)
     or (new.created_at is distinct from old.created_at)
  then
    raise exception 'not permitted to modify restricted department fields' using errcode = '42501';
  end if;

  if new.manager_id is distinct from old.manager_id
     and exists (select 1 from public.profiles where id = v_uid and department_id = old.id)
  then
    raise exception 'you cannot change the manager of your own department' using errcode = '42501';
  end if;

  return new;
end; $$;


--
-- Name: enforce_profile_update_scope(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enforce_profile_update_scope() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid     uuid := auth.uid();
  v_allowed text[];
begin
  if coalesce(current_setting('bj.separation_apply', true), '') = 'on'
     and old.active and not new.active
     and (to_jsonb(new) - 'active') = (to_jsonb(old) - 'active')
  then
    return new;
  end if;

  if private.is_admin(v_uid) then
    return new;  -- admins may change anything
  end if;

  if new.id = v_uid then
    v_allowed := array['full_name', 'language_pref', 'calendar_pref'];
  elsif private.has_perm(v_uid, 'people', 'edit')
        -- FR-55 D4: same company, never an admin (even a deactivated one, so an
        -- editor cannot reactivate one), and nothing the editor does not hold.
        and private.can_act_on(v_uid, old.id)
  then
    v_allowed := array['full_name', 'hire_date', 'department_id', 'manager_id', 'job_title', 'active'];
  elsif private.is_manager_of(v_uid, new.id) then
    v_allowed := array['full_name', 'hire_date'];
  else
    -- Password resets are the admin's alone (20261013200007).
    raise exception 'not permitted to update this profile' using errcode = '42501';
  end if;

  if (new.id            is distinct from old.id)
     or (new.company_id    is distinct from old.company_id)
     or (new.employee_code is distinct from old.employee_code)
     or (new.personnel_no  is distinct from old.personnel_no)
     or (new.created_at    is distinct from old.created_at)
     or (new.must_change_password is distinct from old.must_change_password
         and coalesce(current_setting('bj.password_flag_write', true), '') <> 'on')
     or (new.full_name     is distinct from old.full_name     and not ('full_name'     = any (v_allowed)))
     or (new.hire_date     is distinct from old.hire_date     and not ('hire_date'     = any (v_allowed)))
     or (new.department_id is distinct from old.department_id and not ('department_id' = any (v_allowed)))
     or (new.manager_id    is distinct from old.manager_id    and not ('manager_id'    = any (v_allowed)))
     or (new.job_title     is distinct from old.job_title     and not ('job_title'     = any (v_allowed)))
     or (new.active        is distinct from old.active        and not ('active'        = any (v_allowed)))
     or (new.language_pref is distinct from old.language_pref and not ('language_pref' = any (v_allowed)))
     or (new.calendar_pref is distinct from old.calendar_pref and not ('calendar_pref' = any (v_allowed)))
  then
    raise exception 'not permitted to modify restricted profile fields' using errcode = '42501';
  end if;

  return new;
end; $$;


--
-- Name: enforce_work_settings_scope(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enforce_work_settings_scope() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
begin
  -- Direct SQL (migrations, superuser) has no JWT and is not limited.
  if v_uid is null or private.is_admin(v_uid) then
    return new;
  end if;
  if tg_op = 'INSERT' then
    if new.hours_per_day is distinct from 8 then
      raise exception 'only an admin may change the hours per day' using errcode = '42501';
    end if;
    if new.approval_order_enforced is distinct from false
       and not private.has_perm(v_uid, 'approval_steps', 'edit') then
      raise exception 'not allowed to change the approval order setting' using errcode = '42501';
    end if;
  else
    if new.hours_per_day is distinct from old.hours_per_day then
      raise exception 'only an admin may change the hours per day' using errcode = '42501';
    end if;
    if new.approval_order_enforced is distinct from old.approval_order_enforced
       and not private.has_perm(v_uid, 'approval_steps', 'edit') then
      raise exception 'not allowed to change the approval order setting' using errcode = '42501';
    end if;
  end if;
  return new;
end; $$;


--
-- Name: enroll_request_delegation(uuid, boolean, jsonb, boolean); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enroll_request_delegation(p_request uuid, p_auto_consent boolean, p_preview jsonb, p_temporary_ceo_authorized boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r public.leave_requests%rowtype; x public.approval_executive_settings%rowtype;
  d public.approval_delegations%rowtype; v_preview jsonb; v_bounds jsonb; v_steps uuid[];
  v_step uuid; v_temp uuid;
begin
  select * into r from public.leave_requests where id=p_request;
  perform private.approval_lock(r.company_id);
  select * into r from public.leave_requests where id=p_request;
  v_preview:=public.app_request_delegation_preview(r.start_date,r.end_date,r.unit,r.day_part,
    r.start_time,r.end_time,r.replacement_id);
  if p_preview is not null and p_preview->>'preview_token' is distinct from v_preview->>'preview_token' then
    raise exception 'delegation preview changed; refresh the request preview' using errcode='22023'; end if;
  if r.day_part<>'full' and private.has_perm(r.employee_id,'approval_delegate','edit')
      and r.replacement_id is not null and private.delegate_eligible(r.employee_id,r.replacement_id)
      and p_preview is null then
    raise exception 'delegation preview required; refresh the request preview' using errcode='22023'; end if;
  v_bounds:=v_preview->'bounds';
  select * into x from public.approval_executive_settings where company_id=r.company_id;
  insert into public.approval_request_policy(request_id,company_id,starts_at,ends_at,hr_head_id,
    hr_exempt_step_ids,step_snapshot)
  values(r.id,r.company_id,(v_bounds->>'starts_at')::timestamptz,(v_bounds->>'ends_at')::timestamptz,
    x.hr_head_id,case when r.employee_id=x.hr_head_id then coalesce((select array_agg(s.id)
      from public.approval_steps s where s.company_id=r.company_id and s.active
        and s.id=any(x.hr_step_ids) and r.kind=any(s.applies_to)
        and private.step_applies(s.manager_scope,r.employee_id)),'{}') else '{}'::uuid[] end,
    private.approval_step_snapshot(r.id));
  if r.replacement_id is not null and private.delegate_eligible(r.employee_id,r.replacement_id) then
    if r.employee_id=x.ceo_id and p_temporary_ceo_authorized is not true then
      raise exception 'temporary CEO delegation authorization required' using errcode='22023'; end if;
    if r.employee_id=x.ceo_id and not private.ceo_delegate_configuration_ready(r.employee_id,r.replacement_id) then
      raise exception 'CEO must naturally own applicable approval steps for leave and errand before automatic authority is authorized' using errcode='22023'; end if;
    if exists (select 1 from public.approval_delegations g join public.leave_requests lr on lr.id=g.source_request_id
      where g.principal_id=r.employee_id and g.revoked_at is null and lr.status in ('pending','approved')
        and g.starts_at<(v_bounds->>'ends_at')::timestamptz and g.ends_at>(v_bounds->>'starts_at')::timestamptz) then
      raise exception 'overlapping temporary approval delegation' using errcode='22023'; end if;
    insert into public.approval_delegations(company_id,principal_id,delegate_id,principal_name,
      delegate_name,source_request_id,starts_at,ends_at,ceo_authorized,configured_by)
    select r.company_id,r.employee_id,r.replacement_id,p.full_name,q.full_name,r.id,
      (v_bounds->>'starts_at')::timestamptz,(v_bounds->>'ends_at')::timestamptz,
      -- Separate explicit attestation; the generic requester PNG does not authorize this policy.
      r.employee_id=x.ceo_id and p_temporary_ceo_authorized is true,r.employee_id from public.profiles p,public.profiles q
      where p.id=r.employee_id and q.id=r.replacement_id returning id into v_temp;
  end if;
  select g.* into d from private.effective_approval_delegate(x.ceo_id) g
    where g.delegate_id=r.employee_id and g.ceo_authorized;
  if d.id is not null then
    if p_auto_consent is not true or r.signature_data is null or r.signature_consent_at is null then
      raise exception 'CEO automatic approval responsibility consent required; refresh the request form' using errcode='22023'; end if;
    select array_agg(s.id order by s.step_order,s.id) into v_steps from public.approval_steps s
      where private.request_step_applies(r.id,s.id) and private.natural_step_authority(x.ceo_id,r.id,s.id);
    if cardinality(coalesce(v_steps,'{}'))=0 then
      raise exception 'CEO has no natural applicable approval step; correct executive approval configuration' using errcode='22023'; end if;
    -- Approved at once, before any earlier step (HR still signs separately). The last step to be
    -- approved finalizes the request, so stop once it is no longer pending.
    foreach v_step in array v_steps loop
      exit when (select status from public.leave_requests where id=r.id)<>'pending';
      if not private.request_step_decided(r.id,v_step) then
        perform private.decide_approval_request(r.id,v_step,null,'approved',null,false,false,null,null,d.id);
      end if;
    end loop;
  elsif p_auto_consent then
    raise exception 'CEO automatic approval authority changed; refresh the request preview' using errcode='22023';
  end if;
end; $$;


--
-- Name: finalize_approval_request(uuid, uuid, text, timestamp with time zone, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.finalize_approval_request(p_id uuid, p_actor uuid, p_signature text, p_consent_at timestamp with time zone, p_origin text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r public.leave_requests%rowtype; v_affects boolean; v_is_paid boolean;
  v_prev integer:=0; v_paid integer:=0; v_unpaid integer:=0;
begin
  select * into r from public.leave_requests where id=p_id;
  perform private.approval_lock(r.company_id);
  perform pg_advisory_xact_lock(hashtextextended('leave:'||r.employee_id::text,0));
  select * into r from public.leave_requests where id=p_id for update;
  if r.status<>'pending' then return false; end if;
  if exists (select 1 from public.approval_steps s where private.request_step_applies(p_id,s.id)
    and not private.request_step_decided(p_id,s.id,'approved')) then return false; end if;
  if exists (select 1 from public.leave_requests lr where lr.employee_id=r.employee_id and lr.id<>r.id
    and lr.status='approved' and lr.start_date<=r.end_date and lr.end_date>=r.start_date
    and (lr.unit='day' or r.unit='day' or (lr.start_time<r.end_time and lr.end_time>r.start_time))) then
    raise exception 'overlapping approved leave exists' using errcode='22023'; end if;
  if r.replacement_id is not null and private.replacement_is_away(r.replacement_id,r.start_date,r.end_date,
    r.unit,r.start_time,r.end_time) then raise exception 'replacement is on leave during this period' using errcode='22023'; end if;
  select affects_balance,is_paid into v_affects,v_is_paid from public.leave_types where id=r.leave_type_id;
  if v_affects then
    v_prev:=public.current_leave_balance(r.employee_id,r.leave_type_id);
    v_paid:=least(r.requested_minutes,greatest(v_prev,0)); v_unpaid:=r.requested_minutes-v_paid;
  elsif r.leave_type_id is not null and not coalesce(v_is_paid,false) then v_unpaid:=r.requested_minutes; end if;
  update public.leave_requests set status='approved',unpaid_minutes=v_unpaid,decided_by=p_actor,
    decided_at=clock_timestamp(),approver_signature_data=p_signature,
    approver_signature_consent_at=case when p_signature is null then null else p_consent_at end
    where id=p_id and status='pending';
  if not found then return false; end if;
  if v_affects and v_paid>0 then
    insert into public.leave_ledger(employee_id,leave_type_id,request_id,entry_type,delta_minutes,balance_after_minutes,note)
    values(r.employee_id,r.leave_type_id,p_id,'consumption',-v_paid,v_prev-v_paid,'paid portion consumed on approval');
  end if;
  insert into public.audit_log(actor_id,action,entity,entity_id,after) values
    (p_actor,'approve_leave_request','leave_requests',p_id,jsonb_build_object('employee_id',r.employee_id,
      'requested_minutes',r.requested_minutes,'paid_minutes',v_paid,'unpaid_minutes',v_unpaid,
      'replacement_id',r.replacement_id,'origin',p_origin));
  return true;
end; $$;


--
-- Name: has_perm(uuid, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.has_perm(uid uuid, p_key text, p_level text DEFAULT 'edit'::text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(private.is_active(uid)
     and private.perm_level(uid, p_key) >= case p_level when 'edit' then 2 when 'read' then 1 end, false);
$$;


--
-- Name: has_permission(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.has_permission(uid uuid, p_permission text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case p_permission
    when 'employees.edit'     then private.has_perm(uid, 'people', 'edit')
    when 'departments.edit'   then private.has_perm(uid, 'departments', 'edit')
    when 'accruals.run'       then private.has_perm(uid, 'leave_accrual', 'edit')
    when 'roles.manager'      then private.has_perm(uid, 'role_manager', 'edit')
    when 'personal_info.view' then private.has_perm(uid, 'personal_info', 'read')
    when 'personal_info.edit' then private.has_perm(uid, 'personal_info', 'edit')
    when 'personal_info.edit_own' then private.has_perm(uid, 'personal_info_own', 'edit')
    when 'special_leave.grant' then private.has_perm(uid, 'special_leave', 'edit')
    when 'separations.manage' then private.has_perm(uid, 'clearance', 'edit')
    when 'separations.view'   then private.has_perm(uid, 'clearance', 'read')
    when 'settings.edit'      then private.has_perm(uid, 'work_settings', 'edit')
                                   and private.has_perm(uid, 'holidays', 'edit')
    when 'absences.view'      then private.has_perm(uid, 'absences', 'read')
    when 'finance.view'       then private.has_perm(uid, 'finance', 'read')
    else false
  end;
$$;


--
-- Name: has_role(uuid, public.app_role); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.has_role(uid uuid, r public.app_role) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.is_active(uid)
     and exists (
       select 1
         from public.user_roles
        where user_id = uid
          and role = r
     );
$$;


--
-- Name: is_active(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.is_active(uid uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
      from public.profiles
     where id = uid
       and active
  );
$$;


--
-- Name: is_admin(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.is_admin(uid uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.has_role(uid, 'admin');
$$;


--
-- Name: is_company_weekend(uuid, date); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.is_company_weekend(p_company_id uuid, p_date date) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_weekly   int[];
  v_biweekly int[];
  v_anchor   date;
  v_dow      int;
begin
  if p_date is null then return false; end if;

  select coalesce(weekend_days, '{5}'),
         coalesce(biweekly_weekend_days, '{}'),
         biweekly_anchor
    into v_weekly, v_biweekly, v_anchor
    from public.work_settings
   where company_id = p_company_id
   limit 1;

  -- No settings row: same fallback the callers have always used (Friday only).
  if v_weekly is null then
    v_weekly := '{5}';
    v_biweekly := '{}';
  end if;

  v_dow := extract(isodow from p_date)::int;

  if v_dow = any(v_weekly) then
    return true;
  end if;

  if v_anchor is null or array_length(v_biweekly, 1) is null then
    return false;
  end if;

  if v_dow <> all(v_biweekly) then
    return false;
  end if;

  -- Whole weeks between the two dates' week buckets, on a Saturday-aligned grid.
  -- floor() division matters: `/` on integers truncates toward zero in Postgres,
  -- so a date BEFORE the epoch would bucket wrongly without it. The epoch is far
  -- in the past, but relying on that is the kind of assumption that breaks once.
  return mod(
           abs(
             floor((p_date  - date '2000-01-01') / 7.0)::int
             - floor((v_anchor - date '2000-01-01') / 7.0)::int
           ),
           2
         ) = 0;
end;
$$;


--
-- Name: FUNCTION is_company_weekend(p_company_id uuid, p_date date); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.is_company_weekend(p_company_id uuid, p_date date) IS 'FR-41: single source of truth for "is this date a non-working weekend day for this company". Mirrored in lib/leave/weekend.ts.';


--
-- Name: is_department_manager_of(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.is_department_manager_of(p_uid uuid, p_emp uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p_uid is not null
     and private.is_active(p_uid)
     and private.department_manager_for(p_emp) = p_uid;
$$;


--
-- Name: is_manager_of(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.is_manager_of(uid uuid, target uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.has_role(uid, 'manager')
     and exists (
       select 1
         from public.profiles caller
         join public.profiles employee
           on employee.id = target
          and employee.company_id = caller.company_id
        where caller.id = uid
          and employee.manager_id = uid
     );
$$;


--
-- Name: is_valid_card_no(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.is_valid_card_no(p text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare
  v_sum int := 0;
  v_d   int;
begin
  if p is null or p !~ '^[0-9]{16}$' then return false; end if;
  for i in 1..16 loop
    v_d := substr(p, i, 1)::int;
    if i % 2 = 1 then            -- 16 digits: odd positions from the left are doubled
      v_d := v_d * 2;
      if v_d > 9 then v_d := v_d - 9; end if;
    end if;
    v_sum := v_sum + v_d;
  end loop;
  return v_sum % 10 = 0;
end; $_$;


--
-- Name: is_valid_national_id(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.is_valid_national_id(p text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare
  v_sum int := 0;
  v_rem int;
  v_chk int;
begin
  if p is null or p !~ '^[0-9]{10}$' then return false; end if;
  -- All-same-digit numbers pass the arithmetic but are never issued.
  if p ~ '^(.)\1{9}$' then return false; end if;
  for i in 1..9 loop
    v_sum := v_sum + substr(p, i, 1)::int * (11 - i);
  end loop;
  v_rem := v_sum % 11;
  v_chk := substr(p, 10, 1)::int;
  return (v_rem < 2 and v_chk = v_rem) or (v_rem >= 2 and v_chk = 11 - v_rem);
end; $_$;


--
-- Name: is_valid_sheba(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.is_valid_sheba(p text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare
  v_digits text;
  v_rem    int := 0;
begin
  if p is null or p !~ '^IR[0-9]{24}$' then return false; end if;
  v_digits := substr(p, 5) || '1827' || substr(p, 3, 2);
  for i in 1..length(v_digits) loop
    v_rem := (v_rem * 10 + substr(v_digits, i, 1)::int) % 97;
  end loop;
  return v_rem = 1;
end; $_$;


--
-- Name: natural_approver(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.natural_approver(p_uid uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(private.is_active(p_uid) and (
    private.has_role(p_uid,'manager') or private.is_admin(p_uid)
    or exists (select 1 from public.departments d where d.manager_id=p_uid)
    or exists (select 1 from public.approval_steps s
      join public.profiles p on p.id=p_uid and p.company_id=s.company_id
      where s.active and (s.approver_id=p_uid
        or (s.approver_id is null and s.role <> 'manager' and private.has_role(p_uid,s.role))))),false);
$$;


--
-- Name: natural_step_authority(uuid, uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.natural_step_authority(p_uid uuid, p_request uuid, p_step uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(exists (select 1 from public.leave_requests r
    join public.profiles p on p.id=p_uid and p.company_id=r.company_id and p.active
    join public.approval_steps s on s.id=p_step and s.company_id=r.company_id and s.active
      and r.kind=any(s.applies_to) and private.step_applies(s.manager_scope,r.employee_id)
    where r.id=p_request and r.employee_id<>p_uid and
      case when s.approver_id is not null then s.approver_id=p_uid
      when s.role='manager' and s.manager_scope='department'
        then private.is_department_manager_of(p_uid,r.employee_id)
      when s.role='manager' then private.is_manager_of(p_uid,r.employee_id)
      else private.has_role(p_uid,s.role) end),false);
$$;


--
-- Name: perm_level(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.perm_level(uid uuid, p_key text) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  -- Ignores `active` on purpose: a deactivated holder keeps their latent levels,
  -- so someone weaker cannot reactivate them (D4). Callers add is_active.
  select case
    when exists (select 1 from public.user_roles where user_id = uid and role = 'admin') then
      case when private.permission_allows(p_key, 'edit') then 2
           when private.permission_allows(p_key, 'read') then 1 else 0 end
    else coalesce((
      select max(case rp.level when 'edit' then 2 else 1 end)
        from public.user_roles ur
        join public.role_permissions rp on rp.role_id = ur.role_id
       where ur.user_id = uid and rp.permission = p_key
         and private.permission_allows(rp.permission, rp.level)), 0)
  end;
$$;


--
-- Name: permission_allows(text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.permission_allows(p_key text, p_level text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case
    when p_key in ('people_create','role_manager','role_assign','leave_accrual',
      'personal_info_own','special_leave','approval_delegate') then p_level = 'edit'
    when p_key in ('calendar','reports','absences','finance') then p_level = 'read'
    when p_key in ('people','personal_info','clearance','departments','leave_balances',
      'leave_requests','approval_steps','work_settings','holidays') then p_level in ('read','edit')
    else false end;
$$;


--
-- Name: permission_deps(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.permission_deps() RETURNS TABLE(key text, key_level text, needs text)
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  values
    ('people_create','read','people'),
    ('role_manager','read','people'), ('role_manager','read','leave_balances'),
    ('role_manager','read','calendar'), ('role_assign','read','people'),
    ('personal_info','read','people'), ('clearance','edit','people'),
    ('departments','read','people'), ('leave_balances','read','people'),
    ('leave_accrual','read','departments'), ('leave_requests','read','people'),
    ('approval_steps','read','people'), ('reports','read','people'),
    ('reports','read','leave_balances'), ('reports','read','leave_requests'),
    ('absences','read','people'), ('absences','read','leave_requests'),
    ('special_leave','read','people'), ('special_leave','read','leave_balances');
$$;


--
-- Name: permission_keys(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.permission_keys() RETURNS SETOF text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select unnest(array['people','people_create','role_manager','role_assign',
    'personal_info','personal_info_own','clearance','departments','leave_balances','leave_accrual',
    'special_leave','leave_requests','calendar','reports','absences','approval_steps','approval_delegate',
    'work_settings','holidays','finance']);
$$;


--
-- Name: personal_info_before_update(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.personal_info_before_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.employee_id is distinct from old.employee_id
     or new.company_id is distinct from old.company_id then
    raise exception 'not permitted to modify restricted personal info fields' using errcode = '42501';
  end if;
  new.updated_at := now();
  new.updated_by := auth.uid();
  return new;
end; $$;


--
-- Name: preserve_active_admin(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.preserve_active_admin() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if old.active
     and not new.active
     and exists (
       select 1 from public.user_roles
        where user_id = old.id and role = 'admin'
     )
     and not exists (
       select 1
         from public.profiles p
         join public.user_roles r on r.user_id = p.id and r.role = 'admin'
        where p.active
          and p.id <> old.id
     )
  then
    raise exception 'cannot deactivate the last active admin' using errcode = '22023';
  end if;
  return new;
end;
$$;


--
-- Name: profiles_create_personal_info(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.profiles_create_personal_info() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  insert into public.employee_personal_info (employee_id, company_id)
  values (new.id, new.company_id)
  on conflict (employee_id) do nothing;
  return new;
end; $$;


--
-- Name: reads_balances(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.reads_balances(uid uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.has_role(uid, 'manager') or private.has_perm(uid, 'leave_balances', 'read');
$$;


--
-- Name: reads_calendar(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.reads_calendar(uid uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.has_role(uid, 'manager') or private.has_perm(uid, 'calendar', 'read');
$$;


--
-- Name: reads_people(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.reads_people(uid uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.has_role(uid, 'manager') or private.has_perm(uid, 'people', 'read');
$$;


--
-- Name: refresh_separation_status(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.refresh_separation_status(p_id uuid) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  update public.separations s
     set status = 'awaiting_finance'
   where s.id = p_id
     and s.status = 'in_progress'
     and not exists (select 1 from public.separation_signoffs o
                      where o.separation_id = s.id and o.signed_at is null);
$$;


--
-- Name: replacement_is_away(uuid, date, date, public.leave_unit, time without time zone, time without time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.replacement_is_away(p_replacement_id uuid, p_start date, p_end date, p_unit public.leave_unit, p_start_time time without time zone, p_end_time time without time zone) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1 from public.leave_requests r
     where r.employee_id = p_replacement_id
       and r.status in ('pending', 'approved')
       and r.start_date <= p_end
       and r.end_date >= p_start
       and (
         r.unit = 'day' or p_unit = 'day'
         or (r.start_time < p_end_time and r.end_time > p_start_time)
       )
  );
$$;


--
-- Name: request_hr_exempt(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.request_hr_exempt(p_request uuid, p_step uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists(select 1 from public.approval_request_policy x
    join public.approval_steps s on s.id=p_step
    cross join lateral jsonb_array_elements(x.step_snapshot) snapshot
    where x.request_id=p_request and s.id=any(x.hr_exempt_step_ids)
      and snapshot-'expected_name'=jsonb_build_object('step_id',s.id,'step_role',s.role,
        'step_order',s.step_order,'manager_scope',s.manager_scope,'approver_id',s.approver_id,'applies_to',s.applies_to));
$$;


--
-- Name: request_step_applies(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.request_step_applies(p_request uuid, p_step uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (select 1 from public.leave_requests r join public.approval_steps s
    on s.id=p_step and s.company_id=r.company_id and s.active and r.kind=any(s.applies_to)
    where r.id=p_request and private.step_applies(s.manager_scope,r.employee_id)
      and not private.request_hr_exempt(p_request,p_step));
$$;


--
-- Name: request_step_decided(uuid, uuid, public.leave_status); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.request_step_decided(p_request uuid, p_step uuid, p_decision public.leave_status DEFAULT NULL::public.leave_status) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists(select 1 from public.leave_request_approvals a join public.approval_steps s on s.id=p_step
    where a.request_id=p_request and (p_decision is null or a.decision=p_decision)
      and (a.step_id=s.id or (a.step_id is null and a.step_role=s.role
        and (select count(*) from public.approval_steps candidate where candidate.role=s.role
          and private.request_step_applies(p_request,candidate.id))=1)));
$$;


--
-- Name: role_permissions_guard(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.role_permissions_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if (select kind from public.roles where id = new.role_id) = 'system' then
    raise exception 'permission rows belong on preset and custom roles only' using errcode = '22023';
  end if;
  return new;
end $$;


--
-- Name: role_within(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.role_within(p_role_id uuid, p_uid uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce((
    select case
      when r.system_key = 'admin' then false
      when private.is_admin(p_uid) then true
      when r.system_key = 'manager' then private.has_perm(p_uid, 'role_manager', 'edit')
      when exists (select 1 from public.user_roles where user_id = p_uid and role = 'hr')
        then r.system_key = 'employee' and private.has_perm(p_uid, 'role_assign', 'edit')
      when r.system_key in ('hr', 'finance') then false
      when exists (select 1 from public.role_permissions rp where rp.role_id = r.id
                   and rp.level = 'edit' and private.permission_allows(rp.permission, rp.level)) then false
      else private.has_perm(p_uid, 'role_assign', 'edit')
        and not exists (select 1 from public.role_permissions rp where rp.role_id = r.id
                         and private.permission_allows(rp.permission, rp.level)
                         and case rp.level when 'edit' then 2 else 1 end > private.perm_level(p_uid, rp.permission))
    end
    from public.roles r
    join public.profiles caller on caller.id = p_uid and caller.company_id = r.company_id
    where r.id = p_role_id), false);
$$;


--
-- Name: same_team(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.same_team(uid uuid, target uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.is_active(uid)
     and exists (
       select 1
         from public.profiles caller
         join public.profiles teammate
           on teammate.id = target
          and teammate.company_id = caller.company_id
          and teammate.department_id = caller.department_id
        where caller.id = uid
          and caller.department_id is not null
     );
$$;


--
-- Name: seed_company_roles(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.seed_company_roles(p_company uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  insert into public.roles (company_id, system_key, kind, name) values
    (p_company, 'admin', 'system', 'Admin'), (p_company, 'manager', 'system', 'Manager'),
    (p_company, 'employee', 'system', 'Employee'), (p_company, 'hr', 'preset', 'HR'),
    (p_company, 'security', 'preset', 'Security'), (p_company, 'finance', 'preset', 'Finance')
  on conflict do nothing;

  insert into public.role_permissions (role_id, permission, level)
  select r.id, v.permission, v.level
    from public.roles r
    join (values
      ('hr','people','edit'), ('hr','people_create','edit'), ('hr','role_manager','edit'),
      ('hr','personal_info','edit'), ('hr','clearance','edit'), ('hr','departments','edit'),
      ('hr','leave_balances','edit'), ('hr','leave_accrual','edit'), ('hr','leave_requests','read'),
      ('hr','calendar','read'), ('hr','reports','read'), ('hr','approval_steps','edit'),
      ('hr','work_settings','edit'), ('hr','holidays','edit'), ('hr','special_leave','edit'),
      ('hr','absences','read'), ('hr','finance','read'),
      ('security','people','read'), ('security','leave_balances','read'),
      ('security','leave_requests','read'), ('security','calendar','read'),
      ('security','absences','read'),
      ('finance','clearance','read'), ('finance','finance','read')
    ) as v(system_key, permission, level) on r.system_key = v.system_key::public.app_role
   where r.company_id = p_company
  on conflict do nothing;
end $$;


--
-- Name: separation_caller_company(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.separation_caller_company(p_uid uuid) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if p_uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not private.is_active(p_uid) then
    raise exception 'account is inactive' using errcode = '42501';
  end if;
  return (select company_id from public.profiles where id = p_uid);
end; $$;


--
-- Name: separation_check_fields(text, date, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.separation_check_fields(p_reason text, p_last_day date, p_note text) RETURNS void
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
begin
  if p_reason is null
     or p_reason not in ('resignation', 'dismissal', 'contract_end', 'abandonment', 'redundancy') then
    raise exception 'invalid reason' using errcode = '22023';
  end if;
  if p_last_day is null then
    raise exception 'last working day is required' using errcode = '22023';
  end if;
  if p_note is not null and length(p_note) > 500 then
    raise exception 'note is too long' using errcode = '22023';
  end if;
end; $$;


--
-- Name: separation_check_signature(text, boolean); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.separation_check_signature(p_data text, p_authorized boolean) RETURNS void
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
begin
  if not coalesce(p_authorized, false) then
    raise exception 'signature authorization is required' using errcode = '22023';
  end if;
  if p_data is null or p_data = '' then
    raise exception 'signature is required' using errcode = '22023';
  end if;
  if length(p_data) not between 100 and 350000
     or mod(length(p_data), 4) <> 2
     or p_data !~ '^data:image/png;base64,iVBORw0KGgo[A-Za-z0-9+/]*={0,2}$' then
    raise exception 'signature data is invalid' using errcode = '22023';
  end if;
end; $_$;


--
-- Name: separation_manageable(uuid, uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.separation_manageable(p_uid uuid, p_company uuid, p_employee uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not private.has_perm(p_uid, 'clearance', 'edit') then
    raise exception 'not allowed to manage clearance forms' using errcode = '42501';
  end if;
  if not exists (select 1 from public.profiles where id = p_employee and company_id = p_company) then
    raise exception 'employee not found' using errcode = '42501';
  end if;
  if not private.is_admin(p_uid) and not private.can_act_on(p_uid, p_employee) then
    raise exception 'not allowed to file a clearance form for this employee' using errcode = '42501';
  end if;
end; $$;


--
-- Name: separation_row_signer(uuid, uuid, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.separation_row_signer(p_company uuid, p_employee uuid, p_row jsonb) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_dept   uuid := nullif(p_row->>'department_id', '')::uuid;
  v_signer uuid := nullif(p_row->>'signer_id', '')::uuid;
begin
  if jsonb_typeof(p_row) <> 'object'
     or coalesce(char_length(btrim(p_row->>'name_fa')), 0) not between 1 and 100
     or coalesce(char_length(btrim(p_row->>'name_en')), 0) not between 1 and 100 then
    raise exception 'invalid rows' using errcode = '22023';
  end if;
  if v_dept is not null
     and not exists (select 1 from public.departments where id = v_dept and company_id = p_company) then
    raise exception 'invalid rows' using errcode = '22023';
  end if;
  if v_signer is not null then
    if v_signer = p_employee then
      raise exception 'the departing employee cannot sign their own form' using errcode = '22023';
    end if;
    if not exists (select 1 from public.profiles
                    where id = v_signer and company_id = p_company and active) then
      raise exception 'invalid rows' using errcode = '22023';
    end if;
    return v_signer;
  end if;
  if v_dept is not null then
    select d.manager_id into v_signer
      from public.departments d
      join public.profiles m on m.id = d.manager_id and m.active
     where d.id = v_dept;
    if v_signer = p_employee then
      return null;
    end if;
    return v_signer;
  end if;
  return null;
end; $$;


--
-- Name: special_leave_target(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.special_leave_target(p_actor uuid, p_employee uuid) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_company uuid;
  v_target_company uuid;
begin
  if p_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  -- has_perm is false for an inactive caller.
  if not private.has_perm(p_actor, 'special_leave', 'edit') then
    raise exception 'not allowed to grant special leave' using errcode = '42501';
  end if;
  select company_id into v_company from public.profiles where id = p_actor;
  select company_id into v_target_company from public.profiles where id = p_employee;
  if v_target_company is null or v_target_company <> v_company then
    raise exception 'employee not found' using errcode = 'P0002';
  end if;
  if not private.is_admin(p_actor) then
    if p_employee = p_actor then
      raise exception 'you cannot change your own leave balance' using errcode = '42501';
    end if;
    if exists (select 1 from public.user_roles where user_id = p_employee and role = 'admin') then
      raise exception 'not allowed to grant special leave to an admin' using errcode = '42501';
    end if;
    if not private.can_act_on(p_actor, p_employee) then
      raise exception 'not allowed to grant special leave to this employee' using errcode = '42501';
    end if;
  end if;
  return v_company;
end; $$;


--
-- Name: step_applies(text, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.step_applies(p_scope text, p_emp uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p_scope is distinct from 'department' or private.department_step_applies(p_emp);
$$;


--
-- Name: step_delegation(uuid, uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.step_delegation(p_uid uuid, p_request uuid, p_step uuid) RETURNS SETOF public.approval_delegations
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  -- Review fix: start from the caller's own unrevoked grants (indexed on delegate_id) and resolve
  -- only those principals, instead of resolving every profile in the company per request x step.
  -- Same result: a grant counts only while it is the principal's effective delegate.
  select d.* from public.approval_delegations g
    join public.leave_requests r on r.id=p_request and r.company_id=g.company_id
    cross join lateral private.effective_approval_delegate(g.principal_id) d
  where g.delegate_id=p_uid and g.revoked_at is null and d.id=g.id
    and r.employee_id<>p_uid
    and d.source_request_id is distinct from p_request
    and private.natural_step_authority(g.principal_id,p_request,p_step)
    and private.request_step_applies(p_request,p_step)
  order by d.created_at,d.id limit 1;
$$;


--
-- Name: submit_leave_impl(uuid, date, date, public.day_part, text, public.leave_unit, time without time zone, time without time zone, uuid, public.request_kind, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.submit_leave_impl(p_leave_type_id uuid, p_start date, p_end date, p_day_part public.day_part, p_reason text, p_unit public.leave_unit, p_start_time time without time zone, p_end_time time without time zone, p_replacement_id uuid, p_kind public.request_kind, p_location text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  v_company uuid;
  v_dept uuid;
  v_minutes int;
  v_affects boolean;
  v_is_paid boolean;
  v_allow_hourly boolean;
  v_balance int;
  v_unpaid int := 0;
  v_req uuid;
  v_win_start time;
  v_win_end time;
  v_cap int;
  v_day_used int;
  v_jyear int;
  v_seq int;
  v_location text := nullif(btrim(p_location), '');
  v_replacement uuid;
begin
  if v_uid is null then raise exception 'not authenticated' using errcode = '42501'; end if;
  select company_id, department_id into v_company, v_dept
    from public.profiles where id = v_uid;
  if v_company is null then raise exception 'no profile for caller' using errcode = '42501'; end if;
  perform private.approval_lock(v_company);
  -- Authentication in the public wrapper happened before this possible wait.
  -- Refresh both caller activity/company and the department used for cover rules.
  select department_id into v_dept from public.profiles
    where id=v_uid and company_id=v_company and active;
  if not found then
    raise exception 'not allowed to submit this request' using errcode='42501';
  end if;

  if p_start is null or p_end is null then
    raise exception 'start and end dates are required' using errcode = '22023';
  end if;
  if p_end < p_start then
    raise exception 'end date must not be before start date' using errcode = '22023';
  end if;
  if p_end - p_start > 366 then
    raise exception 'date range too long' using errcode = '22023';
  end if;

  if p_kind = 'errand' then
    if v_location is null then
      raise exception 'errand location is required' using errcode = '22023';
    end if;
    if length(v_location) > 200 then
      raise exception 'errand location is too long' using errcode = '22023';
    end if;
    if p_unit = 'hour' then
      if p_start <> p_end
         or p_start_time is null
         or p_end_time is null
         or p_end_time <= p_start_time
      then
        raise exception 'end time must be after start time' using errcode = '22023';
      end if;
    elsif p_unit = 'day' then
      if p_start_time is not null or p_end_time is not null or p_day_part <> 'full' then
        raise exception 'daily errands require full dates without times' using errcode = '22023';
      end if;
    end if;
    v_replacement := null;
  else
    if p_leave_type_id is null then
      raise exception 'invalid or inactive leave type' using errcode = '22023';
    end if;
    v_location := null;
    v_replacement := p_replacement_id;
  end if;

  if p_kind = 'leave' then
    select affects_balance, is_paid, allow_hourly
      into v_affects, v_is_paid, v_allow_hourly
      from public.leave_types
     where id = p_leave_type_id and company_id = v_company and active;
    if v_affects is null then
      raise exception 'invalid or inactive leave type' using errcode = '22023';
    end if;
  end if;

  if p_kind = 'leave' and p_unit = 'hour' then
    if not coalesce(v_allow_hourly, false) then
      raise exception 'this leave type cannot be taken hourly' using errcode = '22023';
    end if;
    if p_start_time is null or p_end_time is null or p_end_time <= p_start_time then
      raise exception 'end time must be after start time' using errcode = '22023';
    end if;

    select work_start, work_end, max_hourly_minutes_per_day
      into v_win_start, v_win_end, v_cap
      from public.work_settings where company_id = v_company limit 1;
    v_win_start := coalesce(v_win_start, '07:00'::time);
    v_win_end := coalesce(v_win_end, '15:00'::time);
    v_cap := coalesce(v_cap, 240);

    if p_start_time < v_win_start or p_end_time > v_win_end then
      raise exception 'times must fall within working hours' using errcode = '22023';
    end if;
    if (extract(epoch from (p_end_time - p_start_time)) / 60)::int > v_cap then
      raise exception 'hourly leave exceeds the daily limit' using errcode = '22023';
    end if;
  end if;

  if v_replacement is not null then
    if not exists (
      select 1 from public.profiles p
       where p.id = v_replacement
         and p.active
         and p.company_id = v_company
         and ((v_dept is not null and p.department_id = v_dept)
              or private.delegate_eligible(v_uid,p.id))
         and p.id <> v_uid
    ) then
      raise exception 'replacement must be an active colleague in your department'
        using errcode = '22023';
    end if;
  end if;

  perform pg_advisory_xact_lock(hashtextextended('leave:' || v_uid::text, 0));

  if p_kind = 'leave' and p_unit = 'hour' then
    -- FR-57: one hourly leave per person per day. Rejected and cancelled
    -- requests free the day again.
    if exists (
      select 1 from public.leave_requests r
       where r.employee_id = v_uid
         and r.kind = 'leave'
         and r.unit = 'hour'
         and r.start_date = p_start
         and r.status in ('pending', 'approved')
    ) then
      raise exception 'only one hourly leave per day' using errcode = '22023';
    end if;

    select coalesce(sum(r.requested_minutes), 0) into v_day_used
      from public.leave_requests r
     where r.employee_id = v_uid
       and r.kind = 'leave'
       and r.unit = 'hour'
       and r.start_date = p_start
       and r.status in ('pending', 'approved');

    if v_day_used + (extract(epoch from (p_end_time - p_start_time)) / 60)::int > v_cap then
      raise exception 'hourly leave exceeds the daily limit' using errcode = '22023';
    end if;
  end if;

  if exists (
    select 1 from public.leave_requests r
     where r.employee_id = v_uid
       and r.status in ('pending', 'approved')
       and r.start_date <= p_end
       and r.end_date >= p_start
       and (
         r.unit = 'day' or p_unit = 'day'
         or (r.start_time < p_end_time and r.end_time > p_start_time)
       )
  ) then
    raise exception 'overlapping leave request exists' using errcode = '22023';
  end if;

  if v_replacement is not null
     and private.replacement_is_away(
       v_replacement, p_start, p_end, p_unit, p_start_time, p_end_time
     )
  then
    raise exception 'replacement is on leave during this period' using errcode = '22023';
  end if;

  v_minutes := public.compute_requested_minutes(
    v_company, p_start, p_end, p_day_part, p_unit, p_start_time, p_end_time, p_kind
  );
  if v_minutes <= 0 then
    raise exception 'requested days must be greater than 0 (all days fall on weekend/holiday or dates invalid)'
      using errcode = '22023';
  end if;

  if v_affects then
    v_balance := public.current_leave_balance(v_uid, p_leave_type_id);
    v_unpaid := greatest(v_minutes - greatest(v_balance, 0), 0);
  elsif p_kind = 'leave' and not coalesce(v_is_paid, false) then
    v_unpaid := v_minutes;
  end if;

  select jm.jalali_year into v_jyear
    from public.jalali_months jm
   where p_start between jm.gregorian_start and jm.gregorian_end;
  if v_jyear is null then
    raise exception 'date outside supported calendar range' using errcode = '22023';
  end if;

  insert into public.leave_request_serials(company_id, jalali_year, kind, last_seq)
  values (v_company, v_jyear, p_kind, 1)
  on conflict (company_id, jalali_year, kind) do update
     set last_seq = public.leave_request_serials.last_seq + 1
  returning last_seq into v_seq;

  insert into public.leave_requests(
    employee_id, leave_type_id, start_date, end_date, day_part,
    unit, start_time, end_time, requested_minutes, unpaid_minutes, status, reason,
    replacement_id, company_id, serial_year, serial_seq, kind, errand_location, created_at
  )
  values (
    v_uid, p_leave_type_id, p_start, p_end, p_day_part,
    p_unit, p_start_time, p_end_time, v_minutes, v_unpaid, 'pending', p_reason,
    v_replacement, v_company, v_jyear, v_seq, p_kind, v_location, clock_timestamp()
  )
  returning id into v_req;

  return v_req;
end;
$$;


--
-- Name: user_roles_sync(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.user_roles_sync() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_company uuid := (select company_id from public.profiles where id = new.user_id);
  v_role_company uuid;
begin
  if tg_op = 'UPDATE' and new.role is distinct from old.role
     and new.role_id is not distinct from old.role_id then
    raise exception 'change role_id, not role' using errcode = '22023';
  end if;
  if new.role_id is null then
    if new.role is null then
      raise exception 'role or role_id required' using errcode = '23502';
    end if;
    select id into new.role_id from public.roles
     where company_id = v_company and system_key = new.role;
    if new.role_id is null then
      raise exception 'no % role for this company', new.role using errcode = '23503';
    end if;
  else
    select system_key, company_id into new.role, v_role_company from public.roles where id = new.role_id;
    if v_role_company is distinct from v_company then
      raise exception 'role belongs to another company' using errcode = '42501';
    end if;
  end if;
  return new;
end $$;


--
-- Name: user_signatures_touch(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.user_signatures_touch() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  new.updated_at := now();
  return new;
end; $$;


--
-- Name: accrue_all_leave(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accrue_all_leave() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_p            record;
  v_employees    int := 0;
  v_rows_before  int;
  v_rows_after   int;
  v_last_emp     uuid;
begin
  if not private.has_perm(auth.uid(), 'leave_accrual', 'edit') then
    raise exception 'not allowed to post accruals' using errcode = '42501';
  end if;

  select count(*) into v_rows_before from public.leave_ledger where period_month is not null;

  for v_p in
    select p.employee_id, p.leave_type_id
      from public.employee_leave_policies p
      join public.profiles pr on pr.id = p.employee_id
     where pr.active
       and p.accrual_minutes_per_month > 0
     order by p.employee_id
  loop
    perform public.accrue_leave(v_p.employee_id, v_p.leave_type_id);
    if v_last_emp is null or v_last_emp <> v_p.employee_id then
      v_employees := v_employees + 1;
      v_last_emp := v_p.employee_id;
    end if;
  end loop;

  select count(*) into v_rows_after from public.leave_ledger where period_month is not null;

  insert into public.audit_log(actor_id, action, entity, entity_id, after)
  values (auth.uid(), 'accrue_all_leave', 'leave_ledger', null,
          jsonb_build_object('employees', v_employees, 'rows_posted', v_rows_after - v_rows_before));

  return jsonb_build_object('employees', v_employees, 'rows_posted', v_rows_after - v_rows_before);
end; $$;


--
-- Name: accrue_employee_leave(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accrue_employee_leave(p_employee_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_uid uuid := auth.uid(); v_type uuid;
begin
  if v_uid is null then raise exception 'not authenticated' using errcode = '42501'; end if;
  -- FR-43: hr joins manager-of and admin. This posts only months the policy has
  -- ALREADY earned — it credits nothing that was not due — and it runs lazily on
  -- every balance read. Without hr here, the balances HR now reads on the Edit
  -- Employee screen would silently lag behind the accrual policy HR just set.
  if not (private.is_manager_of(v_uid, p_employee_id)
          or private.has_perm(v_uid, 'leave_balances', 'read')) then
    raise exception 'not allowed to accrue for this employee' using errcode = '42501';
  end if;

  for v_type in
    select leave_type_id from public.employee_leave_policies where employee_id = p_employee_id
  loop
    perform public.accrue_leave(p_employee_id, v_type);
  end loop;
end; $$;


--
-- Name: accrue_leave(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accrue_leave(p_employee_id uuid, p_leave_type_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_rate      int;
  v_cap       int;
  v_start     date;
  v_hire      date;
  v_today     date := (now() at time zone 'Asia/Tehran')::date;
  v_this_mon  date;
  v_first_post date;
  v_balance   int;
  v_m         record;
  v_amount    int;
  v_already   int;
  v_rows      int;
begin
  select accrual_minutes_per_month, annual_cap_minutes, accrual_start_month
    into v_rate, v_cap, v_start
    from public.employee_leave_policies
   where employee_id = p_employee_id and leave_type_id = p_leave_type_id;

  -- No policy, or a non-accruing type (sick leave): nothing to do.
  if v_rate is null or v_rate <= 0 then
    return public.current_leave_balance(p_employee_id, p_leave_type_id);
  end if;

  -- Hot-path short-circuit: this runs on every balance read, so if the month
  -- containing today is already posted there is nothing to do and we skip both
  -- the lock and the loop. Steady-state cost is one indexed EXISTS.
  select gregorian_start into v_this_mon
    from public.jalali_months
   where v_today between gregorian_start and gregorian_end;

  -- The oldest month actually posted. If the policy's start is now EARLIER
  -- than this, an admin has backdated accrual_start_month and the months in
  -- between were never credited, so the short-circuit below must not fire.
  select min(period_month) into v_first_post
    from public.leave_ledger
   where employee_id = p_employee_id and leave_type_id = p_leave_type_id
     and entry_type = 'allocation' and period_month is not null;

  if v_this_mon is not null
     and (v_first_post is null or v_first_post <= v_start)
     and exists (
       select 1 from public.leave_ledger
        where employee_id = p_employee_id and leave_type_id = p_leave_type_id
          and entry_type = 'allocation' and period_month = v_this_mon
     )
  then
    return public.current_leave_balance(p_employee_id, p_leave_type_id);
  end if;

  -- Serialize with every other leave write for this employee (2026-07-02 hardening).
  perform pg_advisory_xact_lock(hashtextextended('leave:' || p_employee_id::text, 0));

  select hire_date into v_hire from public.profiles where id = p_employee_id;
  v_balance := public.current_leave_balance(p_employee_id, p_leave_type_id);

  for v_m in
    select jm.jalali_year, jm.jalali_month, jm.gregorian_start, jm.gregorian_end
      from public.jalali_months jm
     where jm.gregorian_start >= v_start
       and jm.gregorian_start <= v_today
     order by jm.gregorian_start
  loop
    -- Nobody accrues for a month that ended before they were hired.
    if v_hire is not null and v_m.gregorian_end < v_hire then
      continue;
    end if;

    v_amount := v_rate;

    -- Pro-rate the hire month by calendar days remaining in it.
    if v_hire is not null and v_hire between v_m.gregorian_start and v_m.gregorian_end then
      v_amount := round(v_rate::numeric
                        * ((v_m.gregorian_end - v_hire) + 1)
                        / ((v_m.gregorian_end - v_m.gregorian_start) + 1));
    end if;

    -- The annual cap counts ACCRUALS within this Jalali year, not the balance.
    -- Opening allocations have a null period_month and so never consume it.
    if v_cap is not null then
      select coalesce(sum(l.delta_minutes), 0) into v_already
        from public.leave_ledger l
        join public.jalali_months jm on jm.gregorian_start = l.period_month
       where l.employee_id = p_employee_id and l.leave_type_id = p_leave_type_id
         and l.entry_type = 'allocation'
         and jm.jalali_year = v_m.jalali_year;
      v_amount := least(v_amount, greatest(v_cap - v_already, 0));
    end if;

    if v_amount > 0 then
      insert into public.leave_ledger(employee_id, leave_type_id, entry_type,
                                      delta_minutes, balance_after_minutes, period_month, note)
      values (p_employee_id, p_leave_type_id, 'allocation',
              v_amount, v_balance + v_amount, v_m.gregorian_start, 'monthly accrual')
      on conflict do nothing;
      get diagnostics v_rows = row_count;
      if v_rows = 1 then
        v_balance := v_balance + v_amount;
      end if;
    end if;
  end loop;

  return v_balance;
end; $$;


--
-- Name: accrue_my_leave(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accrue_my_leave() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid  uuid := auth.uid();
  v_type uuid;
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not private.is_active(v_uid) then
    raise exception 'account is inactive' using errcode = '42501';
  end if;

  for v_type in
    select leave_type_id
      from public.employee_leave_policies
     where employee_id = v_uid
  loop
    perform public.accrue_leave(v_uid, v_type);
  end loop;
end;
$$;


--
-- Name: allocate_leave(uuid, uuid, date, date, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.allocate_leave(p_employee_id uuid, p_leave_type_id uuid, p_period_start date, p_period_end date, p_minutes integer) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  -- FR-43, FR-55: admin, or leave_balances at Allowed. HR administers leave, so the
  -- two screens that set an opening balance and an accrual policy are theirs as well.
  if not (private.is_admin(auth.uid()) or private.has_perm(auth.uid(), 'leave_balances', 'edit')) then
    raise exception 'only admins or hr can allocate leave' using errcode = '42501';
  end if;
  -- ...but nobody except an admin does it to THEMSELVES. Same asymmetry FR-36
  -- already applies to signing your own request: an admin is the owner and may,
  -- an HR officer granting themselves leave is an obvious control weakness.
  if not private.is_admin(auth.uid()) and p_employee_id = auth.uid() then
    raise exception 'you cannot change your own leave balance' using errcode = '42501';
  end if;
  -- FR-55 D4: and only on someone who holds nothing the caller lacks.
  if not private.is_admin(auth.uid()) and not private.can_act_on(auth.uid(), p_employee_id) then
    raise exception 'not allowed to change this employee''s leave' using errcode = '42501';
  end if;
  return private.allocate_leave_impl(auth.uid(), p_employee_id, p_leave_type_id,
                                     p_period_start, p_period_end, p_minutes);
end; $$;


--
-- Name: app_approval_capabilities(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_approval_capabilities() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select jsonb_build_object('is_admin',private.is_admin(auth.uid()),
    'can_delegate',private.has_perm(auth.uid(),'approval_delegate','edit'),
    'can_approve',private.natural_approver(auth.uid()) or exists (
      select 1 from public.approval_delegations d
      cross join lateral private.effective_approval_delegate(d.principal_id) e
      where e.id=d.id and d.delegate_id=auth.uid()));
$$;


--
-- Name: app_approval_queue(public.leave_status); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_approval_queue(p_status public.leave_status DEFAULT 'pending'::public.leave_status) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(jsonb_agg(public.app_request_approval_context(r.id) order by r.created_at),'[]')
    from public.leave_requests r where r.status=p_status and private.can_read_approval_request(auth.uid(),r.id)
      and (r.employee_id<>auth.uid() or private.is_admin(auth.uid()));
$$;


--
-- Name: app_bulk_create_employees(uuid, jsonb, jsonb, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_bulk_create_employees(p_company_id uuid, p_rows jsonb, p_departments jsonb, p_balance_as_of date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_caller        uuid := auth.uid();
  v_bulk_hr       boolean;
  v_today         date := (now() at time zone 'Asia/Tehran')::date;
  v_dep           jsonb;
  v_row           jsonb;
  v_i             integer := 0;
  v_dept          uuid;
  v_mgr_pno       text;
  v_mgr           uuid;
  v_role          text;
  v_uid           uuid;
  v_code          text;
  v_minutes       int;
  v_prev          int;
  v_ledger        uuid;
  v_annual_type   uuid;
  v_rate          int;
  v_cap           int;
  v_carry         int;
  v_accrual_start date;
  v_dm            uuid;
  v_result        jsonb := '[]'::jsonb;
begin
  -- FR-55: the non-admin branch keys on people_create; its clamps are unchanged.
  v_bulk_hr := private.has_perm(v_caller, 'people_create', 'edit') and not private.is_admin(v_caller);
  if not (private.is_admin(v_caller) or v_bulk_hr) then
    raise exception 'admin or hr role required' using errcode = '42501';
  end if;
  -- Tenant binding: the company comes from the request, so it must be the
  -- caller's own. Without this an admin of one company could import into another.
  if p_company_id is distinct from (select company_id from public.profiles where id = v_caller) then
    raise exception 'not allowed to import into another company' using errcode = '42501';
  end if;
  if p_rows is null or jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) = 0 then
    raise exception 'no rows to import' using errcode = '22023';
  end if;
  if p_departments is null or jsonb_typeof(p_departments) <> 'array' then
    raise exception 'departments must be an array' using errcode = '22023';
  end if;
  if p_balance_as_of is null then
    raise exception 'balance date is required' using errcode = '22023';
  end if;
  if p_balance_as_of > v_today then
    raise exception 'balance date cannot be in the future' using errcode = '22023';
  end if;

  -- First Jalali month after the one containing the balance date. Raises
  -- through the join if the date is outside the seeded calendar.
  select n.gregorian_start into v_accrual_start
    from public.jalali_months m
    join public.jalali_months n on n.gregorian_start = m.gregorian_end + 1
   where p_balance_as_of between m.gregorian_start and m.gregorian_end;
  if v_accrual_start is null then
    raise exception 'date outside supported calendar range' using errcode = '22023';
  end if;

  select id, default_accrual_minutes_per_month, default_annual_cap_minutes, default_carryover_cap_minutes
    into v_annual_type, v_rate, v_cap, v_carry
    from public.leave_types
   where company_id = p_company_id and name_en = 'Annual Leave' and affects_balance;

  -- 1. Departments.
  for v_dep in select * from jsonb_array_elements(p_departments) loop
    v_code := upper(btrim(coalesce(v_dep->>'code', '')));
    if v_code !~ '^[A-Z0-9]{2,4}$' then
      raise exception 'invalid department code "%"', v_code using errcode = '22023';
    end if;
    if coalesce((v_dep->>'create')::boolean, false) then
      if v_bulk_hr then
        raise exception 'only admins can create departments' using errcode = '42501';
      end if;
      if exists (select 1 from public.departments where company_id = p_company_id and code = v_code) then
        raise exception 'department code "%" already exists', v_code using errcode = '23505';
      end if;
      if coalesce(btrim(v_dep->>'name_fa'), '') = '' or coalesce(btrim(v_dep->>'name_en'), '') = '' then
        raise exception 'department "%" needs a Farsi and an English name', v_code using errcode = '22023';
      end if;
      insert into public.departments (company_id, name_fa, name_en, kind, code)
      values (p_company_id, btrim(v_dep->>'name_fa'), btrim(v_dep->>'name_en'), 'team', v_code);
    end if;
  end loop;

  -- 2–4. Employees, opening balances, accrual policies.
  for v_row in select * from jsonb_array_elements(p_rows) loop
    v_i := v_i + 1;

    v_role := coalesce(v_row->>'role', 'employee');
    -- FR-35 / spec D4: HR may bulk-onboard, but only ordinary employees.
    if v_bulk_hr then
      v_role := 'employee';
    end if;
    if v_role not in ('manager', 'employee') then
      raise exception 'row %: role must be manager or employee', v_i using errcode = '22023';
    end if;

    select id into v_dept from public.departments
     where company_id = p_company_id and code = upper(btrim(coalesce(v_row->>'department_code', '')));
    if v_dept is null then
      raise exception 'row %: unknown department code "%"', v_i, v_row->>'department_code' using errcode = '22023';
    end if;

    v_mgr := null;
    v_mgr_pno := coalesce(nullif(btrim(coalesce(v_row->>'supervisor_personnel_no', '')), ''),
                          nullif(btrim(coalesce(v_row->>'manager_personnel_no', '')), ''));
    if v_mgr_pno is not null then
      select id into v_mgr from public.profiles
       where company_id = p_company_id and personnel_no = v_mgr_pno;
      if v_mgr is null then
        raise exception 'row %: manager with personnel number % not found (list managers before their team)',
          v_i, v_mgr_pno using errcode = '22023';
      end if;
    end if;

    v_uid := private.create_employee_impl(
      v_caller, case when v_bulk_hr then 'bulk_hr' else 'bulk' end, p_company_id, v_dept, v_mgr,
      v_row->>'personnel_no', v_row->>'full_name', v_row->>'password',
      (case when v_role = 'manager' then array['manager','employee'] else array['employee'] end)::public.app_role[],
      nullif(v_row->>'hire_date', '')::date, 'fa', 'jalali', v_row->>'job_title');

    v_minutes := coalesce(nullif(v_row->>'balance_minutes', ''), '0')::int;
    -- FR-55: an opening balance is leave_balances edit, as on the Add Employee form.
    if v_bulk_hr and v_minutes <> 0 and not private.has_perm(v_caller, 'leave_balances', 'edit') then
      raise exception 'not allowed to set opening balances' using errcode = '42501';
    end if;
    if v_minutes < -366 * private.company_minutes_per_day(p_company_id)
       or v_minutes > 366 * private.company_minutes_per_day(p_company_id) then
      raise exception 'row %: opening balance is out of range', v_i using errcode = '22023';
    end if;
    if v_minutes <> 0 then
      if v_annual_type is null then
        raise exception 'row %: leave type "Annual Leave" not found', v_i using errcode = '22023';
      end if;
      perform pg_advisory_xact_lock(hashtextextended('leave:' || v_uid::text, 0));
      v_prev := public.current_leave_balance(v_uid, v_annual_type);
      insert into public.leave_ledger (employee_id, leave_type_id, entry_type, delta_minutes, balance_after_minutes, note)
      values (v_uid, v_annual_type, 'adjustment', v_minutes, v_prev + v_minutes,
              'opening balance as of ' || p_balance_as_of::text)
      returning id into v_ledger;
      insert into public.audit_log (actor_id, action, entity, entity_id, after)
      values (v_caller, 'opening_balance', 'leave_ledger', v_ledger,
              jsonb_build_object('employee_id', v_uid, 'leave_type_id', v_annual_type,
                                 'minutes', v_minutes, 'as_of', p_balance_as_of));
    end if;

    if v_annual_type is not null and coalesce(v_rate, 0) > 0 then
      insert into public.employee_leave_policies (
        employee_id, leave_type_id, accrual_minutes_per_month,
        annual_cap_minutes, carryover_cap_minutes, accrual_start_month, created_by
      ) values (
        v_uid, v_annual_type, v_rate, v_cap, coalesce(v_carry, 4320), v_accrual_start, v_caller
      )
      on conflict (employee_id, leave_type_id) do nothing;
    end if;

    select employee_code into v_code from public.profiles where id = v_uid;
    v_result := v_result || jsonb_build_object(
      'personnel_no', v_row->>'personnel_no', 'employee_code', v_code, 'user_id', v_uid);
  end loop;

  -- 5. Department managers — only where the department has none yet.
  for v_dep in select * from jsonb_array_elements(p_departments) loop
    if coalesce(btrim(v_dep->>'manager_personnel_no'), '') = '' then
      continue;
    end if;
    if v_bulk_hr then
      raise exception 'only admins can assign department managers' using errcode = '42501';
    end if;
    select id into v_dm from public.profiles
     where company_id = p_company_id and personnel_no = btrim(v_dep->>'manager_personnel_no');
    if v_dm is null then
      raise exception 'department manager with personnel number % not found',
        v_dep->>'manager_personnel_no' using errcode = '22023';
    end if;
    update public.departments
       set manager_id = v_dm
     where company_id = p_company_id
       and code = upper(btrim(v_dep->>'code'))
       and manager_id is null;
  end loop;

  insert into public.audit_log (actor_id, action, entity, entity_id, after)
  values (v_caller, 'bulk_create_employees', 'profiles', null,
          jsonb_build_object('count', jsonb_array_length(p_rows),
                             'departments_created',
                             (select count(*) from jsonb_array_elements(p_departments) d
                               where coalesce((d->>'create')::boolean, false)),
                             'balance_as_of', p_balance_as_of));

  return v_result;
end;
$_$;


--
-- Name: app_bulk_import_employees(uuid, text, jsonb, jsonb, date, boolean, uuid[], jsonb, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_bulk_import_employees(p_company_id uuid, p_mode text, p_rows jsonb, p_departments jsonb, p_balance_as_of date, p_overwrite_balances boolean, p_deactivate uuid[], p_reassign jsonb, p_delete_departments text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_caller        uuid := auth.uid();
  v_is_admin      boolean;
  v_bulk_hr       boolean;
  v_today         date := (now() at time zone 'Asia/Tehran')::date;
  v_dep           jsonb;
  v_row           jsonb;
  v_i             integer := 0;
  v_dept          uuid;
  v_mgr_pno       text;
  v_mgr           uuid;
  v_role          text;
  v_uid           uuid;
  v_existing      uuid;
  v_code          text;
  v_minutes       int;
  v_prev          int;
  v_ledger        uuid;
  v_annual_type   uuid;
  v_rate          int;
  v_cap           int;
  v_carry         int;
  v_accrual_start date;
  v_dm            uuid;
  v_id            uuid;
  v_created       jsonb := '[]'::jsonb;
  v_updated       int := 0;
  v_deactivated   int := 0;
  v_deleted       text[] := '{}';
  v_not_deleted   text[] := '{}';
  v_mpd           int;
begin
  v_is_admin := private.is_admin(v_caller);
  -- FR-55: the non-admin branch keys on people_create; its clamps are unchanged.
  v_bulk_hr  := private.has_perm(v_caller, 'people_create', 'edit') and not v_is_admin;
  if not (v_is_admin or v_bulk_hr) then
    raise exception 'admin or hr role required' using errcode = '42501';
  end if;
  -- Tenant binding: the company comes from the request, so it must be the
  -- caller's own. Without this an admin of one company could import into another.
  if p_company_id is distinct from (select company_id from public.profiles where id = v_caller) then
    raise exception 'not allowed to import into another company' using errcode = '42501';
  end if;
  -- Acquire this before any profile row or employee leave lock. The profile
  -- trigger intentionally skips updates that do not change approval authority.
  perform private.approval_lock(p_company_id);
  v_is_admin := private.is_admin(v_caller);
  v_bulk_hr := private.has_perm(v_caller, 'people_create', 'edit') and not v_is_admin;
  if not (v_is_admin or v_bulk_hr) then
    raise exception 'admin or hr role required' using errcode = '42501';
  end if;
  if p_company_id is distinct from (select company_id from public.profiles where id = v_caller) then
    raise exception 'not allowed to import into another company' using errcode = '42501';
  end if;
  v_today := (clock_timestamp() at time zone 'Asia/Tehran')::date;

  if p_mode is null or p_mode not in ('add', 'update', 'replace') then
    raise exception 'import mode must be add, update or replace' using errcode = '22023';
  end if;
  if p_mode <> 'add' and not v_is_admin then
    raise exception 'only admins can update or replace employees by import' using errcode = '42501';
  end if;
  if p_rows is null or jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) = 0 then
    raise exception 'no rows to import' using errcode = '22023';
  end if;
  if p_departments is null or jsonb_typeof(p_departments) <> 'array' then
    raise exception 'departments must be an array' using errcode = '22023';
  end if;
  if p_mode <> 'replace' and (coalesce(cardinality(p_deactivate), 0) > 0
       or coalesce(cardinality(p_delete_departments), 0) > 0
       or coalesce(jsonb_array_length(p_reassign), 0) > 0) then
    raise exception 'deactivation and department deletion need replace mode' using errcode = '22023';
  end if;
  if p_balance_as_of is null then
    raise exception 'balance date is required' using errcode = '22023';
  end if;
  if p_balance_as_of > v_today then
    raise exception 'balance date cannot be in the future' using errcode = '22023';
  end if;

  select n.gregorian_start into v_accrual_start
    from public.jalali_months m
    join public.jalali_months n on n.gregorian_start = m.gregorian_end + 1
   where p_balance_as_of between m.gregorian_start and m.gregorian_end;
  if v_accrual_start is null then
    raise exception 'date outside supported calendar range' using errcode = '22023';
  end if;

  select id, default_accrual_minutes_per_month, default_annual_cap_minutes, default_carryover_cap_minutes
    into v_annual_type, v_rate, v_cap, v_carry
    from public.leave_types
   where company_id = p_company_id and name_en = 'Annual Leave' and affects_balance;
  v_mpd := private.company_minutes_per_day(p_company_id);

  -- 1. Departments: create, or (update/replace) take the file's names.
  for v_dep in select * from jsonb_array_elements(p_departments) loop
    v_code := upper(btrim(coalesce(v_dep->>'code', '')));
    if v_code !~ '^[A-Z0-9]{2,4}$' then
      raise exception 'invalid department code "%"', v_code using errcode = '22023';
    end if;
    if coalesce((v_dep->>'create')::boolean, false) then
      if v_bulk_hr then
        raise exception 'only admins can create departments' using errcode = '42501';
      end if;
      if exists (select 1 from public.departments where company_id = p_company_id and code = v_code) then
        raise exception 'department code "%" already exists', v_code using errcode = '23505';
      end if;
      if coalesce(btrim(v_dep->>'name_fa'), '') = '' or coalesce(btrim(v_dep->>'name_en'), '') = '' then
        raise exception 'department "%" needs a Farsi and an English name', v_code using errcode = '22023';
      end if;
      insert into public.departments (company_id, name_fa, name_en, kind, code)
      values (p_company_id, btrim(v_dep->>'name_fa'), btrim(v_dep->>'name_en'), 'team', v_code);
    elsif p_mode <> 'add' and coalesce((v_dep->>'rename')::boolean, false) then
      update public.departments
         set name_fa = btrim(v_dep->>'name_fa'), name_en = btrim(v_dep->>'name_en')
       where company_id = p_company_id and code = v_code
         and coalesce(btrim(v_dep->>'name_fa'), '') <> '' and coalesce(btrim(v_dep->>'name_en'), '') <> '';
    end if;
  end loop;

  -- 2. Employees: create or update.
  for v_row in select * from jsonb_array_elements(p_rows) loop
    v_i := v_i + 1;

    v_role := coalesce(v_row->>'role', 'employee');
    if v_bulk_hr then
      v_role := 'employee';
    end if;
    if v_role not in ('manager', 'employee') then
      raise exception 'row %: role must be manager or employee', v_i using errcode = '22023';
    end if;

    select id into v_dept from public.departments
     where company_id = p_company_id and code = upper(btrim(coalesce(v_row->>'department_code', '')));
    if v_dept is null then
      raise exception 'row %: unknown department code "%"', v_i, v_row->>'department_code' using errcode = '22023';
    end if;

    v_mgr := null;
    v_mgr_pno := coalesce(nullif(btrim(coalesce(v_row->>'supervisor_personnel_no', '')), ''),
                          nullif(btrim(coalesce(v_row->>'manager_personnel_no', '')), ''));
    if v_mgr_pno is not null then
      select id into v_mgr from public.profiles
       where company_id = p_company_id and personnel_no = v_mgr_pno;
      if v_mgr is null then
        raise exception 'row %: manager with personnel number % not found (list managers before their team)',
          v_i, v_mgr_pno using errcode = '22023';
      end if;
    end if;

    v_minutes := coalesce(nullif(v_row->>'balance_minutes', ''), '0')::int;
    -- FR-55: an opening balance is leave_balances edit, as on the Add Employee form
    -- (a non-admin reaches only add mode).
    if v_bulk_hr and v_minutes <> 0 and not private.has_perm(v_caller, 'leave_balances', 'edit') then
      raise exception 'not allowed to set opening balances' using errcode = '42501';
    end if;
    if v_minutes < -366 * v_mpd or v_minutes > 366 * v_mpd then
      raise exception 'row %: opening balance is out of range', v_i using errcode = '22023';
    end if;

    select id into v_existing from public.profiles
     where company_id = p_company_id and personnel_no = btrim(coalesce(v_row->>'personnel_no', ''));

    if v_existing is not null then
      if p_mode = 'add' then
        raise exception 'personnel number already exists' using errcode = '23505';
      end if;
      v_uid := v_existing;

      update public.profiles
         set full_name     = btrim(v_row->>'full_name'),
             job_title     = nullif(btrim(coalesce(v_row->>'job_title', '')), ''),
             department_id = v_dept,
             manager_id    = v_mgr,
             hire_date     = coalesce(nullif(v_row->>'hire_date', '')::date, hire_date),
             active        = true
       where id = v_uid;

      -- Only the manager role follows the file; admin/hr/security are untouched.
      if v_role = 'manager' then
        insert into public.user_roles (user_id, role) values (v_uid, 'manager') on conflict do nothing;
      else
        delete from public.user_roles where user_id = v_uid and role = 'manager';
      end if;

      if coalesce(p_overwrite_balances, false) and v_annual_type is not null then
        perform pg_advisory_xact_lock(hashtextextended('leave:' || v_uid::text, 0));
        v_prev := public.current_leave_balance(v_uid, v_annual_type);
        if v_prev <> v_minutes then
          insert into public.leave_ledger (employee_id, leave_type_id, entry_type, delta_minutes, balance_after_minutes, note)
          values (v_uid, v_annual_type, 'adjustment', v_minutes - v_prev, v_minutes,
                  'opening balance as of ' || p_balance_as_of::text)
          returning id into v_ledger;
          insert into public.audit_log (actor_id, action, entity, entity_id, after)
          values (v_caller, 'opening_balance', 'leave_ledger', v_ledger,
                  jsonb_build_object('employee_id', v_uid, 'previous_minutes', v_prev,
                                     'minutes', v_minutes, 'as_of', p_balance_as_of));
        end if;
        if coalesce(v_rate, 0) > 0 then
          insert into public.employee_leave_policies (
            employee_id, leave_type_id, accrual_minutes_per_month,
            annual_cap_minutes, carryover_cap_minutes, accrual_start_month, created_by
          ) values (v_uid, v_annual_type, v_rate, v_cap, coalesce(v_carry, 4320), v_accrual_start, v_caller)
          on conflict (employee_id, leave_type_id) do update
             set accrual_start_month = excluded.accrual_start_month;
        end if;
      end if;

      insert into public.audit_log (actor_id, action, entity, entity_id, after)
      values (v_caller, 'bulk_update_employee', 'profiles', v_uid,
              jsonb_build_object('personnel_no', v_row->>'personnel_no', 'mode', p_mode,
                                 'department_code', v_row->>'department_code', 'role', v_role));
      v_updated := v_updated + 1;
    else
      v_uid := private.create_employee_impl(
        v_caller, case when v_bulk_hr then 'bulk_hr' else 'bulk' end, p_company_id, v_dept, v_mgr,
        v_row->>'personnel_no', v_row->>'full_name', v_row->>'password',
        (case when v_role = 'manager' then array['manager','employee'] else array['employee'] end)::public.app_role[],
        nullif(v_row->>'hire_date', '')::date, 'fa', 'jalali', v_row->>'job_title');

      if v_minutes <> 0 then
        if v_annual_type is null then
          raise exception 'row %: leave type "Annual Leave" not found', v_i using errcode = '22023';
        end if;
        perform pg_advisory_xact_lock(hashtextextended('leave:' || v_uid::text, 0));
        v_prev := public.current_leave_balance(v_uid, v_annual_type);
        insert into public.leave_ledger (employee_id, leave_type_id, entry_type, delta_minutes, balance_after_minutes, note)
        values (v_uid, v_annual_type, 'adjustment', v_minutes, v_prev + v_minutes,
                'opening balance as of ' || p_balance_as_of::text)
        returning id into v_ledger;
        insert into public.audit_log (actor_id, action, entity, entity_id, after)
        values (v_caller, 'opening_balance', 'leave_ledger', v_ledger,
                jsonb_build_object('employee_id', v_uid, 'leave_type_id', v_annual_type,
                                   'minutes', v_minutes, 'as_of', p_balance_as_of));
      end if;

      if v_annual_type is not null and coalesce(v_rate, 0) > 0 then
        insert into public.employee_leave_policies (
          employee_id, leave_type_id, accrual_minutes_per_month,
          annual_cap_minutes, carryover_cap_minutes, accrual_start_month, created_by
        ) values (v_uid, v_annual_type, v_rate, v_cap, coalesce(v_carry, 4320), v_accrual_start, v_caller)
        on conflict (employee_id, leave_type_id) do nothing;
      end if;

      select employee_code into v_code from public.profiles where id = v_uid;
      v_created := v_created || jsonb_build_object(
        'personnel_no', v_row->>'personnel_no', 'employee_code', v_code, 'user_id', v_uid);
    end if;
  end loop;

  -- 3. Kept people whose manager changes (replace).
  for v_dep in select * from jsonb_array_elements(coalesce(p_reassign, '[]'::jsonb)) loop
    v_id := (v_dep->>'id')::uuid;
    if not exists (select 1 from public.profiles where id = v_id and company_id = p_company_id) then
      raise exception 'employee not found' using errcode = 'P0002';
    end if;
    v_mgr := null;
    if coalesce(btrim(v_dep->>'manager_personnel_no'), '') <> '' then
      select id into v_mgr from public.profiles
       where company_id = p_company_id and personnel_no = btrim(v_dep->>'manager_personnel_no');
      if v_mgr is null then
        raise exception 'manager with personnel number % not found', v_dep->>'manager_personnel_no' using errcode = '22023';
      end if;
    end if;
    update public.profiles set manager_id = v_mgr where id = v_id;
    insert into public.audit_log (actor_id, action, entity, entity_id, after)
    values (v_caller, 'bulk_reassign_manager', 'profiles', v_id, jsonb_build_object('manager_id', v_mgr));
  end loop;

  -- 4. Deactivations (replace). Never an admin, never the caller.
  foreach v_id in array coalesce(p_deactivate, '{}'::uuid[]) loop
    if not exists (select 1 from public.profiles where id = v_id and company_id = p_company_id) then
      raise exception 'employee not found' using errcode = 'P0002';
    end if;
    if v_id = v_caller or exists (select 1 from public.user_roles where user_id = v_id and role = 'admin') then
      raise exception 'an import cannot deactivate an admin account' using errcode = '42501';
    end if;
    update public.profiles set active = false where id = v_id and active;
    if found then
      v_deactivated := v_deactivated + 1;
      insert into public.audit_log (actor_id, action, entity, entity_id, after)
      values (v_caller, 'bulk_deactivate', 'profiles', v_id, jsonb_build_object('mode', p_mode));
    end if;
  end loop;

  -- 5. Department managers.
  for v_dep in select * from jsonb_array_elements(p_departments) loop
    if coalesce(btrim(v_dep->>'manager_personnel_no'), '') = '' then
      continue;
    end if;
    if v_bulk_hr then
      raise exception 'only admins can assign department managers' using errcode = '42501';
    end if;
    select id into v_dm from public.profiles
     where company_id = p_company_id and personnel_no = btrim(v_dep->>'manager_personnel_no');
    if v_dm is null then
      raise exception 'department manager with personnel number % not found',
        v_dep->>'manager_personnel_no' using errcode = '22023';
    end if;
    update public.departments d
       set manager_id = v_dm
     where d.company_id = p_company_id
       and d.code = upper(btrim(v_dep->>'code'))
       and (p_mode <> 'add'
            or d.manager_id is null
            or not exists (select 1 from public.profiles m where m.id = d.manager_id and m.active));
  end loop;

  -- 6. Unused departments (replace): delete only if nobody, active or not, is in them.
  foreach v_code in array coalesce(p_delete_departments, '{}'::text[]) loop
    select id into v_dept from public.departments where company_id = p_company_id and code = upper(btrim(v_code));
    if v_dept is null then
      continue;
    end if;
    if exists (select 1 from public.profiles where department_id = v_dept) then
      v_not_deleted := v_not_deleted || upper(btrim(v_code));
    else
      delete from public.departments where id = v_dept;
      v_deleted := v_deleted || upper(btrim(v_code));
      insert into public.audit_log (actor_id, action, entity, entity_id, after)
      values (v_caller, 'bulk_delete_department', 'departments', v_dept, jsonb_build_object('code', upper(btrim(v_code))));
    end if;
  end loop;

  insert into public.audit_log (actor_id, action, entity, entity_id, after)
  values (v_caller, 'bulk_import', 'profiles', null,
          jsonb_build_object('mode', p_mode, 'rows', jsonb_array_length(p_rows),
                             'created', jsonb_array_length(v_created), 'updated', v_updated,
                             'deactivated', v_deactivated, 'departments_deleted', to_jsonb(v_deleted),
                             'overwrite_balances', coalesce(p_overwrite_balances, false),
                             'balance_as_of', p_balance_as_of));

  return jsonb_build_object(
    'created', v_created,
    'updated', v_updated,
    'deactivated', v_deactivated,
    'deleted_departments', to_jsonb(v_deleted),
    'not_deleted_departments', to_jsonb(v_not_deleted)
  );
end;
$_$;


--
-- Name: app_bulk_set_employee_passwords(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_bulk_set_employee_passwords(p_resets jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid   uuid := auth.uid();
  v_row   record;
  v_count int;
begin
  if not private.is_admin(v_uid) then
    raise exception 'not allowed to reset passwords' using errcode = '42501';
  end if;
  if jsonb_typeof(p_resets) <> 'array' then
    raise exception 'password resets must be an array' using errcode = '22023';
  end if;

  v_count := jsonb_array_length(p_resets);
  if v_count < 1 or v_count > 100 then
    raise exception 'select between 1 and 100 employees' using errcode = '22023';
  end if;

  if (
    select count(*) <> count(distinct item->>'user_id')
      from jsonb_array_elements(p_resets) item
  ) then
    raise exception 'duplicate employee in password reset' using errcode = '22023';
  end if;

  -- Validate the complete payload before changing the first credential.
  for v_row in
    select (item->>'user_id')::uuid as user_id, item->>'password' as password
      from jsonb_array_elements(p_resets) item
  loop
    if v_row.user_id = v_uid then
      raise exception 'cannot bulk-reset your own password' using errcode = '22023';
    end if;
    if length(coalesce(v_row.password, '')) < 8 then
      raise exception 'new password must be at least 8 characters' using errcode = '22023';
    end if;
    if octet_length(coalesce(v_row.password, '')) > 72 then
      raise exception 'new password must be at most 72 ASCII characters' using errcode = '22023';
    end if;
    if not exists (
      select 1
        from auth.users u
        join public.profiles p on p.id = u.id
       where u.id = v_row.user_id
    ) then
      raise exception 'employee not found' using errcode = 'P0002';
    end if;
    if not private.can_reset_password(v_uid, v_row.user_id) then
      raise exception 'not allowed on %',
        (select coalesce(personnel_no, employee_code) from public.profiles where id = v_row.user_id)
        using errcode = '42501';
    end if;
  end loop;

  for v_row in
    select (item->>'user_id')::uuid as user_id, item->>'password' as password
      from jsonb_array_elements(p_resets) item
  loop
    update auth.users
       set encrypted_password = extensions.crypt(v_row.password, extensions.gen_salt('bf')),
           updated_at = now()
     where id = v_row.user_id;

    perform set_config('bj.password_flag_write', 'on', true);
    update public.profiles
       set must_change_password = true
     where id = v_row.user_id;
    perform set_config('bj.password_flag_write', '', true);

    insert into public.audit_log (actor_id, action, entity, entity_id)
    values (v_uid, 'reset_password', 'auth.users', v_row.user_id);
  end loop;
end;
$$;


