-- Name: app_can_read_approval_request(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_can_read_approval_request(p_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
