    AS $$
  select private.can_read_approval_request(auth.uid(),p_id);
$$;


--
-- Name: app_cancel_separation(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_cancel_separation(p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid     uuid := auth.uid();
  v_company uuid := private.separation_caller_company(v_uid);
  s         record;
begin
  select * into s from public.separations where id = p_id and company_id = v_company for update;
  if not found then
    raise exception 'clearance form not found' using errcode = 'P0002';
  end if;
  perform private.separation_manageable(v_uid, v_company, s.employee_id);
  if s.status = 'cancelled' then
    raise exception 'form is not open for changes' using errcode = '22023';
  end if;
  if s.deactivated_at is not null then
    raise exception 'form already applied' using errcode = '22023';
  end if;
  update public.separations set status = 'cancelled', cancelled_by = v_uid, cancelled_at = now()
   where id = p_id;
  insert into public.audit_log (actor_id, action, entity, entity_id, after)
  values (v_uid, 'separation.cancel', 'separations', p_id, null);
end; $$;


--
-- Name: app_change_my_password(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_change_my_password(p_current text, p_new text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  v_ok  boolean;
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not private.is_active(v_uid) then
    raise exception 'account is inactive' using errcode = '42501';
  end if;
  if length(coalesce(p_new, '')) < 8 then
    raise exception 'new password must be at least 8 characters' using errcode = '22023';
  end if;
  if octet_length(coalesce(p_new, '')) > 72 then
    raise exception 'new password must be at most 72 ASCII characters' using errcode = '22023';
  end if;
  if p_new = p_current then
    raise exception 'new password must differ from the current password' using errcode = '22023';
  end if;

  select encrypted_password = extensions.crypt(p_current, encrypted_password)
    into v_ok
    from auth.users
   where id = v_uid;
  if not coalesce(v_ok, false) then
    raise exception 'current password is incorrect' using errcode = '42501';
  end if;

  update auth.users
     set encrypted_password = extensions.crypt(p_new, extensions.gen_salt('bf')),
         updated_at = now()
   where id = v_uid;

  perform set_config('bj.password_flag_write', 'on', true);
  update public.profiles
     set must_change_password = false
   where id = v_uid and must_change_password;
  perform set_config('bj.password_flag_write', '', true);

  insert into public.audit_log(actor_id, action, entity, entity_id)
  values (v_uid, 'change_own_password', 'auth.users', v_uid);
end;
$$;


--
-- Name: app_cleanup_e2e_users(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_cleanup_e2e_users() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_uid uuid := auth.uid();
  v_count integer;
  v_steps integer;
begin
  if v_uid is null then raise exception 'not authenticated' using errcode = '42501'; end if;
  if not private.is_admin(v_uid) then
    raise exception 'admin role required' using errcode = '42501';
  end if;

  -- The junk predicate, unchanged from 20260702140000. Kept verbatim rather than
  -- factored out: it is the whole safety boundary of this function, and both
  -- shapes matter (see DATA_MODEL — codes before and after the prefix change).
  create temp table if not exists _e2e_junk on commit drop as
    select id from public.profiles
    where employee_code ~ '^(mgr|emp|cxl|auth|peer|lv|non|ov|e2e|set)[0-9]{13}$'
       or employee_code ~ '^(set|pwd)[0-9]{6}$'
       or employee_code ~ '^[a-z0-9]{2,6}-999[0-9]{7}$'
       or employee_code ~ '^999[0-9]{7}$';

  -- FR-42: drop approval steps naming one of these accounts first, or the
  -- foreign key refuses the delete below. Scoped to junk ids only — a step
  -- naming a real employee is never touched.
  delete from public.approval_steps s
   using _e2e_junk j
   where s.approver_id = j.id;
  get diagnostics v_steps = row_count;

  -- Review fix: delegation history references profiles without ON DELETE; remove the
  -- throwaway accounts' rows first.
  delete from public.approval_delegations d using _e2e_junk j
   where d.principal_id = j.id or d.delegate_id = j.id or d.configured_by = j.id;
  update public.approval_executive_settings x set
    ceo_id = case when x.ceo_id in (select id from _e2e_junk) then null else x.ceo_id end,
    hr_head_id = case when x.hr_head_id in (select id from _e2e_junk) then null else x.hr_head_id end,
    configured_by = case when x.configured_by in (select id from _e2e_junk) then null else x.configured_by end
   where x.ceo_id in (select id from _e2e_junk) or x.hr_head_id in (select id from _e2e_junk)
      or x.configured_by in (select id from _e2e_junk);

  with del as (
    delete from auth.users u using _e2e_junk j where u.id = j.id returning u.id
  )
  select count(*) into v_count from del;

  if v_count > 0 or v_steps > 0 then
    insert into public.audit_log (actor_id, action, entity, entity_id, after)
    values (v_uid, 'cleanup_e2e_users', 'auth.users', null,
            jsonb_build_object('deleted', v_count, 'approval_steps_removed', v_steps));
  end if;

  return v_count;
end;
$_$;


--
-- Name: app_create_employee(text, text, text, uuid, uuid, uuid, public.app_role[], date, text, text, text, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_create_employee(p_personnel_no text, p_full_name text, p_password text, p_company_id uuid, p_department_id uuid DEFAULT NULL::uuid, p_manager_id uuid DEFAULT NULL::uuid, p_roles public.app_role[] DEFAULT ARRAY['employee'::public.app_role], p_hire_date date DEFAULT NULL::date, p_language_pref text DEFAULT 'fa'::text, p_calendar_pref text DEFAULT 'jalali'::text, p_job_title text DEFAULT NULL::text, p_role_ids uuid[] DEFAULT NULL::uuid[]) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_caller uuid := auth.uid();
  v_admin  boolean;
  v_hr     boolean;
  v_dept   uuid;
  v_mgr    uuid;
  v_roles  public.app_role[];
  v_company uuid;
  v_uid    uuid;
  v_emp_role uuid;
  lt       record;
begin
  if v_caller is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  v_admin := private.is_admin(v_caller);
  v_hr := private.has_perm(v_caller, 'people_create', 'edit');

  -- D1: no path adds admin, whichever branch below runs.
  if 'admin' = any (coalesce(p_roles, '{}')) then
    raise exception 'admin is moved only by Transfer admin' using errcode = '42501';
  end if;

  if v_admin then
    -- Tenant binding: an admin names the company, but only their own.
    if p_company_id is distinct from
       (select company_id from public.profiles where id = v_caller) then
      raise exception 'not allowed to create employees in another company'
        using errcode = '42501';
    end if;
    v_dept := p_department_id;
    v_mgr := p_manager_id;
    v_roles := p_roles;
    v_company := p_company_id;
  elsif v_hr then
    -- FR-35 / spec D4. HR onboards into ANY department and sets the reporting
    -- line, which is what makes them useful. But the enum role list is overwritten
    -- here regardless of what the client sent; extra roles come only through
    -- p_role_ids, which D5 checks. Checked before the manager branch so someone
    -- holding both gets the wider scope.
    --
    -- The company comes from the caller's own profile rather than the argument,
    -- matching the manager branch: only an admin may name the company.
    select company_id into v_company from public.profiles where id = v_caller;
    v_dept := p_department_id;
    v_mgr := p_manager_id;
    v_roles := array['employee']::public.app_role[];
  elsif private.has_role(v_caller, 'manager') then
    -- Managers onboard into their own team only; every privileged input is
    -- overwritten here regardless of what the client sent.
    select department_id, company_id into v_dept, v_company
      from public.profiles where id = v_caller;
    if v_dept is null then
      raise exception 'manager has no department' using errcode = '22023';
    end if;
    v_mgr := v_caller;
    v_roles := array['employee']::public.app_role[];
  else
    raise exception 'admin or manager role required' using errcode = '42501';
  end if;

  -- With role ids, the enum list is just Employee; the ids decide the rest below.
  if p_role_ids is not null then
    v_roles := array['employee']::public.app_role[];
  end if;

  v_uid := private.create_employee_impl(
    v_caller, case when v_admin then 'admin' when v_hr then 'hr' else 'manager' end,
    v_company, v_dept, v_mgr, p_personnel_no, p_full_name, p_password,
    v_roles, p_hire_date, p_language_pref, p_calendar_pref, p_job_title);

  -- D5 for non-admins (and D1 for everyone) through the assignment RPC. Skipped
  -- when the ids add nothing beyond Employee, so a plain manager still onboards.
  select id into v_emp_role from public.roles where company_id = v_company and system_key = 'employee';
  if p_role_ids is not null
     and exists (select 1 from unnest(p_role_ids) x where x is distinct from v_emp_role) then
    perform public.app_set_user_role_ids(v_uid, p_role_ids || v_emp_role);
  end if;

  -- Manager and HR paths: default quotas immediately, no admin round-trip.
  -- (`not v_admin` is both of them.)
  if not v_admin then
    for lt in
      select id, default_annual_quota_days
        from public.leave_types
       where company_id = v_company and active and affects_balance
         and coalesce(default_annual_quota_days, 0) > 0
    loop
      perform private.allocate_leave_impl(
        v_caller, v_uid, lt.id,
        date_trunc('year', current_date)::date,
        (date_trunc('year', current_date) + interval '1 year - 1 day')::date,
        round(lt.default_annual_quota_days * private.company_minutes_per_day(v_company))::int);
    end loop;
  end if;

  return v_uid;
end; $$;


--
-- Name: app_create_separation(uuid, text, date, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_create_separation(p_employee_id uuid, p_reason text, p_last_working_day date, p_father_name text, p_birth_cert_no text, p_note text, p_rows jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_uid     uuid := auth.uid();
  v_company uuid := private.separation_caller_company(v_uid);
  v_father  text := nullif(btrim(p_father_name), '');
  v_cert    text := nullif(btrim(p_birth_cert_no), '');
  v_note    text := nullif(btrim(p_note), '');
  v_hr_fa   text;
  v_hr_en   text;
  v_id      uuid;
  v_row     jsonb;
  v_i       integer := 0;
begin
  if p_employee_id = v_uid then
    raise exception 'cannot file a clearance form for yourself' using errcode = '42501';
  end if;
  perform private.separation_manageable(v_uid, v_company, p_employee_id);
  perform private.separation_check_fields(p_reason, p_last_working_day, v_note);
  if v_father is not null and char_length(v_father) > 100 then
    raise exception 'invalid father name' using errcode = '22023';
  end if;
  if v_cert is not null and v_cert !~ '^[0-9]{1,10}$' then
    raise exception 'invalid birth certificate number' using errcode = '22023';
  end if;
  if p_rows is null or jsonb_typeof(p_rows) <> 'array' then
    raise exception 'invalid rows' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('separation:' || p_employee_id::text, 0));
  if exists (select 1 from public.separations
              where employee_id = p_employee_id and status <> 'cancelled' and deactivated_at is null) then
    raise exception 'employee already has an open clearance form' using errcode = '23505';
  end if;
  -- The last active admin can never be switched off; refuse the form up front.
  if exists (select 1 from public.user_roles where user_id = p_employee_id and role = 'admin')
     and not exists (select 1 from public.profiles p
                       join public.user_roles r on r.user_id = p.id and r.role = 'admin'
                      where p.active and p.id <> p_employee_id) then
    raise exception 'cannot deactivate the last active admin' using errcode = '22023';
  end if;

  -- D8: personal info wins; what HR typed fills only what is missing there, and is
  -- written back so the profile is complete next time.
  update public.employee_personal_info
     set father_name   = coalesce(father_name, v_father),
         birth_cert_no = coalesce(birth_cert_no, v_cert)
   where employee_id = p_employee_id
     and ((father_name is null and v_father is not null)
          or (birth_cert_no is null and v_cert is not null));
  select coalesce(i.father_name, v_father), coalesce(i.birth_cert_no, v_cert)
    into v_father, v_cert
    from (select 1) one
    left join public.employee_personal_info i on i.employee_id = p_employee_id;

  insert into public.separations (company_id, employee_id, reason, last_working_day, hire_date,
                                  father_name, birth_cert_no, note, created_by)
  select v_company, p_employee_id, p_reason, p_last_working_day, p.hire_date,
         v_father, v_cert, v_note, v_uid
    from public.profiles p where p.id = p_employee_id
  returning id into v_id;

  select name_fa, name_en into v_hr_fa, v_hr_en
    from public.separation_units where company_id = v_company and kind = 'hr';
  insert into public.separation_signoffs (separation_id, is_hr, name_fa, name_en, sort_order)
  values (v_id, true, coalesce(v_hr_fa, 'مدیر اداری و منابع انسانی'),
          coalesce(v_hr_en, 'HR & administration'), 0);

  for v_row in select value from jsonb_array_elements(p_rows) loop
    v_i := v_i + 1;
    insert into public.separation_signoffs (separation_id, name_fa, name_en, department_id, signer_id, sort_order)
    values (v_id, btrim(v_row->>'name_fa'), btrim(v_row->>'name_en'),
            nullif(v_row->>'department_id', '')::uuid,
            private.separation_row_signer(v_company, p_employee_id, v_row), v_i);
  end loop;

  insert into public.audit_log (actor_id, action, entity, entity_id, after)
  values (v_uid, 'separation.create', 'separations', v_id,
          jsonb_build_object('employee_id', p_employee_id, 'reason', p_reason,
                             'last_working_day', p_last_working_day, 'rows', v_i + 1));

  perform private.apply_due_separations(v_id);
  return v_id;
end; $_$;


--
-- Name: app_delegation_context(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_delegation_context(p_principal_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_uid uuid:=auth.uid(); v_principal uuid:=coalesce(p_principal_id,auth.uid());
  v_company uuid; v_name text; v_saved uuid; v_effective uuid; v_admin boolean; v_settings jsonb;
begin
  if not private.is_active(v_uid) then raise exception 'not authenticated' using errcode='42501'; end if;
  select company_id into v_company from public.profiles where id=v_uid;
  v_admin:=private.is_admin(v_uid);
  if (v_principal<>v_uid and not v_admin) or not exists (select 1 from public.profiles
      where id=v_principal and company_id=v_company) then raise exception 'not permitted' using errcode='42501'; end if;
  select full_name into v_name from public.profiles where id=v_principal;
  select id into v_saved from public.approval_delegations where principal_id=v_principal
    and source_request_id is null and revoked_at is null;
  select id into v_effective from private.effective_approval_delegate(v_principal);
  select jsonb_build_object('ceo_id',x.ceo_id,'hr_head_id',x.hr_head_id,'hr_step_ids',x.hr_step_ids,
    'version',x.version) into v_settings from public.approval_executive_settings x where company_id=v_company;
  return jsonb_build_object('principal_id',v_principal,'principal_name',v_name,'is_admin',v_admin,
    'can_delegate',private.has_perm(v_principal,'approval_delegate','edit'),
    'can_approve',private.natural_approver(v_principal),
    'saved',private.approval_grant_json(v_saved),'effective',private.approval_grant_json(v_effective),
    'executive_settings',coalesce(v_settings,'{}'),
    'principals',case when v_admin then coalesce((select jsonb_agg(jsonb_build_object(
      'profile_id',p.id,'full_name',p.full_name,'employee_code',p.employee_code) order by p.full_name)
      from public.profiles p where p.company_id=v_company and p.active),'[]') else '[]'::jsonb end,
    'hr_steps',case when v_admin then coalesce((select jsonb_agg(jsonb_build_object(
      'step_id',s.id,'step_role',s.role,'step_order',s.step_order,'expected_name',p.full_name) order by s.step_order)
      from public.approval_steps s left join public.profiles p on p.id=s.approver_id
      where s.company_id=v_company and s.active),'[]') else '[]'::jsonb end);
end; $$;


--
-- Name: app_delete_role(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_delete_role(p_id uuid) RETURNS TABLE(full_name text, personnel_no text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  v_kind text;
  v_holders jsonb;
begin
  if not private.is_admin(v_uid) then
    raise exception 'only the admin can delete roles' using errcode = '42501';
  end if;
  select kind into v_kind from public.roles where id = p_id and company_id = private.caller_company() for update;
  if v_kind is null then raise exception 'role not found' using errcode = '22023'; end if;
  if v_kind <> 'custom' then raise exception 'built-in roles cannot be deleted' using errcode = '22023'; end if;

  select coalesce(jsonb_agg(jsonb_build_object('full_name', p.full_name, 'personnel_no', p.personnel_no)
                            order by p.personnel_no), '[]'::jsonb)
    into v_holders
    from public.user_roles ur join public.profiles p on p.id = ur.user_id where ur.role_id = p_id;

  delete from public.user_roles where role_id = p_id;
  insert into public.audit_log (actor_id, action, entity, entity_id, before, after)
  values (v_uid, 'role.delete', 'roles', p_id,
          jsonb_build_object('name', (select name from public.roles where id = p_id), 'holders', v_holders), null);
  delete from public.roles where id = p_id;

  return query select h->>'full_name', h->>'personnel_no' from jsonb_array_elements(v_holders) h;
end $$;


--
-- Name: app_export_personal_info(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_export_personal_info() RETURNS TABLE(personnel_no text, employee_code text, full_name text, active boolean, national_id text, birth_cert_no text, father_name text, birth_date date, birth_place text, gender text, marital_status text, bank_name text, bank_account_no text, sheba text, card_no text, mobile text, home_phone text, address text, postal_code text, emergency_name text, emergency_phone text, insurance_no text, education text, military_status text, children_count smallint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid     uuid := auth.uid();
  v_company uuid;
  v_count   int;
begin
  if not private.has_perm(v_uid, 'personal_info', 'read') then
    raise exception 'not permitted to export personal info' using errcode = '42501';
  end if;
  select company_id into v_company from public.profiles where id = v_uid;

  select count(*) into v_count from public.employee_personal_info where company_id = v_company;
  insert into public.audit_log(actor_id, action, entity, entity_id, after)
  values (v_uid, 'personal_info.export', 'employee_personal_info', null,
          jsonb_build_object('rows', v_count));

  return query
    select p.personnel_no, p.employee_code, p.full_name, p.active,
           i.national_id, i.birth_cert_no, i.father_name, i.birth_date, i.birth_place,
           i.gender, i.marital_status, i.bank_name, i.bank_account_no, i.sheba,
           i.card_no, i.mobile, i.home_phone, i.address, i.postal_code,
           i.emergency_name, i.emergency_phone, i.insurance_no, i.education,
           i.military_status, i.children_count
      from public.employee_personal_info i
      join public.profiles p on p.id = i.employee_id
     where i.company_id = v_company
     order by p.active desc, p.personnel_no nulls last, p.full_name;
end; $$;


--
-- Name: app_get_separation(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_get_separation(p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v jsonb;
begin
  if not private.can_read_separation(auth.uid(), p_id) then
    raise exception 'clearance form not found' using errcode = 'P0002';
  end if;
  select jsonb_build_object(
           'id', s.id, 'status', s.status, 'reason', s.reason,
           'last_working_day', s.last_working_day, 'hire_date', s.hire_date,
           'father_name', s.father_name, 'birth_cert_no', s.birth_cert_no, 'note', s.note,
           'settlement_date', s.settlement_date, 'finance_note', s.finance_note,
           'finance_signed_at', s.finance_signed_at, 'finance_signed_by_name', fs.full_name,
           'deactivated_at', s.deactivated_at, 'created_at', s.created_at,
           'created_by_name', cb.full_name, 'cancelled_at', s.cancelled_at,
           'employee', jsonb_build_object(
             'id', p.id, 'name', p.full_name, 'personnel_no', p.personnel_no,
             'department_id', p.department_id, 'department_name_fa', d.name_fa,
             'department_name_en', d.name_en, 'active', p.active),
           'rows', coalesce((
             select jsonb_agg(jsonb_build_object(
                      'id', o.id, 'is_hr', o.is_hr, 'name_fa', o.name_fa, 'name_en', o.name_en,
                      'department_id', o.department_id, 'signer_id', o.signer_id,
                      'signer_name', sp.full_name, 'sort_order', o.sort_order,
                      'signed_by', o.signed_by, 'signed_by_name', sb.full_name,
                      'signed_at', o.signed_at, 'note', o.note)
                    order by o.is_hr desc, o.sort_order)
               from public.separation_signoffs o
               left join public.profiles sp on sp.id = o.signer_id
               left join public.profiles sb on sb.id = o.signed_by
              where o.separation_id = s.id), '[]'::jsonb))
    into v
    from public.separations s
    join public.profiles p on p.id = s.employee_id
    left join public.departments d on d.id = p.department_id
    left join public.profiles fs on fs.id = s.finance_signed_by
    left join public.profiles cb on cb.id = s.created_by
   where s.id = p_id;
  return v;
end; $$;


--
-- Name: app_grant_special_leave(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_grant_special_leave(p_employee_id uuid, p_kind text, p_note text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid     uuid := auth.uid();
  v_company uuid;
  v_type    uuid;
  v_minutes int;
  v_prev    int;
  v_status  text;
  v_id      uuid;
  v_note    text := nullif(btrim(coalesce(p_note, '')), '');
begin
  v_company := private.special_leave_target(v_uid, p_employee_id);
  if p_kind not in ('marriage', 'bereavement') then
    raise exception 'invalid special leave kind' using errcode = '22023';
  end if;
  -- FR-65 amendment: HR records why each bereavement grant was made.
  if p_kind = 'bereavement' and v_note is null then
    raise exception 'a note is required for bereavement leave' using errcode = '22023';
  end if;
  if length(v_note) > 500 then
    raise exception 'special leave note is too long (max 500 characters)' using errcode = '22023';
  end if;

  select id into v_type from public.leave_types
   where company_id = v_company and name_en = 'Annual Leave' and active
   limit 1;
  if v_type is null then
    raise exception 'annual leave type not found' using errcode = 'P0002';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('leave:' || p_employee_id::text, 0));

  if p_kind = 'marriage' then
    if exists (select 1 from public.special_leave_grants
                where employee_id = p_employee_id and kind = 'marriage' and revoked_at is null) then
      raise exception 'marriage leave was already granted' using errcode = '22023';
    end if;
    select marital_status into v_status from public.employee_personal_info where employee_id = p_employee_id;
    if v_status is distinct from 'single' then
      raise exception 'marriage leave needs marital status single' using errcode = '22023';
    end if;
  end if;

  v_minutes := 3 * private.company_minutes_per_day(v_company);
  v_prev := public.current_leave_balance(p_employee_id, v_type);

  insert into public.special_leave_grants (company_id, employee_id, kind, leave_type_id, minutes, prev_marital_status, granted_by, note)
  values (v_company, p_employee_id, p_kind, v_type, v_minutes, v_status, v_uid, v_note)
  returning id into v_id;

  insert into public.leave_ledger (employee_id, leave_type_id, entry_type, delta_minutes, balance_after_minutes, note)
  values (p_employee_id, v_type, 'allocation', v_minutes, v_prev + v_minutes,
          case p_kind when 'marriage' then 'marriage leave (3 days)' else 'bereavement leave (3 days)' end);

  if p_kind = 'marriage' then
    update public.employee_personal_info set marital_status = 'married' where employee_id = p_employee_id;
  end if;

  insert into public.audit_log (actor_id, action, entity, entity_id, after)
  values (v_uid, 'special_leave.grant', 'special_leave_grants', v_id,
          jsonb_build_object('employee_id', p_employee_id, 'kind', p_kind, 'minutes', v_minutes, 'note', v_note));
  return v_id;
end; $$;


--
-- Name: app_import_personal_info(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_import_personal_info(p_rows jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid      uuid := auth.uid();
  v_company  uuid;
  v_is_admin boolean := private.is_admin(auth.uid());
  v_row      jsonb;
  v_pno      text;
  v_target   uuid;
  v_updated  int := 0;
  v_fields   constant text[] := array[
    'national_id','birth_cert_no','father_name','birth_date','birth_place','gender',
    'marital_status','bank_name','bank_account_no','sheba','card_no','mobile','home_phone',
    'address','postal_code','emergency_name','emergency_phone','insurance_no','education',
    'military_status','children_count'];
  v_key      text;
begin
  if not private.has_perm(v_uid, 'personal_info', 'edit') then
    raise exception 'not permitted to import personal info' using errcode = '42501';
  end if;
  if jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) = 0 then
    raise exception 'no rows to import' using errcode = '22023';
  end if;
  if jsonb_array_length(p_rows) > 2000 then
    raise exception 'too many rows (max 2000)' using errcode = '22023';
  end if;
  select company_id into v_company from public.profiles where id = v_uid;

  if (select count(distinct r->>'personnel_no') <> count(*) from jsonb_array_elements(p_rows) r) then
    raise exception 'duplicate personnel number in file' using errcode = '22023';
  end if;

  for v_row in select * from jsonb_array_elements(p_rows) loop
    v_pno := v_row->>'personnel_no';
    select id into v_target from public.profiles
     where company_id = v_company and personnel_no = v_pno;
    if v_target is null then
      raise exception 'unknown personnel number: %', coalesce(v_pno, '(empty)') using errcode = '22023';
    end if;
    -- FR-63: one's own row follows personal_info_own, not the import.
    if v_target = v_uid then
      if not private.has_perm(v_uid, 'personal_info_own', 'edit') then
        raise exception 'not permitted to edit your own personal info: %', v_pno using errcode = '42501';
      end if;
    elsif not v_is_admin and not private.can_act_on(v_uid, v_target) then
      raise exception 'not permitted to edit this person''s personal info: %', v_pno using errcode = '42501';
    end if;
    for v_key in select jsonb_object_keys(v_row) loop
      if v_key <> 'personnel_no' and not (v_key = any (v_fields)) then
        raise exception 'unknown field: %', v_key using errcode = '22023';
      end if;
    end loop;

    update public.employee_personal_info i set
      national_id     = coalesce(v_row->>'national_id', i.national_id),
      birth_cert_no   = coalesce(v_row->>'birth_cert_no', i.birth_cert_no),
      father_name     = coalesce(v_row->>'father_name', i.father_name),
      birth_date      = coalesce((v_row->>'birth_date')::date, i.birth_date),
      birth_place     = coalesce(v_row->>'birth_place', i.birth_place),
      gender          = coalesce(v_row->>'gender', i.gender),
      marital_status  = coalesce(v_row->>'marital_status', i.marital_status),
      bank_name       = coalesce(v_row->>'bank_name', i.bank_name),
      bank_account_no = coalesce(v_row->>'bank_account_no', i.bank_account_no),
      sheba           = coalesce(v_row->>'sheba', i.sheba),
      card_no         = coalesce(v_row->>'card_no', i.card_no),
      mobile          = coalesce(v_row->>'mobile', i.mobile),
      home_phone      = coalesce(v_row->>'home_phone', i.home_phone),
      address         = coalesce(v_row->>'address', i.address),
      postal_code     = coalesce(v_row->>'postal_code', i.postal_code),
      emergency_name  = coalesce(v_row->>'emergency_name', i.emergency_name),
      emergency_phone = coalesce(v_row->>'emergency_phone', i.emergency_phone),
      insurance_no    = coalesce(v_row->>'insurance_no', i.insurance_no),
      education       = coalesce(v_row->>'education', i.education),
      military_status = coalesce(v_row->>'military_status', i.military_status),
      children_count  = coalesce((v_row->>'children_count')::smallint, i.children_count)
     where i.employee_id = v_target;
    v_updated := v_updated + 1;
  end loop;

  insert into public.audit_log(actor_id, action, entity, entity_id, after)
  values (v_uid, 'personal_info.import', 'employee_personal_info', null,
          jsonb_build_object('rows', v_updated));

  return jsonb_build_object('updated', v_updated);
end; $$;


--
-- Name: app_list_roles(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_list_roles() RETURNS TABLE(id uuid, system_key text, kind text, name text, holders integer, permissions jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select r.id, r.system_key::text, r.kind, r.name,
         (select count(*)::int from public.user_roles ur join public.profiles p on p.id = ur.user_id
           where ur.role_id = r.id and p.active),
         coalesce((select jsonb_object_agg(rp.permission, rp.level) from public.role_permissions rp
                    where rp.role_id = r.id), '{}'::jsonb)
    from public.roles r
   where r.company_id = private.caller_company()
   order by case r.kind when 'system' then 0 when 'preset' then 1 else 2 end,
            array_position(array['admin','manager','employee','hr','security','finance'], r.system_key::text),
            lower(r.name);
$$;


--
-- Name: app_list_separations(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_list_separations() RETURNS TABLE(id uuid, employee_id uuid, employee_name text, personnel_no text, department_name_fa text, department_name_en text, status text, reason text, last_working_day date, deactivated_at timestamp with time zone, created_at timestamp with time zone, rows_total integer, rows_signed integer, awaiting_me boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select s.id, s.employee_id, p.full_name, p.personnel_no, d.name_fa, d.name_en,
         s.status, s.reason, s.last_working_day, s.deactivated_at, s.created_at,
         (select count(*)::int from public.separation_signoffs o where o.separation_id = s.id),
         (select count(*)::int from public.separation_signoffs o where o.separation_id = s.id and o.signed_at is not null),
         s.employee_id <> auth.uid() and (
           (s.status = 'in_progress' and exists (
              select 1 from public.separation_signoffs o
               where o.separation_id = s.id and o.signed_at is null
                 and ((not o.is_hr and o.signer_id = auth.uid())
                      or (o.is_hr and (private.has_role(auth.uid(), 'hr') or private.is_admin(auth.uid()))))))
           or (s.status = 'awaiting_finance' and private.has_role(auth.uid(), 'finance')))
    from public.separations s
    join public.profiles p on p.id = s.employee_id
    left join public.departments d on d.id = p.department_id
   where private.can_read_separation(auth.uid(), s.id)
   order by s.created_at desc
   limit 500;
$$;


--
-- Name: app_my_permissions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_my_permissions() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(jsonb_object_agg(k, case l when 2 then 'edit' else 'read' end), '{}'::jsonb)
    from (select k, private.perm_level(auth.uid(), k) l from private.permission_keys() k) s
   where l > 0 and private.is_active(auth.uid());
$$;


--
-- Name: app_password_reset_eligible(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_password_reset_eligible(p_ids uuid[]) RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select distinct x
    from unnest(coalesce(p_ids, '{}'::uuid[])) x
   where x is distinct from auth.uid()
     and private.can_reset_password(auth.uid(), x);
$$;


--
-- Name: app_request_approval_context(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_request_approval_context(p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r public.leave_requests%rowtype; v_progress jsonb; v_result jsonb;
begin
  if not private.can_read_approval_request(auth.uid(),p_id) then
    raise exception 'request not found' using errcode='P0002'; end if;
  select * into r from public.leave_requests where id=p_id;
  v_progress:=public.app_request_approval_progress(p_id);
  select (to_jsonb(r)-'signature_data'-'approver_signature_data')||jsonb_build_object(
    'employee_name',p.full_name,'employee_code',p.employee_code,
    'personnel_no',case when p.id=auth.uid() or private.reads_people(auth.uid()) or private.is_manager_of(auth.uid(),p.id) then p.personnel_no end,
    'job_title',case when p.id=auth.uid() or private.reads_people(auth.uid()) or private.is_manager_of(auth.uid(),p.id) then p.job_title end,
    'employee_manager_id',p.manager_id,'department_id',p.department_id,
    'department_name',dep.name_fa,'department_name_fa',dep.name_fa,'department_name_en',dep.name_en,
    'employee_department_manager_id',private.department_manager_for(p.id),
    'leave_type_name_fa',lt.name_fa,'leave_type_name_en',lt.name_en,'affects_balance',lt.affects_balance,
    'leave_type_affects_balance',lt.affects_balance,'is_paid',lt.is_paid,
    'replacement_name',rp.full_name,'decided_by_name',dp.full_name,
    'replacement_conflict',case when r.replacement_id is null then false else
      private.replacement_is_away(r.replacement_id,r.start_date,r.end_date,r.unit,r.start_time,r.end_time) end,
    'can_override',r.status='pending' and private.is_admin(auth.uid()),
    'can_approve',r.status='pending' and (private.is_admin(auth.uid()) or exists
      (select 1 from jsonb_array_elements(v_progress) item where (item->>'can_approve')::boolean)),
    'can_reject',r.status='pending' and (private.is_admin(auth.uid()) or exists
      (select 1 from jsonb_array_elements(v_progress) item where (item->>'can_reject')::boolean)),
    'configuration_changed',coalesce(pol.configuration_changed,false),
    'legacy_reconciliation_required',private.ambiguous_legacy_approval(r.id),
    'progress',v_progress)
  into v_result from public.profiles p left join public.departments dep on dep.id=p.department_id
    left join public.leave_types lt on lt.id=r.leave_type_id
    left join public.profiles rp on rp.id=r.replacement_id left join public.profiles dp on dp.id=r.decided_by
    left join public.approval_request_policy pol on pol.request_id=r.id where p.id=r.employee_id;
  return v_result;
end; $$;


--
-- Name: app_request_approval_progress(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_request_approval_progress(p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r public.leave_requests%rowtype; v_result jsonb:='[]'; v_item jsonb;
  v_policy public.approval_request_policy%rowtype; v_done record; s record; v_snapshot jsonb;
  d public.approval_delegations%rowtype; v_natural boolean; v_allowed boolean; v_can_approve boolean; v_expected text;
begin
  if not private.can_read_approval_request(auth.uid(),p_id) then
    raise exception 'request not found' using errcode='P0002'; end if;
  select * into r from public.leave_requests where id=p_id;
  select * into v_policy from public.approval_request_policy where request_id=p_id;
  for v_done in select a.*,st.step_order,st.manager_scope,st.approver_id as expected_id,
      sp.full_name as live_signer,np.full_name as live_expected
    from public.leave_request_approvals a left join public.approval_steps st on st.id=a.step_id
      left join public.profiles sp on sp.id=a.approver_id left join public.profiles np on np.id=st.approver_id
    where a.request_id=p_id order by coalesce((a.evidence->>'step_order')::integer,st.step_order,1),a.created_at,a.id loop
    v_snapshot:=null;
    select item into v_snapshot from jsonb_array_elements(coalesce(v_policy.step_snapshot,'[]')) item
      where item->>'step_id'=v_done.step_id::text;
    v_result:=v_result||jsonb_build_array(jsonb_build_object(
      'step_id',v_done.step_id,'step_role',v_done.step_role,
      'step_order',coalesce((v_done.evidence->>'step_order')::integer,(v_snapshot->>'step_order')::integer,v_done.step_order,1),
      'manager_scope',coalesce(v_done.evidence->>'manager_scope',v_snapshot->>'manager_scope',v_done.manager_scope,'direct'),
      'named',coalesce((v_done.evidence->>'named')::boolean,case when v_snapshot is not null
        then (v_snapshot->>'approver_id') is not null else v_done.expected_id is not null end),
      'expected_name',coalesce(v_done.evidence->>'expected_name',v_snapshot->>'expected_name',v_done.live_expected,v_done.principal_name),
      'signer_name',case when v_done.evidence_kind='automatic' then null else coalesce(v_done.signer_name_snapshot,v_done.live_signer) end,
      'signed_at',v_done.created_at,'principal_name',v_done.principal_name,'principal_id',v_done.principal_id,
      'grant_id',v_done.authority_id,'authority_id',v_done.authority_id,'authority_ref',v_done.authority_id,
      'evidence_kind',v_done.evidence_kind,'decision',v_done.decision,
      'is_delegated',v_done.evidence_kind='delegated','can_approve',false,'can_reject',false,
      'per_diem_allowed',false,'statement',v_done.evidence->>'statement','evidence',v_done.evidence));
  end loop;
  for s in select st.* from public.approval_steps st
    where r.status='pending' and st.company_id=r.company_id and st.active and r.kind=any(st.applies_to)
      and private.step_applies(st.manager_scope,r.employee_id)
      and not private.request_step_decided(p_id,st.id)
    order by st.step_order,st.id loop
    v_snapshot:=null;
    select item into v_snapshot from jsonb_array_elements(coalesce(v_policy.step_snapshot,'[]')) item
      where item->>'step_id'=s.id::text;
    v_expected:=null;
    if s.approver_id is not null then select full_name into v_expected from public.profiles where id=s.approver_id;
    elsif s.role='manager' then select full_name into v_expected from public.profiles where id=
      case when s.manager_scope='department' then private.department_manager_for(r.employee_id)
      else (select manager_id from public.profiles where id=r.employee_id) end; end if;
    if private.request_hr_exempt(p_id,s.id) then
      v_expected:=v_snapshot->>'expected_name';
      v_item:=jsonb_build_object('evidence_kind','hr_exempt','can_approve',false,'can_reject',false,
        'is_delegated',false,'per_diem_allowed',false,'statement','Not required — request submitted by the Head of HR');
    else
      v_natural:=private.natural_step_authority(auth.uid(),p_id,s.id);
      d:=null;
      if not v_natural then select g.* into d from private.step_delegation(auth.uid(),p_id,s.id) g; end if;
      v_allowed:=r.status='pending' and (v_natural or d.id is not null);
      v_can_approve:=v_allowed and not (exists(select 1 from public.work_settings w
        where w.company_id=r.company_id and w.approval_order_enforced)
        and exists(select 1 from public.approval_steps earlier where private.request_step_applies(p_id,earlier.id)
          and earlier.step_order<s.step_order and not private.request_step_decided(p_id,earlier.id,'approved')));
      v_item:=jsonb_build_object('evidence_kind','pending','can_approve',v_can_approve,
        'can_reject',r.status='pending' and (v_allowed or private.is_admin(auth.uid())),
        'is_delegated',d.id is not null,'principal_id',d.principal_id,
        'principal_name',d.principal_name,'grant_id',d.id,'authority_id',d.id,
        'per_diem_allowed',v_can_approve and s.role='hr' and r.kind='errand');
    end if;
    v_result:=v_result||jsonb_build_array(v_item||jsonb_build_object('step_id',s.id,
      'step_role',s.role,'step_order',s.step_order,'manager_scope',s.manager_scope,
      'named',s.approver_id is not null,'expected_name',v_expected,'signer_name',null,
      'signed_at',null,'decision',null,
      'configuration_changed',coalesce(v_policy.configuration_changed,false),
      'historical_hr_exemption',case when s.id=any(coalesce(v_policy.hr_exempt_step_ids,'{}'))
        and not private.request_hr_exempt(p_id,s.id) then v_snapshot end));
  end loop;
  -- Preserve the exemption if the administrator later removes its configured step.
  for v_snapshot in select item from jsonb_array_elements(coalesce(v_policy.step_snapshot,'[]')) item
    where (item->>'step_id')::uuid=any(coalesce(v_policy.hr_exempt_step_ids,'{}'))
      and not exists(select 1 from jsonb_array_elements(v_result) shown where shown->>'step_id'=item->>'step_id') loop
    v_result:=v_result||jsonb_build_array(v_snapshot||jsonb_build_object('evidence_kind','hr_exempt',
      'named',(v_snapshot->>'approver_id') is not null,'principal_id',v_policy.hr_head_id,
      'can_approve',false,'can_reject',false,'is_delegated',false,'per_diem_allowed',false,
      'signer_name',null,'signed_at',null,'decision',null,
      'statement','Not required — request submitted by the Head of HR'));
  end loop;
  if jsonb_array_length(v_result)=0 and r.status='pending' then
    v_allowed:=private.approval_fallback_allowed(auth.uid(),p_id);
    v_result:=jsonb_build_array(jsonb_build_object('step_id',null,'step_role','manager','step_order',1,
      'manager_scope','direct','named',false,
      'expected_name',(select p.full_name from public.profiles emp join public.profiles p on p.id=emp.manager_id where emp.id=r.employee_id),
      'evidence_kind','pending','decision',null,'signer_name',null,'signed_at',null,
      'can_approve',v_allowed,'can_reject',v_allowed,'per_diem_allowed',false,
      'is_delegated',v_allowed and not private.is_manager_of(auth.uid(),r.employee_id) and not private.is_admin(auth.uid())));
  end if;
  return (select coalesce(jsonb_agg(item order by coalesce((item->>'step_order')::integer,1),item->>'step_id'),'[]')
    from jsonb_array_elements(v_result) item);
end; $$;


--
-- Name: app_request_delegation_preview(date, date, public.leave_unit, public.day_part, time without time zone, time without time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_request_delegation_preview(p_start date, p_end date, p_unit public.leave_unit DEFAULT 'day'::public.leave_unit, p_day_part public.day_part DEFAULT 'full'::public.day_part, p_start_time time without time zone DEFAULT NULL::time without time zone, p_end_time time without time zone DEFAULT NULL::time without time zone, p_replacement_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_uid uuid:=auth.uid(); v_company uuid; v_bounds jsonb; v_saved uuid; v_effective uuid;
  v_authority uuid; v_temporary boolean; v_auto boolean; v_result jsonb;
begin
  if not private.is_active(v_uid) then raise exception 'not authenticated' using errcode='42501'; end if;
  select company_id into v_company from public.profiles where id=v_uid;
  v_bounds:=private.approval_bounds(v_company,p_start,p_end,p_unit,p_day_part,p_start_time,p_end_time);
  select id into v_saved from public.approval_delegations where principal_id=v_uid
    and source_request_id is null and revoked_at is null and private.delegate_eligible(v_uid,delegate_id);
  select id into v_effective from private.effective_approval_delegate(v_uid);
  v_temporary:=p_replacement_id is not null and private.delegate_eligible(v_uid,p_replacement_id);
  select d.id into v_authority from public.approval_executive_settings x
    cross join lateral private.effective_approval_delegate(x.ceo_id) d
    where x.company_id=v_company and d.delegate_id=v_uid and d.ceo_authorized;
  v_auto:=v_authority is not null;
  v_result:=jsonb_build_object('principal_id',v_uid,'bounds',v_bounds,'saved',private.approval_grant_json(v_saved),
    'effective',private.approval_grant_json(v_effective),
    'temporary',case when v_temporary then jsonb_build_object('delegate_id',p_replacement_id,
      'delegate_name',(select full_name from public.profiles where id=p_replacement_id),
      'starts_at',v_bounds->'starts_at','ends_at',v_bounds->'ends_at') else null end,
    'can_approve',private.natural_approver(v_uid),'can_delegate',private.has_perm(v_uid,'approval_delegate','edit'),
    'auto_approval_eligible',v_auto,'authority_id',v_authority,
    'is_ceo',exists(select 1 from public.approval_executive_settings where company_id=v_company and ceo_id=v_uid),
    'temporary_eligible',v_temporary,'temporary_delegate_name',case when v_temporary then (select full_name from public.profiles where id=p_replacement_id) end,
    'replacement_id',p_replacement_id,'start',p_start,'end',p_end,'unit',p_unit,'day_part',p_day_part,
    'start_time',p_start_time,'end_time',p_end_time);
  return v_result||jsonb_build_object('preview_token',md5(v_result::text));
end; $$;


--
-- Name: app_revoke_special_leave(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_revoke_special_leave(p_grant_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid  uuid := auth.uid();
  v_g    public.special_leave_grants;
  v_prev int;
begin
  select * into v_g from public.special_leave_grants where id = p_grant_id;
  if v_g.id is null then
    raise exception 'special leave grant not found' using errcode = 'P0002';
  end if;
  perform private.special_leave_target(v_uid, v_g.employee_id);

  perform pg_advisory_xact_lock(hashtextextended('leave:' || v_g.employee_id::text, 0));

  update public.special_leave_grants
     set revoked_at = now(), revoked_by = v_uid
   where id = p_grant_id and revoked_at is null;
  if not found then
    raise exception 'special leave grant was already revoked' using errcode = '22023';
  end if;

  v_prev := public.current_leave_balance(v_g.employee_id, v_g.leave_type_id);
  insert into public.leave_ledger (employee_id, leave_type_id, entry_type, delta_minutes, balance_after_minutes, note)
  values (v_g.employee_id, v_g.leave_type_id, 'adjustment', -v_g.minutes, v_prev - v_g.minutes,
          case v_g.kind when 'marriage' then 'marriage leave revoked' else 'bereavement leave revoked' end);

  if v_g.kind = 'marriage' then
    update public.employee_personal_info set marital_status = v_g.prev_marital_status
     where employee_id = v_g.employee_id;
  end if;

  insert into public.audit_log (actor_id, action, entity, entity_id, after)
  values (v_uid, 'special_leave.revoke', 'special_leave_grants', p_grant_id,
          jsonb_build_object('employee_id', v_g.employee_id, 'kind', v_g.kind, 'minutes', v_g.minutes));
end; $$;


--
-- Name: app_role_holders(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_role_holders(p_role_id uuid) RETURNS TABLE(user_id uuid, full_name text, personnel_no text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not private.is_admin(auth.uid()) then
    raise exception 'only the admin can list role holders' using errcode = '42501';
  end if;
  return query
    select p.id, p.full_name, p.personnel_no
      from public.user_roles ur join public.profiles p on p.id = ur.user_id
      join public.roles r on r.id = ur.role_id
     where ur.role_id = p_role_id and r.company_id = private.caller_company()
     order by p.personnel_no;
end $$;


--
-- Name: app_save_role(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_save_role(p_id uuid, p_name text, p_permissions jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_uid     uuid := auth.uid();
  v_company uuid := private.caller_company();
  v_perms   jsonb := coalesce(p_permissions, '{}'::jsonb);
  v_kind    text;
  v_before  jsonb;
  v_id      uuid := p_id;
  v_name    text := btrim(coalesce(p_name, ''));
  kv        record;
  d         record;
begin
  if not private.is_admin(v_uid) then
    raise exception 'only the admin can edit roles' using errcode = '42501';
  end if;
  if jsonb_typeof(v_perms) <> 'object' then
    raise exception 'permissions must be an object' using errcode = '22023';
  end if;
  for kv in select key, value from jsonb_each(v_perms) loop
    if jsonb_typeof(kv.value) <> 'string'
       or not coalesce(private.permission_allows(kv.key, kv.value #>> '{}'), false) then
      raise exception 'invalid permission % = %', kv.key, kv.value using errcode = '22023';
    end if;
  end loop;
  for d in select * from private.permission_deps() loop
    if v_perms ? d.key
       and (d.key_level = 'read' or v_perms->>d.key = 'edit')
       and not v_perms ? d.needs then
      raise exception '% needs %', d.key, d.needs using errcode = '22023';
    end if;
  end loop;

  if v_id is null then
    if v_name !~ '^[A-Za-z0-9][A-Za-z0-9 &/-]{0,39}$' then
      raise exception 'invalid role name' using errcode = '22023';
    end if;
    if exists (select 1 from public.roles where company_id = v_company and lower(name) = lower(v_name)) then
      raise exception 'role name already used' using errcode = '22023';
    end if;
    insert into public.roles (company_id, kind, name) values (v_company, 'custom', v_name)
      returning id into v_id;
    v_before := null;
  else
    select kind into v_kind from public.roles where id = v_id and company_id = v_company for update;
    if v_kind is null then raise exception 'role not found' using errcode = '22023'; end if;
    if v_kind = 'system' then raise exception 'built-in role cannot be edited' using errcode = '22023'; end if;
    if v_kind = 'custom' then
      if v_name !~ '^[A-Za-z0-9][A-Za-z0-9 &/-]{0,39}$' then
        raise exception 'invalid role name' using errcode = '22023';
      end if;
      if exists (select 1 from public.roles where company_id = v_company and lower(name) = lower(v_name) and id <> v_id) then
        raise exception 'role name already used' using errcode = '22023';
      end if;
      update public.roles set name = v_name, updated_at = now() where id = v_id;
    else
      -- Presets keep their name (D9); the argument is ignored.
      update public.roles set updated_at = now() where id = v_id;
    end if;
    select coalesce(jsonb_object_agg(permission, level), '{}'::jsonb) into v_before
      from public.role_permissions where role_id = v_id;
    delete from public.role_permissions where role_id = v_id;
  end if;

  insert into public.role_permissions (role_id, permission, level)
    select v_id, key, value #>> '{}' from jsonb_each(v_perms);

  insert into public.audit_log (actor_id, action, entity, entity_id, before, after)
  values (v_uid, case when v_before is null then 'role.create' else 'role.update' end, 'roles', v_id,
          v_before, jsonb_build_object('name', (select name from public.roles where id = v_id),
                                       'permissions', v_perms));
  return v_id;
end $_$;


--
-- Name: app_save_separation_units(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_save_separation_units(p_units jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid     uuid := auth.uid();
  v_company uuid := private.separation_caller_company(v_uid);
  v_unit    jsonb;
  v_id      uuid;
  v_kind    text;
  v_dept    uuid;
  v_signer  uuid;
  v_keep    uuid[] := '{}';
  v_i       integer := 0;
begin
  if not private.has_perm(v_uid, 'clearance', 'edit') then
    raise exception 'not allowed to manage clearance forms' using errcode = '42501';
  end if;
  if p_units is null or jsonb_typeof(p_units) <> 'array' then
    raise exception 'invalid rows' using errcode = '22023';
  end if;
  insert into public.separation_units (company_id, kind, name_fa, name_en, sort_order)
  values (v_company, 'hr', 'مدیر اداری و منابع انسانی', 'HR & administration', 0)
  on conflict (company_id) where kind = 'hr' do nothing;

  for v_unit in select value from jsonb_array_elements(p_units) loop
    v_kind := v_unit->>'kind';
    if jsonb_typeof(v_unit) <> 'object'
       or coalesce(char_length(btrim(v_unit->>'name_fa')), 0) not between 1 and 100
       or coalesce(char_length(btrim(v_unit->>'name_en')), 0) not between 1 and 100 then
      raise exception 'invalid rows' using errcode = '22023';
    end if;
    if v_kind = 'hr' then
      update public.separation_units
         set name_fa = btrim(v_unit->>'name_fa'), name_en = btrim(v_unit->>'name_en')
       where company_id = v_company and kind = 'hr';
      continue;
    end if;
    if v_kind is null or v_kind not in ('department', 'own_department', 'person') then
      raise exception 'invalid rows' using errcode = '22023';
    end if;
    v_i := v_i + 1;
    v_dept   := case when v_kind = 'department' then nullif(v_unit->>'department_id', '')::uuid end;
    v_signer := case when v_kind = 'person' then nullif(v_unit->>'signer_id', '')::uuid end;
    if v_kind = 'department' and (v_dept is null or not exists (
         select 1 from public.departments where id = v_dept and company_id = v_company)) then
      raise exception 'invalid rows' using errcode = '22023';
    end if;
    if v_signer is not null and not exists (
         select 1 from public.profiles where id = v_signer and company_id = v_company and active) then
      raise exception 'invalid rows' using errcode = '22023';
    end if;
    v_id := nullif(v_unit->>'id', '')::uuid;
    if v_id is not null and exists (select 1 from public.separation_units
                                     where id = v_id and company_id = v_company and kind <> 'hr') then
      update public.separation_units
         set kind = v_kind, name_fa = btrim(v_unit->>'name_fa'), name_en = btrim(v_unit->>'name_en'),
             department_id = v_dept, signer_id = v_signer, sort_order = v_i,
             active = coalesce((v_unit->>'active')::boolean, true)
       where id = v_id;
    else
      insert into public.separation_units (company_id, kind, name_fa, name_en, department_id, signer_id, sort_order, active)
      values (v_company, v_kind, btrim(v_unit->>'name_fa'), btrim(v_unit->>'name_en'), v_dept, v_signer, v_i,
              coalesce((v_unit->>'active')::boolean, true))
      returning id into v_id;
    end if;
    v_keep := v_keep || v_id;
  end loop;

  delete from public.separation_units
   where company_id = v_company and kind <> 'hr' and not (id = any (v_keep));
  insert into public.audit_log (actor_id, action, entity, entity_id, after)
  values (v_uid, 'separation.units', 'separation_units', null, jsonb_build_object('units', v_i + 1));
end; $$;


--
-- Name: app_search_delegates(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_search_delegates(p_principal_id uuid, p_search text DEFAULT ''::text) RETURNS TABLE(profile_id uuid, full_name text, employee_code text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not private.is_active(auth.uid()) or not (auth.uid()=p_principal_id or private.is_admin(auth.uid()))
     or not exists (select 1 from public.profiles p join public.profiles c on c.company_id=p.company_id
        where p.id=p_principal_id and c.id=auth.uid())
     or not private.has_perm(p_principal_id,'approval_delegate','edit') then
    raise exception 'not permitted to select a delegate' using errcode='42501'; end if;
  return query select p.id,p.full_name,p.employee_code from public.profiles p
    where private.delegate_eligible(p_principal_id,p.id)
      and (coalesce(btrim(p_search),'')='' or p.full_name ilike '%'||btrim(p_search)||'%'
        or p.employee_code ilike '%'||btrim(p_search)||'%')
    order by p.full_name,p.id limit 50;
end; $$;


--
-- Name: app_separation_balances(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_separation_balances(p_id uuid) RETURNS TABLE(leave_type_id uuid, name_fa text, name_en text, balance_minutes integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  v_emp uuid;
begin
  if not private.can_read_separation(v_uid, p_id) then
    raise exception 'clearance form not found' using errcode = 'P0002';
  end if;
  select employee_id into v_emp from public.separations where id = p_id;
  return query
    select t.id, t.name_fa, t.name_en,
           coalesce((select l.balance_after_minutes from public.leave_ledger l
                      where l.employee_id = v_emp and l.leave_type_id = t.id
                      order by l.seq desc limit 1), 0)
      from public.leave_types t
      join public.profiles p on p.id = v_emp and p.company_id = t.company_id
     where t.active and t.affects_balance
     order by t.name_fa;
end; $$;


--
-- Name: app_separation_warnings(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_separation_warnings(p_employee_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid     uuid := auth.uid();
  v_company uuid := private.separation_caller_company(v_uid);
begin
  if not private.has_perm(v_uid, 'clearance', 'edit') then
    raise exception 'not allowed to manage clearance forms' using errcode = '42501';
  end if;
  if not exists (select 1 from public.profiles where id = p_employee_id and company_id = v_company) then
    raise exception 'employee not found' using errcode = '42501';
  end if;
  return jsonb_build_object(
    'pending_requests', (select count(*) from public.leave_requests
                          where employee_id = p_employee_id and status = 'pending'),
    'direct_reports', (select count(*) from public.profiles
                        where manager_id = p_employee_id and active),
    'departments_managed', (select count(*) from public.departments
                             where manager_id = p_employee_id),
    'approval_steps', (select count(*) from public.approval_steps
                        where approver_id = p_employee_id and active));
end; $$;


--
-- Name: app_set_approval_delegate(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_set_approval_delegate(p_principal_id uuid, p_delegate_id uuid DEFAULT NULL::uuid, p_ceo_authorized boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_company uuid; v_ceo uuid; v_id uuid; v_old uuid;
begin
  select p.company_id into v_company from public.profiles p join public.profiles c
    on c.company_id=p.company_id and c.id=auth.uid() where p.id=p_principal_id;
  if v_company is null or not private.is_active(auth.uid()) or
      not (auth.uid()=p_principal_id or private.is_admin(auth.uid())) then
    raise exception 'not permitted to select a delegate' using errcode='42501'; end if;
  perform private.approval_lock(v_company);
  -- A waiting former admin or deactivated caller cannot keep pre-lock authority.
  if not private.is_active(auth.uid()) or not exists (
      select 1 from public.profiles p join public.profiles c
        on c.id=auth.uid() and c.company_id=p.company_id
      where p.id=p_principal_id and p.company_id=v_company)
      or not (auth.uid()=p_principal_id or private.is_admin(auth.uid())) then
    raise exception 'not permitted to select a delegate' using errcode='42501'; end if;
  if not private.has_perm(p_principal_id,'approval_delegate','edit')
    or not private.natural_approver(p_principal_id) then
    raise exception 'principal needs approval delegation permission and natural approval duties' using errcode='42501'; end if;
  select ceo_id into v_ceo from public.approval_executive_settings where company_id=v_company;
  if p_delegate_id is not null and not private.delegate_eligible(p_principal_id,p_delegate_id) then
    raise exception 'delegate must be an active eligible approver; CEO delegates must be direct reports' using errcode='22023'; end if;
  if coalesce(p_ceo_authorized,false) and (v_ceo is distinct from p_principal_id or p_delegate_id is null) then
    raise exception 'automatic approval authorization requires the designated CEO appointment' using errcode='22023'; end if;
  if coalesce(p_ceo_authorized,false) and not private.ceo_delegate_configuration_ready(p_principal_id,p_delegate_id) then
    raise exception 'CEO must naturally own applicable approval steps for leave and errand before automatic authority is authorized' using errcode='22023'; end if;
  select id into v_old from public.approval_delegations where principal_id=p_principal_id
    and source_request_id is null and revoked_at is null;
  update public.approval_delegations set revoked_at=clock_timestamp() where id=v_old;
  if p_delegate_id is not null then
    insert into public.approval_delegations(company_id,principal_id,delegate_id,principal_name,delegate_name,
      configured_by,ceo_authorized)
    select v_company,p_principal_id,p_delegate_id,p.full_name,d.full_name,auth.uid(),coalesce(p_ceo_authorized,false)
      from public.profiles p,public.profiles d where p.id=p_principal_id and d.id=p_delegate_id returning id into v_id;
  end if;
  insert into public.audit_log(actor_id,action,entity,entity_id,after) values
    (auth.uid(),'set_approval_delegate','approval_delegations',v_id,
      jsonb_build_object('principal_id',p_principal_id,'delegate_id',p_delegate_id,
        'previous_grant_id',v_old,'ceo_authorized',coalesce(p_ceo_authorized,false)));
end; $$;


--
-- Name: app_set_approval_order_enforced(boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_set_approval_order_enforced(p_enforced boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid     uuid := auth.uid();
  v_company uuid;
begin
  if v_uid is null or not private.is_active(v_uid)
     or not (private.is_admin(v_uid) or private.has_perm(v_uid, 'approval_steps', 'edit')) then
    raise exception 'not allowed to change the approval order setting' using errcode = '42501';
  end if;
  if p_enforced is null then
    raise exception 'approval order setting must be true or false' using errcode = '22023';
  end if;
  v_company := private.caller_company();

  insert into public.work_settings (company_id, approval_order_enforced, updated_by, updated_at)
  values (v_company, p_enforced, v_uid, now())
  on conflict (company_id) do update
    set approval_order_enforced = excluded.approval_order_enforced,
        updated_by = excluded.updated_by,
        updated_at = excluded.updated_at;
end $$;


--
-- Name: app_set_employee_password(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_set_employee_password(p_user_id uuid, p_password text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_rows int;
begin
  if not private.can_reset_password(auth.uid(), p_user_id) then
    raise exception 'not allowed to reset this password' using errcode = '42501';
  end if;
  if length(coalesce(p_password, '')) < 8 then
    raise exception 'new password must be at least 8 characters' using errcode = '22023';
  end if;
  if octet_length(coalesce(p_password, '')) > 72 then
    raise exception 'new password must be at most 72 ASCII characters' using errcode = '22023';
  end if;

  update auth.users
     set encrypted_password = extensions.crypt(p_password, extensions.gen_salt('bf')),
         updated_at = now()
   where id = p_user_id;
  get diagnostics v_rows = row_count;
  if v_rows <> 1 then
    raise exception 'employee not found' using errcode = 'P0002';
  end if;

  -- An admin resetting their own password chose it themselves.
  -- A non-admin caller passes the profile guard only with this flag (FR-55).
  perform set_config('bj.password_flag_write', 'on', true);
  update public.profiles
     set must_change_password = (p_user_id <> auth.uid())
   where id = p_user_id;
  perform set_config('bj.password_flag_write', '', true);

  insert into public.audit_log (actor_id, action, entity, entity_id)
  values (auth.uid(), 'reset_password', 'auth.users', p_user_id);
end;
$$;


--
-- Name: app_set_executive_settings(uuid, uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_set_executive_settings(p_ceo_id uuid, p_hr_head_id uuid, p_hr_step_ids uuid[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_company uuid; v_old_ceo uuid;
begin
  if not private.is_admin(auth.uid()) then raise exception 'admin required' using errcode='42501'; end if;
  select company_id into v_company from public.profiles where id=auth.uid();
  perform private.approval_lock(v_company);
  if not private.is_admin(auth.uid()) or not exists (
      select 1 from public.profiles where id=auth.uid() and company_id=v_company) then
    raise exception 'admin required' using errcode='42501'; end if;
  if exists (select 1 from unnest(array[p_ceo_id,p_hr_head_id]) id where id is not null
      and not exists (select 1 from public.profiles p where p.id=id and p.company_id=v_company and p.active)) then
    raise exception 'executive must be active in your company' using errcode='22023'; end if;
  if exists (select 1 from unnest(coalesce(p_hr_step_ids,'{}')) id where not exists
      (select 1 from public.approval_steps s where s.id=id and s.company_id=v_company and s.active)) then
    raise exception 'HR review step must be an active company approval step' using errcode='22023'; end if;
  select ceo_id into v_old_ceo from public.approval_executive_settings where company_id=v_company;
  -- Review fix: re-designating a former CEO must not silently revive their earlier attestation.
  if v_old_ceo is not null and v_old_ceo is distinct from p_ceo_id then
    update public.approval_delegations set ceo_authorized=false
      where company_id=v_company and principal_id=v_old_ceo and revoked_at is null and ceo_authorized;
  end if;
  insert into public.approval_executive_settings(company_id,ceo_id,hr_head_id,hr_step_ids,configured_by)
    values(v_company,p_ceo_id,p_hr_head_id,coalesce(p_hr_step_ids,'{}'),auth.uid())
    on conflict(company_id) do update set ceo_id=excluded.ceo_id,hr_head_id=excluded.hr_head_id,
      hr_step_ids=excluded.hr_step_ids,configured_by=excluded.configured_by,
      configured_at=clock_timestamp(),version=public.approval_executive_settings.version+1;
  insert into public.audit_log(actor_id,action,entity,entity_id,after) values
    (auth.uid(),'set_approval_executives','approval_executive_settings',v_company,
      jsonb_build_object('ceo_id',p_ceo_id,'hr_head_id',p_hr_head_id,'hr_step_ids',p_hr_step_ids));
end; $$;


--
-- Name: app_set_initial_password(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_set_initial_password(p_new text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid  uuid := auth.uid();
  v_same boolean;
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not private.is_active(v_uid) then
    raise exception 'account is inactive' using errcode = '42501';
  end if;
  if not exists (
    select 1 from public.profiles where id = v_uid and must_change_password
  ) then
    raise exception 'password change is not required' using errcode = '22023';
  end if;
  if length(coalesce(p_new, '')) < 8 then
    raise exception 'new password must be at least 8 characters' using errcode = '22023';
  end if;
  if octet_length(coalesce(p_new, '')) > 72 then
    raise exception 'new password must be at most 72 ASCII characters' using errcode = '22023';
  end if;

  select encrypted_password = extensions.crypt(p_new, encrypted_password)
    into v_same
    from auth.users
   where id = v_uid;
  if coalesce(v_same, false) then
    raise exception 'new password must differ from the issued password' using errcode = '22023';
  end if;

  update auth.users
     set encrypted_password = extensions.crypt(p_new, extensions.gen_salt('bf')),
         updated_at = now()
   where id = v_uid;

  perform set_config('bj.password_flag_write', 'on', true);
  update public.profiles
     set must_change_password = false
   where id = v_uid;
  perform set_config('bj.password_flag_write', '', true);

  insert into public.audit_log(actor_id, action, entity, entity_id)
  values (v_uid, 'set_initial_password', 'auth.users', v_uid);
end;
$$;


--
-- Name: app_set_separation_signoffs(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_set_separation_signoffs(p_id uuid, p_rows jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid     uuid := auth.uid();
  v_company uuid := private.separation_caller_company(v_uid);
  s         record;
  v_row     jsonb;
  v_row_id  uuid;
  v_keep    uuid[] := '{}';
  v_i       integer := 0;
  o         record;
begin
  select * into s from public.separations where id = p_id and company_id = v_company for update;
  if not found then
    raise exception 'clearance form not found' using errcode = 'P0002';
  end if;
  perform private.separation_manageable(v_uid, v_company, s.employee_id);
  if s.status <> 'in_progress' then
    raise exception 'form is not open for changes' using errcode = '22023';
  end if;
  if p_rows is null or jsonb_typeof(p_rows) <> 'array' then
    raise exception 'invalid rows' using errcode = '22023';
  end if;

  for v_row in select value from jsonb_array_elements(p_rows) loop
    v_i := v_i + 1;
    v_row_id := nullif(v_row->>'id', '')::uuid;
    if v_row_id is null then
      insert into public.separation_signoffs (separation_id, name_fa, name_en, department_id, signer_id, sort_order)
      values (p_id, btrim(v_row->>'name_fa'), btrim(v_row->>'name_en'),
              nullif(v_row->>'department_id', '')::uuid,
              private.separation_row_signer(v_company, s.employee_id, v_row), v_i)
      returning id into v_row_id;
    else
      select * into o from public.separation_signoffs where id = v_row_id and separation_id = p_id;
      if not found or o.is_hr then
        raise exception 'invalid rows' using errcode = '22023';
      end if;
      if o.signed_at is not null then
        update public.separation_signoffs set sort_order = v_i where id = v_row_id;
      else
        update public.separation_signoffs
           set name_fa = btrim(v_row->>'name_fa'), name_en = btrim(v_row->>'name_en'),
               department_id = nullif(v_row->>'department_id', '')::uuid,
               signer_id = private.separation_row_signer(v_company, s.employee_id, v_row),
               sort_order = v_i
         where id = v_row_id;
      end if;
    end if;
    v_keep := v_keep || v_row_id;
  end loop;

  if exists (select 1 from public.separation_signoffs
              where separation_id = p_id and not is_hr and signed_at is not null
                and not (id = any (v_keep))) then
    raise exception 'signed rows cannot be changed' using errcode = '22023';
  end if;
  delete from public.separation_signoffs
   where separation_id = p_id and not is_hr and signed_at is null and not (id = any (v_keep));

  insert into public.audit_log (actor_id, action, entity, entity_id, after)
  values (v_uid, 'separation.rows', 'separations', p_id, jsonb_build_object('rows', v_i + 1));
  perform private.refresh_separation_status(p_id);
end; $$;


--
-- Name: app_set_user_role_ids(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_set_user_role_ids(p_user_id uuid, p_role_ids uuid[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid      uuid := auth.uid();
  v_company  uuid;
  v_is_admin boolean;
  v_admin_id uuid;
  v_before   uuid[];
  v_after    uuid[] := coalesce(p_role_ids, '{}');
  v_changed  uuid;
  v_key      public.app_role;
begin
  -- Serialise with app_transfer_admin, which locks the same profile rows in the
  -- same (id) order: the admin check and v_before below then see a committed
  -- transfer instead of racing it.
  perform 1 from public.profiles where id in (v_uid, p_user_id) order by id for no key update;
  v_company := private.caller_company();
  v_is_admin := private.is_admin(v_uid);

  -- Only role holders reach the per-role checks below; anyone else is refused even
  -- for a call that changes nothing.
  if not v_is_admin
     and not private.has_perm(v_uid, 'role_assign', 'edit')
     and not private.has_perm(v_uid, 'role_manager', 'edit') then
    raise exception 'not allowed to set roles' using errcode = '42501';
  end if;
  if not exists (select 1 from public.profiles where id = p_user_id and company_id = v_company) then
    raise exception 'employee not found' using errcode = '42501';
  end if;
  -- Validated here, not left to role_within: the admin skips role_within.
  if exists (select 1 from unnest(v_after) x left join public.roles r on r.id = x
              where r.id is null or r.company_id <> v_company) then
    raise exception 'unknown role' using errcode = '22023';
  end if;
  select id into v_admin_id from public.roles where company_id = v_company and system_key = 'admin';
  select coalesce(array_agg(role_id order by role_id), '{}') into v_before
    from public.user_roles where user_id = p_user_id;

  -- D1: admin moves only by transfer, for everyone, the admin included.
  if (v_admin_id = any (v_before)) <> (v_admin_id = any (v_after)) then
    raise exception 'admin is moved only by Transfer admin' using errcode = '42501';
  end if;

  if not v_is_admin then
    -- D3 + D4 (can_act_on is false on yourself), then D5 per added or removed role.
    if not private.can_act_on(v_uid, p_user_id) then
      raise exception 'not allowed on this employee' using errcode = '42501';
    end if;
    for v_changed in
      (select x from unnest(v_before) x except select x from unnest(v_after) x)
      union
      (select x from unnest(v_after) x except select x from unnest(v_before) x)
    loop
      -- Identity presets: their holders sign approval steps and the clearance HR
      -- rows (hr) or the clearance finance box, so giving one to someone whose
      -- password you can reset is signing as them. It takes the powers that edit
      -- those signers (mirrors can_act_on). Security signs no step since
      -- 20261012120003 (main's approval_steps_role_allowed).
      v_key := (select system_key from public.roles where id = v_changed);
      if not private.role_within(v_changed, v_uid)
         or (v_key = 'hr' and not (private.has_perm(v_uid, 'approval_steps', 'edit')
                                   and private.has_perm(v_uid, 'clearance', 'edit')))
         or (v_key = 'finance' and not private.has_perm(v_uid, 'clearance', 'edit')) then
        raise exception 'not allowed to give or remove role %', (select name from public.roles where id = v_changed)
          using errcode = '42501';
      end if;
    end loop;
  end if;

  -- Never the admin row, whatever v_before said (D1; belt and braces to the lock).
  delete from public.user_roles where user_id = p_user_id and role_id <> all (v_after)
     and role is distinct from 'admin';
  insert into public.user_roles (user_id, role_id)
    select distinct p_user_id, x from unnest(v_after) x on conflict (user_id, role_id) do nothing;

  insert into public.audit_log (actor_id, action, entity, entity_id, before, after)
  values (v_uid, 'set_roles', 'user_roles', p_user_id,
    jsonb_build_object('roles', (select coalesce(jsonb_agg(name order by name), '[]') from public.roles where id = any (v_before))),
    jsonb_build_object('roles', (select coalesce(jsonb_agg(name order by name), '[]') from public.roles where id = any (v_after))));
end $$;


--
-- Name: app_set_user_roles(uuid, public.app_role[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_set_user_roles(p_user_id uuid, p_roles public.app_role[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_ids uuid[];
begin
  select coalesce(array_agg(r.id), '{}') into v_ids
    from public.roles r join public.profiles p on p.company_id = r.company_id and p.id = p_user_id
   where r.system_key = any (coalesce(p_roles, '{}'));
  select v_ids || coalesce(array_agg(ur.role_id), '{}') into v_ids
    from public.user_roles ur where ur.user_id = p_user_id and ur.role is null;
  perform public.app_set_user_role_ids(p_user_id, v_ids);
end $$;


--
-- Name: app_sign_separation_finance(uuid, text, boolean, text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_sign_separation_finance(p_id uuid, p_signature_data text, p_signature_authorized boolean, p_note text, p_settlement_date date) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid     uuid := auth.uid();
  v_company uuid := private.separation_caller_company(v_uid);
  v_note    text := nullif(btrim(p_note), '');
  s         record;
begin
  if not private.has_role(v_uid, 'finance') then
    raise exception 'not allowed to sign as finance' using errcode = '42501';
  end if;
  perform private.separation_check_signature(p_signature_data, p_signature_authorized);
  if v_note is not null and length(v_note) > 500 then
    raise exception 'note is too long' using errcode = '22023';
  end if;
  select * into s from public.separations where id = p_id and company_id = v_company for update;
  if not found then
    raise exception 'clearance form not found' using errcode = 'P0002';
  end if;
  if s.employee_id = v_uid then
    raise exception 'you cannot sign your own clearance form' using errcode = '42501';
  end if;
  if s.status <> 'awaiting_finance' then
    raise exception 'form is not awaiting finance' using errcode = '22023';
  end if;

  update public.separations
     set status = 'completed', finance_signed_by = v_uid, finance_signed_at = now(),
         finance_signature_data = p_signature_data, finance_signature_consent_at = now(),
         finance_note = v_note,
         settlement_date = coalesce(p_settlement_date, (now() at time zone 'Asia/Tehran')::date)
   where id = p_id;
  insert into public.audit_log (actor_id, action, entity, entity_id, after)
  values (v_uid, 'separation.finance', 'separations', p_id, null);
end; $$;


--
-- Name: app_sign_separation_row(uuid, text, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_sign_separation_row(p_row_id uuid, p_signature_data text, p_signature_authorized boolean, p_note text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid     uuid := auth.uid();
  v_company uuid := private.separation_caller_company(v_uid);
  v_note    text := nullif(btrim(p_note), '');
  o         record;
  s         record;
begin
  perform private.separation_check_signature(p_signature_data, p_signature_authorized);
  if v_note is not null and length(v_note) > 500 then
    raise exception 'note is too long' using errcode = '22023';
  end if;

  select * into s from public.separations
   where id = (select separation_id from public.separation_signoffs where id = p_row_id)
     and company_id = v_company
     for update;
  if not found then
    raise exception 'clearance form not found' using errcode = 'P0002';
  end if;
  if s.employee_id = v_uid then
    raise exception 'you cannot sign your own clearance form' using errcode = '42501';
  end if;
  if s.status <> 'in_progress' then
    raise exception 'form is not open for signing' using errcode = '22023';
  end if;
  -- Re-read under the form lock: a concurrent signer may have just signed it.
  select * into o from public.separation_signoffs where id = p_row_id;
  if o.signed_at is not null then
    raise exception 'row already signed' using errcode = '22023';
  end if;
  if o.is_hr then
    -- A5: any hr holder or an admin signs the HR row.
    if not (private.has_role(v_uid, 'hr') or private.is_admin(v_uid)) then
      raise exception 'row is not yours to sign' using errcode = '42501';
    end if;
  elsif o.signer_id is null then
    raise exception 'row has no signer yet' using errcode = '22023';
  elsif o.signer_id <> v_uid then
    raise exception 'row is not yours to sign' using errcode = '42501';
  end if;

  update public.separation_signoffs
     set signed_by = v_uid, signed_at = now(), signature_data = p_signature_data,
         signature_consent_at = now(), note = v_note
   where id = p_row_id;
  insert into public.audit_log (actor_id, action, entity, entity_id, after)
  values (v_uid, 'separation.sign', 'separation_signoffs', p_row_id,
          jsonb_build_object('separation_id', s.id));
  perform private.refresh_separation_status(s.id);
end; $$;


--
-- Name: app_transfer_admin(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_transfer_admin(p_target uuid, p_personnel_no text, p_password text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
begin
  -- Same lock order as app_set_user_role_ids (profile rows, by id).
  perform 1 from public.profiles where id in (v_uid, p_target) order by id for no key update;
  if not private.is_admin(v_uid) then
    raise exception 'only the admin can transfer admin' using errcode = '42501';
  end if;
  if not exists (select 1 from auth.users
                  where id = v_uid
                    and encrypted_password = extensions.crypt(coalesce(p_password, ''), encrypted_password)) then
    raise exception 'wrong password' using errcode = '42501';
  end if;
  if p_target = v_uid then
    raise exception 'you already hold admin' using errcode = '22023';
  end if;
  -- The typed personnel number guards against picking the wrong person. An account
  -- with none (the bootstrap admin, deploy/sql/bootstrap_admin.sql) is confirmed by
  -- its employee code instead, so admin can be handed back to it.
  if not exists (select 1 from public.profiles t join public.profiles c on c.id = v_uid and c.company_id = t.company_id
                  where t.id = p_target and t.active
                    and coalesce(t.personnel_no, t.employee_code) = btrim(coalesce(p_personnel_no, ''))) then
    raise exception 'personnel number does not match an active employee' using errcode = '22023';
  end if;

  delete from public.user_roles where user_id = v_uid and role = 'admin';
  -- The bootstrap admin holds no other row: leave it the company's Employee role
  -- rather than no role at all.
  if not exists (select 1 from public.user_roles where user_id = v_uid) then
    insert into public.user_roles (user_id, role) values (v_uid, 'employee');
  end if;
  insert into public.user_roles (user_id, role) values (p_target, 'admin');
  insert into public.audit_log (actor_id, action, entity, entity_id, before, after)
  values (v_uid, 'admin.transfer', 'user_roles', p_target,
          jsonb_build_object('admin', v_uid), jsonb_build_object('admin', p_target));
end $$;


--
-- Name: app_update_separation(uuid, text, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_update_separation(p_id uuid, p_reason text, p_last_working_day date, p_note text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid     uuid := auth.uid();
  v_company uuid := private.separation_caller_company(v_uid);
  v_note    text := nullif(btrim(p_note), '');
  s         record;
begin
  select * into s from public.separations where id = p_id and company_id = v_company for update;
  if not found then
    raise exception 'clearance form not found' using errcode = 'P0002';
  end if;
  perform private.separation_manageable(v_uid, v_company, s.employee_id);
  if s.status = 'cancelled' then
    raise exception 'form is not open for changes' using errcode = '22023';
  end if;
  if s.deactivated_at is not null then
    raise exception 'form already applied' using errcode = '22023';
  end if;
  perform private.separation_check_fields(p_reason, p_last_working_day, v_note);

  update public.separations
     set reason = p_reason, last_working_day = p_last_working_day, note = v_note
   where id = p_id;
  insert into public.audit_log (actor_id, action, entity, entity_id, before, after)
  values (v_uid, 'separation.update', 'separations', p_id,
          jsonb_build_object('reason', s.reason, 'last_working_day', s.last_working_day),
          jsonb_build_object('reason', p_reason, 'last_working_day', p_last_working_day));
  perform private.apply_due_separations(p_id);
end; $$;


--
-- Name: approve_leave_request(uuid, text, boolean, boolean, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_leave_request(p_id uuid, p_signature_data text, p_signature_authorized boolean, p_override boolean DEFAULT false, p_per_diem_rials bigint DEFAULT NULL::bigint) RETURNS void
