--
-- Name: cancel_leave_request(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_leave_request(p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  v_owner uuid;
  v_company uuid;
  v_now timestamptz;
  v_status public.leave_status;
  v_start date;
  v_type uuid;
  v_kind public.request_kind;
  v_minutes int;
  v_unpaid int;
  v_paid int;
  v_affects boolean;
  v_prev int;
  v_rows int;
  v_today date;
begin
  if v_uid is null then raise exception 'not authenticated' using errcode = '42501'; end if;
  if not private.is_active(v_uid) then
    raise exception 'account is inactive' using errcode = '42501';
  end if;

  select employee_id, company_id into v_owner, v_company from public.leave_requests where id = p_id;
  if v_owner is null then raise exception 'request not found' using errcode = 'P0002'; end if;
  if not (v_owner = v_uid
          or private.is_admin(v_uid)
          -- FR-55 D8: leave_requests at Allowed covers the company, apart from the admin.
          or (private.has_perm(v_uid, 'leave_requests', 'edit')
              and exists (select 1 from public.profiles o
                            join public.profiles c on c.company_id = o.company_id and c.id = v_uid
                           where o.id = v_owner)
              and not exists (select 1 from public.user_roles where user_id = v_owner and role = 'admin'))) then
    raise exception 'not allowed to cancel this request' using errcode = '42501';
  end if;

  perform private.approval_lock(v_company);
  perform pg_advisory_xact_lock(hashtextextended('leave:' || v_owner::text, 0));

  select status, start_date, leave_type_id, requested_minutes, unpaid_minutes, kind
    into v_status, v_start, v_type, v_minutes, v_unpaid, v_kind
    from public.leave_requests where id = p_id for update;
  v_now := clock_timestamp();
  v_today := (v_now at time zone 'Asia/Tehran')::date;
  if not private.is_active(v_uid) or not exists (
      select 1 from public.profiles where id=v_uid and company_id=v_company) then
    raise exception 'not allowed to cancel this request' using errcode='42501';
  end if;
  if not (v_owner = v_uid
          or private.is_admin(v_uid)
          or (private.has_perm(v_uid, 'leave_requests', 'edit')
              and exists (select 1 from public.profiles o
                            join public.profiles c on c.company_id=o.company_id and c.id=v_uid
                           where o.id=v_owner)
              and not exists (select 1 from public.user_roles where user_id=v_owner and role='admin'))) then
    raise exception 'not allowed to cancel this request' using errcode='42501';
  end if;
  v_paid := greatest(v_minutes - coalesce(v_unpaid, 0), 0);

  if v_status = 'pending' then
    update public.leave_requests
       set status = 'cancelled', decided_by = v_uid, decided_at = v_now
     where id = p_id and status = 'pending';
    get diagnostics v_rows = row_count;
    if v_rows <> 1 then
      raise exception 'request was already decided' using errcode = '22023';
    end if;
  elsif v_status = 'approved'
        and (v_start > v_today or (v_kind = 'errand' and v_start >= v_today))
  then
    update public.leave_requests
       set status = 'cancelled', decided_by = v_uid, decided_at = v_now
     where id = p_id and status = 'approved';
    get diagnostics v_rows = row_count;
    if v_rows <> 1 then
      raise exception 'request was already decided' using errcode = '22023';
    end if;

    select affects_balance into v_affects from public.leave_types where id = v_type;
    if v_affects and v_paid > 0 then
      v_prev := public.current_leave_balance(v_owner, v_type);
      insert into public.leave_ledger(
        employee_id, leave_type_id, request_id, entry_type,
        delta_minutes, balance_after_minutes, note
      ) values (
        v_owner, v_type, p_id, 'reversal',
        v_paid, v_prev + v_paid, 'paid portion reversed on cancel'
      );
    end if;
  else
    raise exception 'only pending or not-yet-started approved requests can be cancelled'
      using errcode = '22023';
  end if;

  insert into public.audit_log(actor_id, action, entity, entity_id, after)
  values (
    v_uid, 'cancel_leave_request', 'leave_requests', p_id,
    jsonb_build_object(
      'status_before', v_status,
      'requested_minutes', v_minutes,
      'paid_minutes_reversed', case when v_status = 'approved' then v_paid else 0 end,
      'unpaid_minutes', v_unpaid,
      'kind', v_kind,
      'reversed', (
        v_status = 'approved' and coalesce(v_affects, false) and v_paid > 0
      )
    )
  );
end;
$$;


--
-- Name: compute_requested_minutes(uuid, date, date, public.day_part, public.leave_unit, time without time zone, time without time zone, public.request_kind); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compute_requested_minutes(p_company_id uuid, p_start date, p_end date, p_day_part public.day_part, p_unit public.leave_unit DEFAULT 'day'::public.leave_unit, p_start_time time without time zone DEFAULT NULL::time without time zone, p_end_time time without time zone DEFAULT NULL::time without time zone, p_kind public.request_kind DEFAULT 'leave'::public.request_kind) RETURNS integer
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_per_day numeric;
  v_count numeric := 0;
  d date;
  v_working boolean;
begin
  if p_end < p_start then return 0; end if;

  select hours_per_day into v_per_day
    from public.work_settings where company_id = p_company_id limit 1;
  if v_per_day is null then v_per_day := 8; end if;

  if p_unit = 'hour' then
    if p_start_time is null or p_end_time is null or p_end_time <= p_start_time then
      return 0;
    end if;
    if p_kind = 'errand' then
      return (extract(epoch from (p_end_time - p_start_time)) / 60)::int;
    end if;

    v_working := (not private.is_company_weekend(p_company_id, p_start))
                 and not exists (
                   select 1 from public.holidays h
                    where h.company_id = p_company_id and h.holiday_date = p_start
                 );
    if not v_working then return 0; end if;
    return (extract(epoch from (p_end_time - p_start_time)) / 60)::int;
  end if;

  if p_kind = 'errand' then
    return round(((p_end - p_start) + 1) * v_per_day * 60);
  end if;

  if p_day_part in ('am', 'pm') then
    if p_start <> p_end then return 0; end if;
    v_working := (not private.is_company_weekend(p_company_id, p_start))
                 and not exists (
                   select 1 from public.holidays h
                    where h.company_id = p_company_id and h.holiday_date = p_start
                 );
    return case when v_working then round(v_per_day * 60 / 2) else 0 end;
  end if;

  d := p_start;
  while d <= p_end loop
    if (not private.is_company_weekend(p_company_id, d))
       and not exists (
         select 1 from public.holidays h
          where h.company_id = p_company_id and h.holiday_date = d
       )
    then
      v_count := v_count + 1;
    end if;
    d := d + 1;
  end loop;

  return round(v_count * v_per_day * 60);
end;
$$;


--
-- Name: current_leave_balance(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_leave_balance(p_employee_id uuid, p_leave_type_id uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce((
    select balance_after_minutes from public.leave_ledger
    where employee_id = p_employee_id and leave_type_id = p_leave_type_id
    order by seq desc limit 1
  ), 0);
$$;


--
-- Name: custom_access_token_hook(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.custom_access_token_hook(event jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare
  v_uid    uuid := (event->>'user_id')::uuid;
  v_active boolean;
  claims   jsonb;
  roles    jsonb;
  perms    jsonb;
  locale   text;
begin
  select p.active, p.language_pref into v_active, locale from public.profiles p where p.id = v_uid;
  v_active := coalesce(v_active, false);

  select coalesce(jsonb_agg(role order by role), '[]'::jsonb) into roles
    from public.user_roles where user_id = v_uid and role is not null and v_active;

  select coalesce(jsonb_object_agg(k, case l when 2 then 'edit' else 'read' end), '{}'::jsonb) into perms
    from (select k, private.perm_level(v_uid, k) l from private.permission_keys() k) s
   where l > 0 and v_active;

  claims := jsonb_set(coalesce(event->'claims', '{}'::jsonb), '{app_roles}', roles);
  claims := jsonb_set(claims, '{app_perms}', perms);
  -- Constrain to the locales the app routes (see the previous definition's note).
  claims := jsonb_set(claims, '{app_locale}',
    to_jsonb(case when locale in ('fa', 'en') then locale else 'fa' end));
  return jsonb_set(event, '{claims}', claims);
end;
$$;


--
-- Name: finance_approved_requests(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finance_approved_requests(p_from date, p_to date) RETURNS TABLE(id uuid, serial_year integer, serial_seq integer, kind public.request_kind, employee_name text, personnel_no text, department_name_fa text, department_name_en text, leave_type_name_fa text, leave_type_name_en text, is_paid boolean, start_date date, end_date date, unit public.leave_unit, start_time time without time zone, end_time time without time zone, requested_minutes integer, unpaid_minutes integer, errand_location text, per_diem_rials bigint, decided_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  v_company uuid;
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not private.is_active(v_uid) or not private.has_permission(v_uid, 'finance.view') then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if p_from is null or p_to is null or p_to < p_from then
    raise exception 'invalid date range' using errcode = '22023';
  end if;
  if p_to - p_from > 400 then
    raise exception 'date range too long' using errcode = '22023';
  end if;
  select company_id into v_company from public.profiles where profiles.id = v_uid;

  return query
    select r.id, r.serial_year, r.serial_seq, r.kind,
           p.full_name, p.personnel_no,
           d.name_fa, d.name_en,
           t.name_fa, t.name_en, t.is_paid,
           r.start_date, r.end_date, r.unit, r.start_time, r.end_time,
           r.requested_minutes, r.unpaid_minutes,
           r.errand_location, r.per_diem_rials, r.decided_at
      from public.leave_requests r
      join public.profiles p on p.id = r.employee_id
      left join public.departments d on d.id = p.department_id
      left join public.leave_types t on t.id = r.leave_type_id
     where r.company_id = v_company
       and r.status = 'approved'
       and r.start_date <= p_to
       and r.end_date >= p_from
     order by r.start_date, r.serial_year, r.serial_seq;
end; $$;


--
-- Name: get_leave_request_signatures(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_leave_request_signatures(p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_result jsonb; v_progress jsonb;
begin
  if not private.can_read_approval_request(auth.uid(),p_id) then
    raise exception 'request not found' using errcode='P0002'; end if;
  v_progress:=public.app_request_approval_progress(p_id);
  select jsonb_build_object('requester_signature_data',r.signature_data,
    'requester_consent_at',r.signature_consent_at,'approver_signature_data',r.approver_signature_data,
    'approver_signature_consent_at',r.approver_signature_consent_at,
    'approvals',coalesce((select jsonb_agg(item||jsonb_build_object('signature_data',a.signature_data,
      'signature_consent_at',a.signature_consent_at) order by (item->>'step_order')::integer)
      from jsonb_array_elements(v_progress) item left join public.leave_request_approvals a
        on a.request_id=r.id and (a.step_id=(item->>'step_id')::uuid
          or (a.step_id is null and item->>'step_id' is null and a.step_role::text=item->>'step_role'))),'[]'))
    into v_result from public.leave_requests r where r.id=p_id;
  return v_result;
end; $$;


--
-- Name: get_my_cover_conflicts(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_cover_conflicts(p_start date, p_end date) RETURNS TABLE(request_id uuid, employee_name text, start_date date, end_date date, unit public.leave_unit, start_time time without time zone, end_time time without time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select r.id, p.full_name, r.start_date, r.end_date, r.unit, r.start_time, r.end_time
    from public.leave_requests r
    join public.profiles p on p.id = r.employee_id
   where private.is_active(auth.uid())
     and r.replacement_id = auth.uid()
     and r.status in ('pending', 'approved')
     and r.start_date <= p_end
     and r.end_date >= p_start
   order by r.start_date;
$$;


--
-- Name: get_my_team_directory(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_team_directory() RETURNS TABLE(profile_id uuid, full_name text, employee_code text, relation text, roles public.app_role[], department_name_fa text, department_name_en text, manager_name text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with me as (
    select id, company_id, department_id, manager_id
      from public.profiles
     where id = auth.uid()
       and active
  )
  select
    p.id,
    p.full_name,
    p.employee_code,
    case when p.id = me.manager_id then 'manager' else 'teammate' end,
    coalesce(
      array_agg(ur.role order by ur.role) filter (where ur.role is not null),
      array[]::public.app_role[]
    ),
    d.name_fa,
    d.name_en,
    mgr.full_name
  from me
  join public.profiles p
    on p.company_id = me.company_id
   and p.active
   and p.id <> me.id
   and (
     p.id = me.manager_id
     or (me.department_id is not null and p.department_id = me.department_id)
   )
  left join public.user_roles ur on ur.user_id = p.id
  left join public.departments d on d.id = p.department_id
  left join public.profiles mgr on mgr.id = p.manager_id
  group by p.id, p.full_name, p.employee_code, me.manager_id,
           d.name_fa, d.name_en, mgr.full_name
  order by case when p.id = me.manager_id then 0 else 1 end, p.full_name;
$$;


--
-- Name: get_org_chart(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_org_chart() RETURNS TABLE(profile_id uuid, full_name text, job_title text, department_id uuid, department_name_fa text, department_name_en text, manager_id uuid, is_department_manager boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with me as (
    select company_id
      from public.profiles
     where id = auth.uid()
       and active
  )
  select
    p.id,
    p.full_name,
    p.job_title,
    p.department_id,
    d.name_fa,
    d.name_en,
    case when m.active then p.manager_id end,
    exists (
      select 1 from public.departments dm
       where dm.manager_id = p.id and dm.company_id = p.company_id
    )
  from me
  join public.profiles p
    on p.company_id = me.company_id
   and p.active
  left join public.departments d on d.id = p.department_id
  left join public.profiles m on m.id = p.manager_id
  order by p.full_name;
$$;


--
-- Name: get_replacement_candidates(date, date, public.leave_unit, time without time zone, time without time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_replacement_candidates(p_start date, p_end date, p_unit public.leave_unit DEFAULT 'day'::public.leave_unit, p_start_time time without time zone DEFAULT NULL::time without time zone, p_end_time time without time zone DEFAULT NULL::time without time zone) RETURNS TABLE(profile_id uuid, full_name text, employee_code text, unavailable boolean, unavailable_reason text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with me as (
    select id, company_id, department_id
      from public.profiles
     where id = auth.uid()
       and active
  )
  select
    p.id,
    p.full_name,
    p.employee_code,
    private.replacement_is_away(
      p.id, p_start, p_end, p_unit, p_start_time, p_end_time
    ) as unavailable,
    case
      when private.replacement_is_away(
        p.id, p_start, p_end, p_unit, p_start_time, p_end_time
      ) then 'on leave'
      else null
    end as unavailable_reason
  from me
  join public.profiles p
    on p.company_id = me.company_id
   and p.active
   and p.id <> me.id
   and ((me.department_id is not null and p.department_id = me.department_id)
        or private.delegate_eligible(me.id,p.id))
  order by p.full_name;
$$;


--
-- Name: jalali_months; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.jalali_months (
    jalali_year integer NOT NULL,
    jalali_month integer NOT NULL,
    gregorian_start date NOT NULL,
    gregorian_end date NOT NULL,
    CONSTRAINT jalali_months_jalali_month_check CHECK (((jalali_month >= 1) AND (jalali_month <= 12))),
    CONSTRAINT jalali_months_range CHECK ((gregorian_end >= gregorian_start))
);


--
-- Name: jalali_month_of(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.jalali_month_of(p_date date) RETURNS public.jalali_months
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare v_row public.jalali_months;
begin
  select * into v_row from public.jalali_months
   where p_date between gregorian_start and gregorian_end;
  if v_row is null then
    raise exception 'date outside supported calendar range' using errcode = '22023';
  end if;
  return v_row;
end; $$;


--
-- Name: reject_leave_request(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_leave_request(p_id uuid, p_reason text DEFAULT NULL::text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select public.reject_leave_request_v2(p_id,null,p_reason);
$$;


--
-- Name: reject_leave_request_v2(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_leave_request_v2(p_id uuid, p_step_id uuid, p_reason text DEFAULT NULL::text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.decide_approval_request(p_id,p_step_id,auth.uid(),'rejected',null,false,false,null,p_reason);
$$;


--
-- Name: request_approval_progress(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_approval_progress(p_id uuid) RETURNS TABLE(step_order integer, step_role public.app_role, manager_scope text, named boolean, expected_name text, decision public.leave_status, signer_name text, signed_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select (item->>'step_order')::integer,(item->>'step_role')::public.app_role,
    item->>'manager_scope',coalesce((item->>'named')::boolean,false),item->>'expected_name',
    (item->>'decision')::public.leave_status,item->>'signer_name',(item->>'signed_at')::timestamptz
  from jsonb_array_elements(public.app_request_approval_progress(p_id)) item;
$$;


--
-- Name: search_approver_candidates(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_approver_candidates(p_query text) RETURNS TABLE(id uuid, full_name text, personnel_no text, employee_code text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
  v_company uuid;
  v_q text := btrim(coalesce(p_query, ''));
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '28000';
  end if;
  if not private.has_perm(v_uid, 'approval_steps', 'edit') then
    raise exception 'admin or hr role required' using errcode = '42501';
  end if;

  select company_id into v_company from public.profiles where public.profiles.id = v_uid;

  return query
    select p.id, p.full_name, p.personnel_no, p.employee_code
      from public.profiles p
     where p.company_id = v_company
       and p.active
       and (
         v_q = ''
         or p.full_name ilike '%' || v_q || '%'
         or p.personnel_no ilike v_q || '%'
         or p.employee_code ilike v_q || '%'
       )
     order by p.full_name
     limit 20;
end;
$$;


--
-- Name: set_employee_leave_policy(uuid, uuid, integer, integer, integer, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_employee_leave_policy(p_employee_id uuid, p_leave_type_id uuid, p_accrual_minutes_per_month integer, p_annual_cap_minutes integer, p_carryover_cap_minutes integer, p_accrual_start_month date) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_id uuid;
begin
  -- FR-43, FR-55: admin, or leave_balances at Allowed. HR administers leave, so the
  -- two screens that set an opening balance and an accrual policy are theirs as well.
  if not (private.is_admin(auth.uid()) or private.has_perm(auth.uid(), 'leave_balances', 'edit')) then
    raise exception 'only admins or hr can set a leave policy' using errcode = '42501';
  end if;
  -- ...but nobody except an admin does it to THEMSELVES. Same asymmetry FR-36
  -- already applies to signing your own request: an admin is the owner and may,
  -- an HR officer granting themselves leave is an obvious control weakness.
  if not private.is_admin(auth.uid()) and p_employee_id = auth.uid() then
    raise exception 'you cannot change your own leave balance' using errcode = '42501';
  end if;
  -- FR-55 D4: and only on someone who holds nothing the caller lacks.
  if not private.is_admin(auth.uid()) and not private.can_act_on(auth.uid(), p_employee_id) then
    raise exception 'not allowed to change this employee''s leave' using errcode = '42501';
  end if;
  if p_accrual_minutes_per_month is null or p_accrual_minutes_per_month < 0 then
    raise exception 'accrual per month must be 0 or more' using errcode = '22023';
  end if;
  if p_carryover_cap_minutes is null or p_carryover_cap_minutes < 0 then
    raise exception 'carryover cap must be 0 or more' using errcode = '22023';
  end if;
  if p_annual_cap_minutes is not null and p_annual_cap_minutes < 0 then
    raise exception 'annual cap must be 0 or more' using errcode = '22023';
  end if;
  if not exists (select 1 from public.jalali_months where gregorian_start = p_accrual_start_month) then
    raise exception 'accrual start month must be a jalali month start' using errcode = '22023';
  end if;

  insert into public.employee_leave_policies as elp (
    employee_id, leave_type_id, accrual_minutes_per_month,
    annual_cap_minutes, carryover_cap_minutes, accrual_start_month, created_by
  ) values (
    p_employee_id, p_leave_type_id, p_accrual_minutes_per_month,
    p_annual_cap_minutes, p_carryover_cap_minutes, p_accrual_start_month, auth.uid()
  )
  on conflict (employee_id, leave_type_id) do update
     set accrual_minutes_per_month = excluded.accrual_minutes_per_month,
         annual_cap_minutes        = excluded.annual_cap_minutes,
         carryover_cap_minutes     = excluded.carryover_cap_minutes,
         accrual_start_month       = excluded.accrual_start_month
  returning elp.id into v_id;

  insert into public.audit_log(actor_id, action, entity, entity_id, after)
  values (auth.uid(), 'set_employee_leave_policy', 'employee_leave_policies', v_id,
          jsonb_build_object('employee_id', p_employee_id, 'leave_type_id', p_leave_type_id,
                             'accrual_minutes_per_month', p_accrual_minutes_per_month,
                             'annual_cap_minutes', p_annual_cap_minutes,
                             'carryover_cap_minutes', p_carryover_cap_minutes,
                             'accrual_start_month', p_accrual_start_month));
  return v_id;
end; $$;


--
-- Name: set_leave_balance(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_leave_balance(p_employee_id uuid, p_leave_type_id uuid, p_target_minutes integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_current int;
  v_ledger uuid;
begin
  -- FR-43, FR-55: admin, or leave_balances at Allowed. HR administers leave, so the
  -- two screens that set an opening balance and an accrual policy are theirs as well.
  if not (private.is_admin(auth.uid()) or private.has_perm(auth.uid(), 'leave_balances', 'edit')) then
    raise exception 'only admins or hr can set leave balance' using errcode = '42501';
  end if;
  -- ...but nobody except an admin does it to THEMSELVES. Same asymmetry FR-36
  -- already applies to signing your own request: an admin is the owner and may,
  -- an HR officer granting themselves leave is an obvious control weakness.
  if not private.is_admin(auth.uid()) and p_employee_id = auth.uid() then
    raise exception 'you cannot change your own leave balance' using errcode = '42501';
  end if;
  -- FR-55 D4: and only on someone who holds nothing the caller lacks.
  if not private.is_admin(auth.uid()) and not private.can_act_on(auth.uid(), p_employee_id) then
    raise exception 'not allowed to change this employee''s leave' using errcode = '42501';
  end if;

  -- FR-48: a balance may be negative (leave taken in advance). Bounded at one
  -- year of workdays below zero so a typo cannot post an absurd debit.
  if p_target_minutes is null
     or p_target_minutes < -366 * private.company_minutes_per_day(
          (select company_id from public.profiles where id = p_employee_id)) then
    raise exception 'target balance is out of range' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('leave:' || p_employee_id::text, 0));

  v_current := public.current_leave_balance(p_employee_id, p_leave_type_id);

  if v_current = p_target_minutes then
    return p_target_minutes;
  end if;

  insert into public.leave_ledger(employee_id, leave_type_id, entry_type, delta_minutes, balance_after_minutes, note)
  values (p_employee_id, p_leave_type_id, 'adjustment', p_target_minutes - v_current, p_target_minutes, 'admin balance set')
  returning id into v_ledger;

  insert into public.audit_log(actor_id, action, entity, entity_id, after)
  values (auth.uid(), 'set_leave_balance', 'leave_ledger', v_ledger,
          jsonb_build_object('employee_id', p_employee_id, 'leave_type_id', p_leave_type_id,
                             'previous_minutes', v_current, 'target_minutes', p_target_minutes));

  return p_target_minutes;
end; $$;


