--
-- Name: leave_request_approvals; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.leave_request_approvals (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    request_id uuid NOT NULL,
    step_role public.app_role NOT NULL,
    approver_id uuid,
    decision public.leave_status NOT NULL,
    signature_data text,
    signature_consent_at timestamp with time zone,
    note text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    step_id uuid,
    evidence_kind text DEFAULT 'legacy'::text NOT NULL,
    principal_id uuid,
    principal_name text,
    signer_name_snapshot text,
    authority_id uuid,
    evidence jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT leave_approval_automatic_shape CHECK (((evidence_kind <> 'automatic'::text) OR ((approver_id IS NULL) AND (signature_data IS NULL) AND (signature_consent_at IS NULL) AND (principal_id IS NOT NULL) AND (authority_id IS NOT NULL) AND (step_id IS NOT NULL)))),
    CONSTRAINT leave_approval_evidence_kind CHECK ((evidence_kind = ANY (ARRAY['legacy'::text, 'manual'::text, 'delegated'::text, 'automatic'::text]))),
    CONSTRAINT leave_request_approvals_decision CHECK ((decision = ANY (ARRAY['approved'::public.leave_status, 'rejected'::public.leave_status]))),
    CONSTRAINT leave_request_approvals_note_len CHECK (((note IS NULL) OR (length(note) <= 500))),
    CONSTRAINT leave_request_approvals_signature_shape CHECK ((((signature_data IS NULL) AND (signature_consent_at IS NULL)) OR ((signature_data IS NOT NULL) AND (signature_consent_at IS NOT NULL) AND ((length(signature_data) >= 100) AND (length(signature_data) <= 350000)) AND (mod(length(signature_data), 4) = 2) AND (signature_data ~ '^data:image/png;base64,iVBORw0KGgo[A-Za-z0-9+/]*={0,2}$'::text)))),
    CONSTRAINT leave_request_approvals_signed_when_approved CHECK (((decision = 'approved'::public.leave_status) OR ((decision = 'rejected'::public.leave_status) AND (signature_data IS NULL))))
);


--
-- Name: TABLE leave_request_approvals; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.leave_request_approvals IS 'FR-36: one signed decision per (request, step). The request itself stays pending until every active applicable step has an approved row.';


--
-- Name: COLUMN leave_request_approvals.step_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.leave_request_approvals.step_id IS 'FR-42: which approval_steps row this evidence fills. NULL for rows written before FR-42, which key on step_role. Deliberately NOT a foreign key — recorded evidence must survive the step being reordered or deleted.';


