COMMENT ON TABLE public.special_leave_grants IS 'FR-65: extra annual-leave days for a first marriage (once) or a close relative''s death (each). Written only by app_grant_special_leave / app_revoke_special_leave.';


--
-- Name: team_leave_calendar; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.team_leave_calendar AS
 SELECT lr.id,
    lr.employee_id,
    p.full_name AS employee_name,
    p.department_id,
    lr.kind,
    lr.leave_type_id,
    lt.name_fa AS leave_type_name_fa,
    lt.name_en AS leave_type_name_en,
    lt.color AS leave_type_color,
    lr.start_date,
    lr.end_date,
    lr.day_part,
    lr.unit,
    lr.start_time,
    lr.end_time,
    lr.requested_minutes,
    lr.status
   FROM ((public.leave_requests lr
     JOIN public.profiles p ON ((p.id = lr.employee_id)))
     LEFT JOIN public.leave_types lt ON ((lt.id = lr.leave_type_id)))
  WHERE (private.is_active(auth.uid()) AND (lr.status = ANY (ARRAY['pending'::public.leave_status, 'approved'::public.leave_status])) AND ((lr.employee_id = auth.uid()) OR private.same_team(auth.uid(), lr.employee_id) OR private.reads_calendar(auth.uid())));


